(window.VesperCadastros = window.VesperCadastros || {}).species = {"from":"5etools","generatedAt":"2026-11-23","sources":{"AAG":"Astral Adventurer's Guide","AI":"Acquisitions Incorporated","AWM":"Adventure with Muk","DMG":"Dungeon Master's Guide (2014)","DSotDQ":"Dragonlance: Shadow of the Dragon Queen","EEPC":"Elemental Evil Player's Companion","EFA":"Eberron: Forge of the Artificer","EGW":"Explorer's Guide to Wildemount","ERLW":"Eberron: Rising from the Last War","FTD":"Fizban's Treasury of Dragons","GGR":"Guildmasters' Guide to Ravnica","LFL":"Lorwyn: First Light","LR":"Locathah Rising","MOT":"Mythic Odysseys of Theros","MPMM":"Mordenkainen Presents: Monsters of the Multiverse","MTF":"Mordenkainen's Tome of Foes","OGA":"One Grung Above","PHB":"Player's Handbook (2014)","PSA":"Plane Shift: Amonkhet","PSD":"Plane Shift: Dominaria","PSI":"Plane Shift: Innistrad","PSK":"Plane Shift: Kaladesh","PSX":"Plane Shift: Ixalan","PSZ":"Plane Shift: Zendikar","RHW":"Ravenloft: The Horrors Within","SCC":"Strixhaven: A Curriculum of Chaos","TCE":"Tasha's Cauldron of Everything","TTP":"The Tortle Package","VGM":"Volo's Guide to Monsters","VRGR":"Van Richten's Guide to Ravenloft","WBtW":"The Wild Beyond the Witchlight","XPHB":"Player's Handbook (2024)"},"species":[{"id":"aarakocra-dmg","name":"Aarakocra","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":6,"fly":15},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":2}}],"proficiencies":[{"kind":"language","fixed":["auran"]}]},"feats":[],"traits":[{"name":"Dive Attack","text":"If you are flying and dive at least 30 ft. straight toward a target and then hit it with a melee weapon attack, the attack deals an extra 1d6 damage to the target."},{"name":"Talons","text":"You are proficient with your unarmed strikes, which deal 1d4 slashing damage on a hit."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"aarakocra-eepc","name":"Aarakocra","source":"EEPC","page":5,"edition":"","size":["Medium"],"speed":{"walk":7.5,"fly":15},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"proficiencies":[{"kind":"language","fixed":["common","other","auran"]}]},"feats":[],"traits":[{"name":"Flight","text":"You have a flying speed of 50 feet. To use this speed, you can't be wearing medium or heavy armor."},{"name":"Talons","text":"Your talons are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}],"lineage":"","age":{"mature":3,"max":30},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EEPC/Aarakocra.webp"]},{"id":"aarakocra-mpmm","name":"Aarakocra","source":"MPMM","page":5,"edition":"2014","size":["Medium"],"speed":{"walk":9,"fly":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"gust-of-wind-phb","name":"Gust of Wind","how":"innate","uses":"","at":"3"}]}]}},"feats":[],"traits":[{"name":"Flight","text":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."},{"name":"Talons","text":"You have talons that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Wind Caller","text":"Starting at 3rd level, you can cast the gust of wind spell with this trait, without requiring a material component. Once you cast the spell with this trait, you can't do so again until you finish a long rest. You can also cast the spell using any spell slots you have of 2nd level or higher.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for when you cast gust of wind with this trait (choose when you select this race)."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Aarakocra.webp"]},{"id":"aasimar-dmg","name":"Aasimar","source":"DMG","page":286,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"wis":1,"cha":2}}],"proficiencies":[{"kind":"language","fixed":["common","celestial"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"light-phb","name":"Light","how":"known","uses":"","at":"1"},{"spell":"lesser-restoration-phb","name":"Lesser Restoration","how":"innate","uses":"1/day","at":"3"},{"spell":"daylight-phb","name":"Daylight","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["necrotic","radiant"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Thanks to your celestial heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of grey."},{"name":"Celestial Resistance","text":"You have resistance to necrotic and radiant damage."},{"name":"Celestial Legacy","text":"You know the light cantrip. Once you reach 3rd level, you can cast the lesser restoration spell once with this trait, and you regain the ability to do so when you finish a long rest. Once you reach 5th level, you can cast the daylight spell once with this trait, and you regain the ability to do so when you finish a long rest. Charisma is your spellcasting ability for these spells."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[],"description":""},{"id":"aasimar-mpmm","name":"Aasimar","source":"MPMM","page":7,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"light-phb","name":"Light","how":"known","uses":"","at":"1"}]}]},"resist":{"fixed":["necrotic","radiant"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Celestial Resistance","text":"You have resistance to necrotic damage and radiant damage."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Healing Hands","text":"As an action, you can touch a creature and roll a number of d4s equal to your proficiency bonus. The creature regains a number of hit points equal to the total rolled. Once you use this trait, you can't use it again until you finish a long rest."},{"name":"Light Bearer","text":"You know the light cantrip. Charisma is your spellcasting ability for it."},{"name":"Celestial Revelation","text":"When you reach 3rd level, choose one of the revelation options below. Thereafter, you can use a bonus action to unleash the celestial energy within yourself, gaining the benefits of that revelation. Your transformation lasts for 1 minute or until you end it as a bonus action. Once you transform using your revelation below, you can't use it again until you finish a long rest.\n\n• Necrotic Shroud Your eyes briefly become pools of darkness, and ghostly, flightless wings sprout from your back temporarily. Creatures other than your allies within 10 feet of you that can see you must succeed on a Charisma saving throw (DC 8 + your proficiency bonus + your Charisma modifier) or become frightened of you until the end of your next turn. Until the transformation ends, once on each of your turns, you can deal extra necrotic damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus.\n• Radiant Consumption Searing light temporarily radiates from your eyes and mouth. For the duration, you shed bright light in a 10-foot radius and dim light for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes radiant damage equal to your proficiency bonus. Until the transformation ends, once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus.\n• Radiant Soul Two luminous, spectral wings sprout from your back temporarily. Until the transformation ends, you have a flying speed equal to your walking speed, and once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."}],"lineage":"VRGR","age":{"mature":null,"max":180},"heightWeight":null,"options":[{"id":"aasimar-mpmm--necrotic-shroud","name":"Necrotic Shroud","kind":"lineage","source":"MPMM","page":7,"traits":[{"name":"Celestial Revelation (Necrotic Shroud)","text":"When you reach 3rd level, you can use a bonus action to transform yourself. Your transformation lasts for 1 minute or until you end it as a bonus action. Once you transform using your revelation, you can't use it again until you finish a long rest.\n\nYour eyes briefly become pools of darkness, and ghostly, flightless wings sprout from your back temporarily. Creatures other than your allies within 10 feet of you that can see you must succeed on a Charisma saving throw (DC 8 + your proficiency bonus + your Charisma modifier) or become frightened of you until the end of your next turn. Until the transformation ends, once on each of your turns, you can deal extra necrotic damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."}],"removes":["Celestial Revelation"]},{"id":"aasimar-mpmm--radiant-consumption","name":"Radiant Consumption","kind":"lineage","source":"MPMM","page":7,"traits":[{"name":"Celestial Revelation (Radiant Consumption)","text":"When you reach 3rd level, you can use a bonus action to transform yourself. Your transformation lasts for 1 minute or until you end it as a bonus action. Once you transform using your revelation, you can't use it again until you finish a long rest.\n\nSearing light temporarily radiates from your eyes and mouth. For the duration, you shed bright light in a 10-foot radius and dim light for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes radiant damage equal to your proficiency bonus. Until the transformation ends, once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."}],"removes":["Celestial Revelation"]},{"id":"aasimar-mpmm--radiant-soul","name":"Radiant Soul","kind":"lineage","source":"MPMM","page":7,"traits":[{"name":"Celestial Revelation (Radiant Soul)","text":"When you reach 3rd level, you can use a bonus action to transform yourself. Your transformation lasts for 1 minute or until you end it as a bonus action. Once you transform using your revelation, you can't use it again until you finish a long rest.\n\nTwo luminous, spectral wings sprout from your back temporarily. Until the transformation ends, you have a flying speed equal to your walking speed, and once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your proficiency bonus."}],"removes":["Celestial Revelation"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Aasimar.webp"]},{"id":"aasimar-vgm","name":"Aasimar","source":"VGM","page":104,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":2}}],"proficiencies":[{"kind":"language","fixed":["common","celestial"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"light-phb","name":"Light","how":"known","uses":"","at":"1"}]}]},"resist":{"fixed":["necrotic","radiant"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Blessed with a radiant soul, your vision can easily cut through darkness. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Celestial Resistance","text":"You have resistance to necrotic damage and radiant damage."},{"name":"Healing Hands","text":"As an action, you can touch a creature and cause it to regain a number of hit points equal to your level. Once you use this trait, you can't use it again until you finish a long rest."},{"name":"Light Bearer","text":"You know the light cantrip. Charisma is your spellcasting ability for it."}],"lineage":"","age":{"mature":20,"max":160},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[{"id":"aasimar-vgm--fallen","name":"Fallen","kind":"subrace","source":"VGM","page":105,"traits":[{"name":"Necrotic Shroud","text":"Starting at 3rd level, you can use your action to unleash the divine energy within yourself, causing your eyes to turn into pools of darkness and two skeletal, ghostly, flightless wings to sprout from your back. The instant you transform, other creatures within 10 feet of you that can see you must succeed on a Charisma saving throw (DC 8 + your proficiency bonus + your Charisma modifier) or become frightened of you until the end of your next turn.\n\nYour transformation lasts for 1 minute or until you end it as a bonus action. During it, once on each of your turns, you can deal extra necrotic damage to one target when you deal damage to it with an attack or a spell. The extra necrotic damage equals your level.\n\nOnce you use this trait, you can't use it again until you finish a long rest."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":2,"str":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Aasimar.webp"]},{"id":"aasimar-vgm--protector","name":"Protector","kind":"subrace","source":"VGM","page":105,"traits":[{"name":"Radiant Soul","text":"Starting at 3rd level, you can use your action to unleash the divine energy within yourself, causing your eyes to glimmer and two luminous, incorporeal wings to sprout from your back.\n\nYour transformation lasts for 1 minute or until you end it as a bonus action. During it, you have a flying speed of 30 feet, and once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra radiant damage equals your level.\n\nOnce you use this trait, you can't use it again until you finish a long rest."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":2,"wis":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Aasimar.webp"]},{"id":"aasimar-vgm--scourge","name":"Scourge","kind":"subrace","source":"VGM","page":105,"traits":[{"name":"Radiant Consumption","text":"Starting at 3rd level, you can use your action to unleash the divine energy within yourself, causing a searing light to radiate from you, pour out of your eyes and mouth, and threaten to char you.\n\nYour transformation lasts for 1 minute or until you end it as a bonus action. During it, you shed bright light in a 10-foot radius and dim light for an additional 10 feet, and at the end of each of your turns, you and each creature within 10 feet of you take radiant damage equal to half your level (rounded up). In addition, once on each of your turns, you can deal extra radiant damage to one target when you deal damage to it with an attack or a spell. The extra radiant damage equals your level.\n\nOnce you use this trait, you can't use it again until you finish a long rest."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":2,"con":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Aasimar.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Aasimar.webp"]},{"id":"aasimar-xphb","name":"Aasimar","source":"XPHB","page":186,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"light-xphb","name":"Light","how":"known","uses":"","at":"1"}]}]},"resist":{"fixed":["necrotic","radiant"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Celestial Resistance","text":"You have Resistance to Necrotic damage and Radiant damage."},{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Healing Hands","text":"As a Magic action, you touch a creature and roll a number of d4s equal to your Proficiency Bonus. The creature regains a number of Hit Points equal to the total rolled. Once you use this trait, you can't use it again until you finish a Long Rest."},{"name":"Light Bearer","text":"You know the Light cantrip. Charisma is your spellcasting ability for it."},{"name":"Celestial Revelation","text":"When you reach character level 3, you can transform as a Bonus Action using one of the options below (choose the option each time you transform). The transformation lasts for 1 minute or until you end it (no action required). Once you transform, you can't do so again until you finish a Long Rest.\n\nOnce on each of your turns before the transformation ends, you can deal extra damage to one target when you deal damage to it with an attack or a spell. The extra damage equals your Proficiency Bonus, and the extra damage's type is either Necrotic for Necrotic Shroud or Radiant for Heavenly Wings and Inner Radiance.\n\nHere are the transformation options:\n\n• Heavenly Wings Two spectral wings sprout from your back temporarily. Until the transformation ends, you have a Fly Speed equal to your Speed.\n• Inner Radiance Searing light temporarily radiates from your eyes and mouth. For the duration, you shed Bright Light in a 10-foot radius and Dim Light for an additional 10 feet, and at the end of each of your turns, each creature within 10 feet of you takes Radiant damage equal to your Proficiency Bonus.\n• Necrotic Shroud Your eyes briefly become pools of darkness, and flightless wings sprout from your back temporarily. Creatures other than your allies within 10 feet of you must succeed on a Charisma saving throw (DC 8 plus your Charisma modifier and Proficiency Bonus) or have the Frightened condition until the end of your next turn."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Aasimar.webp"]},{"id":"aetherborn-psk","name":"Aetherborn","source":"PSK","page":17,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":2},"choose":{"from":["str","dex","con","int","wis"],"count":2,"amount":1}}],"proficiencies":[{"kind":"skill","fixed":["intimidation"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":2}}],"resist":{"fixed":["necrotic"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Born of Aether","text":"You have resistance to necrotic damage."},{"name":"Menacing","text":"You have proficiency in the Intimidation skill."},{"name":"Gift of the Aetherborn","text":"An unknown aetherborn, desperately seeking a means to extend their short life, discovered a process of transformation that prolonged their existence—by giving them the ability to feed on the life essence of other beings. Since then, other aetherborn have learned and carried out this monstrous transformation, and aetherborn with this \"gift\" have become a small minority among an already small population.\n\nA gifted aetherborn has the ability to drain the life essence of other beings. Similar to the way heat is transferred from a warm object to a cold one, a gifted aetherborn need only touch another living being with a clawed hand to draw life essence out, fueling their own continued existence while draining strength and vitality from their victim.\n\nFor many aetherborn, living as they do for indulgence and instant gratification, the concepts of \"want\" and \"need\" are virtually synonymous. But Aetherborn with this gift understand what it is to truly need, for they develop a hunger for life essence that far exceeds any desires they might have felt before their transformation. A gifted aetherborn who abstains from this feeding deteriorates even more rapidly than other aetherborn, while enduring unspeakable agony caused by the deprivation of life energy.\n\nAt the DM's option, an aetherborn character can research methods of achieving this dark \"gift.\" The process is similar to inventing and manufacturing a rare magic item (see \"1\" earlier in this document). But rather than aether, the process requires a variety of rare unguents and unusual ingredients that make up the cost of researching and undergoing the transformation.\n\nAn aetherborn with this gift gains the Drain Life ability: a natural attack that deals 1d6 necrotic damage and restores the same number of hit points to the aetherborn. However, if the aetherborn goes for 7 days without dealing this damage, their hit point maximum is reduced by 1d6 per week. This reduction can't be removed until the aetherborn has used their Drain Life ability and completed a long rest."}],"lineage":"","age":{"mature":null,"max":3},"heightWeight":null,"options":[{"id":"aetherborn-psk--gifted-aetherborn","name":"Gifted Aetherborn","kind":"lineage","source":"PSK","page":17,"traits":[{"name":"Drain Life","text":"You gain a natural attack that deals 1d6 necrotic damage and restores the same number of hit points to you. However, if you goes for 7 days without dealing this damage, your hit point maximum is reduced by 1d6 per week. This reduction can't be removed until you have used your Drain Life ability and completed a long rest."}],"removes":[]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Aetherborn.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Aetherborn2.webp"]},{"id":"astral-elf-aag","name":"Astral Elf","source":"AAG","page":10,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"dancing-lights-phb","name":"Dancing Lights","how":"known","uses":"","at":"1"}]},{"name":"","items":[{"spell":"light-phb","name":"Light","how":"known","uses":"","at":"1"}]},{"name":"","items":[{"spell":"sacred-flame-phb","name":"Sacred Flame","how":"known","uses":"","at":"1"}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Astral Fire","text":"You know one of the following cantrips of your choice: dancing lights, light, or sacred flame. Intelligence, Wisdom, or Charisma is your spellcasting ability for it (choose when you select this race)."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of yourself as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Starlight Step","text":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Astral Trance","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you remain conscious.\n\nWhenever you finish this trance, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory and the experiences of entities on the Astral Plane, and you retain them until you finish your next long rest."}],"lineage":"VRGR","age":{"mature":null,"max":750},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AAG/Astral%20Elf.webp"]},{"id":"autognome-aag","name":"Autognome","source":"AAG","page":11,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":["construct"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"tool","any":{"any":2}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["poison"]},"conditionImmune":{"fixed":["disease"]}},"feats":[],"traits":[{"name":"Armored Casing","text":"You are encased in thin metal or some other durable material. While you aren't wearing armor, your base Armor Class is 13 + your Dexterity modifier."},{"name":"Built for Success","text":"You can add a d4 to one attack roll, ability check, or saving throw you make, and you can do so after seeing the d20 roll but before the effects of the roll are resolved. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Healing Machine","text":"If the mending spell is cast on you, you can spend a Hit Die, roll it, and regain a number of hit points equal to the roll plus your Constitution modifier (minimum of 1 hit point).\n\nIn addition, your creator designed you to benefit from several spells that preserve life but that normally don't affect Constructs: cure wounds, healing word, mass cure wounds, mass healing word, and spare the dying."},{"name":"Mechanical Nature","text":"You have resistance to poison damage and immunity to disease, and you have advantage on saving throws against being paralyzed or poisoned. You don't need to eat, drink, or breathe."},{"name":"Sentry's Rest","text":"When you take a long rest, you spend at least 6 hours in an inactive, motionless state, instead of sleeping. In this state, you appear inert, but you remain conscious."},{"name":"Specialized Design","text":"You gain two tool proficiencies of your choice, selected from the Player's Handbook."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AAG/Autognome.webp"]},{"id":"aven-psa","name":"Aven","source":"PSA","page":15,"edition":"","size":["Medium"],"speed":{"walk":7.5,"fly":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Flight","text":"You have a flying speed of 30 feet. You can't use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can't use your flying speed if you are encumbered.)"}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[{"id":"aven-psa--hawk-headed","name":"Hawk-Headed","kind":"subrace","source":"PSA","page":16,"traits":[{"name":"Hawkeyed","text":"You have proficiency in the Perception skill. In addition, attacking at long range doesn't impose disadvantage on your ranged weapon attack rolls."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":2}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","other"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven2.webp"]},{"id":"aven-psa--ibis-headed","name":"Ibis-Headed","kind":"subrace","source":"PSA","page":16,"traits":[{"name":"Kefnet's Blessing","text":"You can add half your proficiency bonus, rounded down, to any Intelligence check you make that doesn't already include your proficiency bonus."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"int":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven%20(Ibis-Headed).webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Aven2.webp"]},{"id":"aven-psd","name":"Aven","source":"PSD","page":6,"edition":"","size":["Medium"],"speed":{"walk":7.5,"fly":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":2}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Flight","text":"You have a flying speed of 30 feet. You can't use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can't use your flying speed if you are encumbered.)"},{"name":"Hawkeyed","text":"You have proficiency in the Perception skill. In addition, attacking at long range doesn't impose disadvantage on your ranged weapon attack rolls."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSD/Aven.webp"]},{"id":"boggart-lfl","name":"Boggart","source":"LFL","page":null,"edition":"2024","size":["Small"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Fury of the Small","text":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your proficiency bonus.\n\nYou can use this trait a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest, and you can use it no more than once per turn."},{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Boggart.webp"]},{"id":"bugbear-erlw","name":"Bugbear","source":"ERLW","page":25,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"dex":1}}],"proficiencies":[{"kind":"skill","fixed":["stealth"]},{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Long-Limbed","text":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Sneaky","text":"You are proficient in the Stealth skill."},{"name":"Surprise Attack","text":"If you surprise a creature and hit it with an attack on your first turn in combat, the attack deals an extra 2d6 damage to it. You can use this trait only once per combat."}],"lineage":"","age":{"mature":16,"max":80},"heightWeight":{"baseHeight":72,"heightMod":"2d12","baseWeight":200,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Goblinoids.webp"]},{"id":"bugbear-mpmm","name":"Bugbear","source":"MPMM","page":8,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["stealth"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Long-Limbed","text":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Sneaky","text":"You are proficient in the Stealth skill. In addition, without squeezing, you can move through and stop in a space large enough for a Small creature."},{"name":"Surprise Attack","text":"If you hit a creature with an attack roll, the creature takes an extra 2d6 damage if it hasn't taken a turn yet in the current combat."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Bugbear.webp"]},{"id":"bugbear-vgm","name":"Bugbear","source":"VGM","page":119,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"dex":1}}],"proficiencies":[{"kind":"skill","fixed":["stealth"]},{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Long-Limbed","text":"When you make a melee attack on your turn, your reach for it is 5 feet greater than normal."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Sneaky","text":"You are proficient in the Stealth skill."},{"name":"Surprise Attack","text":"If you surprise a creature and hit it with an attack on your first turn in combat, the attack deals an extra 2d6 damage to it. You can use this trait only once per combat."}],"lineage":"","age":{"mature":16,"max":80},"heightWeight":{"baseHeight":72,"heightMod":"2d12","baseWeight":200,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Bugbear.webp"]},{"id":"bullywug-dmg","name":"Bullywug","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":6,"swim":12},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":-2,"cha":-2}}],"proficiencies":[{"kind":"language","fixed":["other"]}]},"feats":[],"traits":[{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Speak with Frogs and Toads","text":"You can communicate simple concepts to frogs and toads when you speak in Bullywug."},{"name":"Swamp Camouflage","text":"You have advantage on Dexterity (Stealth) checks made to hide in swampy terrain."},{"name":"Standing Leap","text":"Your long jump is up to 20 feet and your high jump is up to 10 feet, with or without a running start."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"centaur-ggr","name":"Centaur","source":"GGR","page":15,"edition":"2014","size":["Medium"],"speed":{"walk":12},"creatureTypes":["fey"],"benefits":{"ability":[{"fixed":{"str":2,"wis":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","medicine","nature","survival"],"count":1}},{"kind":"language","fixed":["common","sylvan"]}]},"feats":[],"traits":[{"name":"Fey","text":"Your creature type is fey, rather than humanoid."},{"name":"Charge","text":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."},{"name":"Hooves","text":"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Equine Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push or drag.\n\nIn addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."},{"name":"Survivor","text":"You have proficiency in one of the following skills of your choice: Animal Handling, Medicine, Nature, or Survival."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":72,"heightMod":"1d10","baseWeight":600,"weightMod":"2d12"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/GGR/Centaur.webp"]},{"id":"centaur-mot","name":"Centaur","source":"MOT","page":18,"edition":"2014","size":["Medium"],"speed":{"walk":12},"creatureTypes":["fey"],"benefits":{"ability":[{"fixed":{"str":2,"wis":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","medicine","nature","survival"],"count":1}},{"kind":"language","fixed":["common","sylvan"]}]},"feats":[],"traits":[{"name":"Fey","text":"Your creature type is fey, rather than humanoid."},{"name":"Charge","text":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."},{"name":"Hooves","text":"Your hooves are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Equine Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push or drag.\n\nIn addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet, instead of the normal 1 extra foot."},{"name":"Survivor","text":"You have proficiency in one of the following skills of your choice: Animal Handling, Medicine, Nature, or Survival."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":72,"heightMod":"1d10","baseWeight":600,"weightMod":"2d12"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Lagonna%20Band%20Centaur.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Pheres%20Band%20Centaur.webp"]},{"id":"centaur-mpmm","name":"Centaur","source":"MPMM","page":9,"edition":"2014","size":["Medium"],"speed":{"walk":12},"creatureTypes":["fey"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","medicine","nature","survival"],"count":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Charge","text":"If you move at least 30 feet straight toward a target and then hit it with a melee weapon attack on the same turn, you can immediately follow that attack with a bonus action, making one attack against the target with your hooves."},{"name":"Equine Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push or drag.\n\nIn addition, any climb that requires hands and feet is especially difficult for you because of your equine legs. When you make such a climb, each foot of movement costs you 4 extra feet instead of the normal 1 extra foot."},{"name":"Hooves","text":"You have hooves that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Natural Affinity","text":"Your fey connection to nature gives you an intuitive connection to the natural world and the animals within it. You therefore have proficiency in one of the following skills of your choice: Animal Handling, Medicine, Nature, or Survival."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Centaur.webp"]},{"id":"changeling-efa","name":"Changeling","source":"EFA","page":34,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["fey"],"benefits":{"proficiencies":[{"kind":"skill","choose":{"from":["deception","insight","intimidation","performance","persuasion"],"count":2}}]},"feats":[],"traits":[{"name":"Changeling Instincts","text":"Thanks to your connection to the fey realm, you gain proficiency in two of the following skills of your choice: Deception, Insight, Intimidation, Performance, or Persuasion."},{"name":"Shape-Shifter","text":"As an action, you can shape-shift to change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height and weight and can change your size between Medium and Small. You can make yourself appear as a member of another playable species, though none of your game statistics change. You can't duplicate the appearance of an individual you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. This trait doesn't change your clothing and equipment.\n\nWhile shape-shifted with this trait, you have Advantage on Charisma checks.\n\nYou stay in the new form until you take an action to revert to your true form."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EFA/Changeling.webp"]},{"id":"changeling-erlw","name":"Changeling","source":"ERLW","page":17,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":2},"choose":{"from":["str","dex","con","int","wis"],"count":1,"amount":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["deception","insight","intimidation","persuasion"],"count":2}},{"kind":"language","fixed":["common"],"any":{"anyStandard":2}}]},"feats":[],"traits":[{"name":"Shapechanger","text":"As an action, you can change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height and weight, but not so much that your size changes. You can make yourself appear as a member of another race, though none of your game statistics change. You can't duplicate the appearance of a creature you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. Your clothing and equipment aren't changed by this trait.\n\nYou stay in the new form until you use an action to revert to your true form or until you die."},{"name":"Changeling Instincts","text":"You gain proficiency with two of the following skills of your choice: Deception, Insight, Intimidation, and Persuasion."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":61,"heightMod":"2d4","baseWeight":115,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Changeling.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Changeling%20001.webp"]},{"id":"changeling-mpmm","name":"Changeling","source":"MPMM","page":10,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["fey"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["deception","insight","intimidation","performance","persuasion"],"count":2}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Changeling Instincts","text":"Thanks to your connection to the fey realm, you gain proficiency with two of the following skills of your choice: Deception, Insight, Intimidation, Performance, or Persuasion."},{"name":"Shapechanger","text":"As an action, you change your appearance and your voice. You determine the specifics of the changes, including your coloration, hair length, and sex. You can also adjust your height between Medium and Small. You can make yourself appear as a member of another race, though none of your game statistics change. You can't duplicate the appearance of an individual you've never seen, and you must adopt a form that has the same basic arrangement of limbs that you have. Your clothing and equipment aren't changed by this trait.\n\nYou stay in the new form until you use an action to revert to your true form or until you die."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Changeling.webp"]},{"id":"custom-lineage-tce","name":"Custom Lineage","source":"TCE","page":8,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"choose":{"from":["str","dex","con","int","wis","cha"],"count":1,"amount":2}}],"proficiencies":[{"kind":"skill","any":{"any":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[{"any":true,"count":1}],"traits":[{"name":"Feat","text":"You gain one feat of your choice for which you qualify."},{"name":"Variable Trait","text":"You gain one of the following options of your choice: (a) darkvision with a range of 60 feet or (b) proficiency in one skill of your choice."}],"lineage":"true","age":null,"heightWeight":null,"options":[{"id":"custom-lineage-tce--darkvision","name":"Darkvision","kind":"lineage","source":"TCE","page":8,"traits":[{"name":"Variable Trait; Darkvision","text":"You gain darkvision with a range of 60 feet."}],"removes":["Variable Trait"],"benefits":{"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]}},{"id":"custom-lineage-tce--skill-proficiency","name":"Skill Proficiency","kind":"lineage","source":"TCE","page":8,"traits":[{"name":"Variable Trait; Skill Proficiency","text":"You gain proficiency in one skill of your choice."}],"removes":["Variable Trait"]}],"description":"Instead of choosing one of the game's races for your character at 1st level, you can use the following traits to represent your character's lineage, giving you full control over how your character's origin shaped them:\n\nYour race is considered to be a Custom Lineage for any game feature that requires a certain race, such as elf or dwarf."},{"id":"deep-gnome-mpmm","name":"Deep Gnome","source":"MPMM","page":11,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"disguise-self-phb","name":"Disguise Self","how":"innate","uses":"1/day","at":"3"},{"spell":"nondetection-phb","name":"Nondetection","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Gift of the Svirfneblin","text":"Starting at 3rd level, you can cast the disguise self spell with this trait. Starting at 5th level, you can also cast the nondetection spell with it, without requiring a material component. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these using spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"name":"Gnomish Magic Resistance","text":"You have advantage on Intelligence, Wisdom, and Charisma saving throws against spells."},{"name":"Svirfneblin Camouflage","text":"When you make a Dexterity (Stealth) check, you can make the check with advantage. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":{"mature":null,"max":500},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Deep%20Gnome.webp"]},{"id":"dhampir-rhw","name":"Dhampir","source":"RHW","page":28,"edition":"2024","size":["Small","Medium"],"speed":{"walk":10.5,"climb":"walk"},"creatureTypes":[],"benefits":{"resist":{"fixed":["necrotic"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Spider Climb","text":"You have a Climb Speed equal to your Speed. When you reach character level 3, you can move up, down, and across vertical surfaces and along ceilings while leaving your hands free."},{"name":"Trace of Undeath","text":"You have Resistance to Necrotic damage."},{"name":"Vampiric Bite","text":"When you use your Unarmed Strike and deal damage, you can choose to bite with your fangs. You deal Piercing damage equal to 1d4 plus your Constitution modifier instead of the normal damage of an Unarmed Strike.\n\nIn addition, when you deal this damage to a creature that isn't a Construct or an Undead, you can empower yourself in one of the following ways:\n\n• Drain You regain Hit Points equal to the Piercing damage dealt.\n• Strengthen You gain a bonus to the next ability check or attack roll you make within the next minute; the bonus is equal to the Piercing damage dealt.\n\nYou can empower yourself with this trait a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/RHW/Dhampir.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/RHW/Dhampir%202.webp"]},{"id":"dhampir-vrgr","name":"Dhampir","source":"VRGR","page":16,"edition":"2014","size":["Small","Medium"],"speed":{"walk":10.5,"climb":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Ancestral Legacy","text":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it.\n\nIf you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness as shades of gray."},{"name":"Deathless Nature","text":"You don't need to breathe."},{"name":"Spider Climb","text":"You have a climbing speed equal to your walking speed. In addition, at 3rd level, you can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free."},{"name":"Vampiric Bite","text":"Your fanged bite is a natural weapon, which counts as a simple melee weapon with which you are proficient. You add your Constitution modifier, instead of your Strength modifier, to the attack and damage rolls when you attack with this bite. It deals 1d4 piercing damage on a hit. While you are missing half or more of your hit points, you have advantage on attack rolls you make with this bite.\n\nWhen you attack with this bite and hit a creature that isn't a Construct or an Undead, you can empower yourself in one of the following ways of your choice:\n\n• You regain hit points equal to the piercing damage dealt by the bite.\n• You gain a bonus to the next ability check or attack roll you make; the bonus equals the piercing damage dealt by the bite\n\nYou can empower yourself with this bite a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VRGR/Dhampir.webp"]},{"id":"dragonborn-base-phb","name":"Dragonborn (Base)","source":"PHB","page":32,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common","draconic"]}],"resist":{"fixed":[],"choose":{"from":["acid","cold","fire","lightning","poison"],"count":1}}},"feats":[],"traits":[{"name":"Draconic Ancestry","text":"You have draconic ancestry. Choose one type of dragon from the Draconic Ancestry table. Your breath weapon and damage resistance are determined by the dragon type, as shown in the table.\n\nDraconic Ancestry:\n| Dragon | Damage Type | Breath Weapon |\n| Black | Acid | 5 by 30 ft. line (Dex. save) |\n| Blue | Lightning | 5 by 30 ft. line (Dex. save) |\n| Brass | Fire | 5 by 30 ft. line (Dex. save) |\n| Bronze | Lightning | 5 by 30 ft. line (Dex. save) |\n| Copper | Acid | 5 by 30 ft. line (Dex. save) |\n| Gold | Fire | 15 ft. cone (Dex. save) |\n| Green | Poison | 15 ft. cone (Con. save) |\n| Red | Fire | 15 ft. cone (Dex. save) |\n| Silver | Cold | 15 ft. cone (Con. save) |\n| White | Cold | 15 ft. cone (Con. save) |"},{"name":"Breath Weapon","text":"You can use your action to exhale destructive energy. Your draconic ancestry determines the size, shape, and damage type of the exhalation.\n\nWhen you use your breath weapon, each creature in the area of the exhalation must make a saving throw, the type of which is determined by your draconic ancestry. The DC for this saving throw equals 8 + your Constitution modifier + your proficiency bonus. A creature takes 2d6 damage on a failed save, and half as much damage on a successful one. The damage increases to 3d6 at 6th level, 4d6 at 11th level, and 5d6 at 16th level.\n\nAfter you use your breath weapon, you can't use it again until you complete a short or long rest."},{"name":"Damage Resistance","text":"You have resistance to the damage type associated with your draconic ancestry."}],"lineage":"","age":{"mature":15,"max":80},"heightWeight":{"baseHeight":66,"heightMod":"2d8","baseWeight":175,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Dragonborn.webp"],"srd":true},{"id":"dragonborn-xphb","name":"Dragonborn","source":"XPHB","page":187,"edition":"2024","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"resist":{"fixed":[],"choose":{"from":["acid","lightning","fire","poison","cold"],"count":1}},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Draconic Ancestry","text":"Your lineage stems from a dragon progenitor. Choose the kind of dragon from the Draconic Ancestors table. Your choice affects your Breath Weapon and Damage Resistance traits as well as your appearance.\n\nDraconic Ancestors:\n| Dragon | Damage Type |\n| Black | Acid |\n| Blue | Lightning |\n| Brass | Fire |\n| Bronze | Lightning |\n| Copper | Acid |\n| Gold | Fire |\n| Green | Poison |\n| Red | Fire |\n| Silver | Cold |\n| White | Cold |"},{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 damage of the type determined by your Draconic Ancestry trait. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to the damage type determined by your Draconic Ancestry trait."},{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Draconic Flight","text":"When you reach character level 5, you can channel draconic magic to give yourself temporary flight. As a Bonus Action, you sprout spectral wings on your back that last for 10 minutes or until you retract the wings (no action required) or have the Incapacitated condition. During that time, you have a Fly Speed equal to your Speed. Your wings appear to be made of the same energy as your Breath Weapon. Once you use this trait, you can't use it again until you finish a Long Rest."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"dragonborn-xphb--black","name":"Black","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Acid damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Acid damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["acid"]}}},{"id":"dragonborn-xphb--blue","name":"Blue","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Lightning damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Lightning damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["lightning"]}}},{"id":"dragonborn-xphb--brass","name":"Brass","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Fire damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Fire damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["fire"]}}},{"id":"dragonborn-xphb--bronze","name":"Bronze","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Lightning damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Lightning damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["lightning"]}}},{"id":"dragonborn-xphb--copper","name":"Copper","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Acid damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Acid damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["acid"]}}},{"id":"dragonborn-xphb--gold","name":"Gold","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Fire damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Fire damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["fire"]}}},{"id":"dragonborn-xphb--green","name":"Green","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Poison damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Poison damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["poison"]}}},{"id":"dragonborn-xphb--red","name":"Red","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Fire damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Fire damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["fire"]}}},{"id":"dragonborn-xphb--silver","name":"Silver","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Cold damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Cold damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["cold"]}}},{"id":"dragonborn-xphb--white","name":"White","kind":"lineage","source":"XPHB","page":187,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in either a 15-foot Cone or a 30-foot Line that is 5 feet wide (choose the shape each time). Each creature in that area must make a Dexterity saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes 1d10 Cold damage. On a successful save, a creature takes half as much damage. This damage increases by 1d10 when you reach character levels 5 (2d10), 11 (3d10), and 17 (4d10).\n\nYou can use this Breath Weapon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Damage Resistance","text":"You have Resistance to Cold damage."}],"removes":["Draconic Ancestry"],"benefits":{"resist":{"fixed":["cold"]}}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Dragonborn.webp"],"srd":true},{"id":"dragonborn-chromatic-ftd","name":"Dragonborn (Chromatic)","source":"FTD","page":10,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":[],"choose":{"from":["acid","lightning","poison","fire","cold"],"count":1}}},"feats":[],"traits":[{"name":"Chromatic Ancestry","text":"You have a chromatic dragon ancestor, granting you a special magical affinity. Choose one kind of dragon from the Chromatic Ancestry table. This determines the damage type for your other traits, as shown in the table.\n\nChromatic Ancestry:\n| Dragon | Damage Type |\n| Black | Acid |\n| Blue | Lightning |\n| Green | Poison |\n| Red | Fire |\n| White | Cold |"},{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your Chromatic Ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to the damage type associated with your Chromatic Ancestry."},{"name":"Chromatic Warding","text":"Starting at 5th level, as an action, you can channel your draconic energy to protect yourself. For 1 minute, you become immune to the damage type associated with your Chromatic Ancestry. Once you use this trait, you can't do so again until you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[{"id":"dragonborn-chromatic-ftd--black","name":"Black)","kind":"lineage","source":"FTD","page":10,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 acid damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to acid damage."}],"removes":["Chromatic Ancestry"]},{"id":"dragonborn-chromatic-ftd--blue","name":"Blue)","kind":"lineage","source":"FTD","page":10,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 lightning damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to lightning damage."}],"removes":["Chromatic Ancestry"]},{"id":"dragonborn-chromatic-ftd--green","name":"Green)","kind":"lineage","source":"FTD","page":10,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 poison damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to poison damage."}],"removes":["Chromatic Ancestry"]},{"id":"dragonborn-chromatic-ftd--red","name":"Red)","kind":"lineage","source":"FTD","page":10,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 fire damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to fire damage."}],"removes":["Chromatic Ancestry"]},{"id":"dragonborn-chromatic-ftd--white","name":"White)","kind":"lineage","source":"FTD","page":10,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 30-foot line that is 5 feet wide. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 cold damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to cold damage."}],"removes":["Chromatic Ancestry"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/FTD/Chromatic%20Dragonborn.webp"]},{"id":"dragonborn-gem-ftd","name":"Dragonborn (Gem)","source":"FTD","page":11,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":[],"choose":{"from":["force","radiant","psychic","thunder","necrotic"],"count":1}}},"feats":[],"traits":[{"name":"Gem Ancestry","text":"You have a gem dragon ancestor, granting you a special magical affinity. Choose one kind of dragon from the Gem Ancestry table. This determines the damage type for your other traits, as shown in the table.\n\nGem Ancestry:\n| Dragon | Damage Type |\n| Amethyst | Force |\n| Crystal | Radiant |\n| Emerald | Psychic |\n| Sapphire | Thunder |\n| Topaz | Necrotic |"},{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your Gem Ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to the damage type associated with your Gem Ancestry."},{"name":"Psionic Mind","text":"You can send telepathic messages to any creature you can see within 30 feet of you. You don't need to share a language with the creature for it to understand these messages, but it must be able to understand at least one language to comprehend them."},{"name":"Gem Flight","text":"Starting at 5th level, you can use a bonus action to manifest spectral wings on your body. These wings last for 1 minute. For the duration, you gain a flying speed equal to your walking speed and can hover. Once you use this trait, you can't do so again until you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[{"id":"dragonborn-gem-ftd--amethyst","name":"Amethyst)","kind":"lineage","source":"FTD","page":11,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 force damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to force damage."}],"removes":["Gem Ancestry"],"benefits":{"resist":{"fixed":["force"]}}},{"id":"dragonborn-gem-ftd--crystal","name":"Crystal)","kind":"lineage","source":"FTD","page":11,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 radiant damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to radiant damage."}],"removes":["Gem Ancestry"],"benefits":{"resist":{"fixed":["radiant"]}}},{"id":"dragonborn-gem-ftd--emerald","name":"Emerald)","kind":"lineage","source":"FTD","page":11,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 psychic damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to psychic damage."}],"removes":["Gem Ancestry"],"benefits":{"resist":{"fixed":["psychic"]}}},{"id":"dragonborn-gem-ftd--sapphire","name":"Sapphire)","kind":"lineage","source":"FTD","page":11,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 thunder damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to thunder damage."}],"removes":["Gem Ancestry"],"benefits":{"resist":{"fixed":["thunder"]}}},{"id":"dragonborn-gem-ftd--topaz","name":"Topaz)","kind":"lineage","source":"FTD","page":11,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 necrotic damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to necrotic damage."}],"removes":["Gem Ancestry"],"benefits":{"resist":{"fixed":["necrotic"]}}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/FTD/Gem%20Dragonborn.webp"]},{"id":"dragonborn-metallic-ftd","name":"Dragonborn (Metallic)","source":"FTD","page":12,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":[],"choose":{"from":["fire","lightning","acid","cold"],"count":1}}},"feats":[],"traits":[{"name":"Metallic Ancestry","text":"You have a metallic dragon ancestor, granting you a special magical affinity. Choose one kind of dragon from the Metallic Ancestry table. This determines the damage type for your other traits, as shown in the table.\n\nMetallic Ancestry:\n| Dragon | Damage Type |\n| Brass | Fire |\n| Bronze | Lightning |\n| Copper | Acid |\n| Gold | Fire |\n| Silver | Cold |"},{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 damage of the type associated with your Metallic Ancestry. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to the damage type associated with your Metallic Ancestry."},{"name":"Metallic Breath Weapon","text":"At 5th level, you gain a second breath weapon. When you take the Attack action on your turn, you can replace one of your attacks with an exhalation in a 15-foot cone. The save DC for this breath is 8 + your Constitution modifier + your proficiency bonus. Whenever you use this trait, choose one:\n\n• Enervating Breath Each creature in the cone must succeed on a Constitution saving throw or become incapacitated until the start of your next turn.\n• Repulsion Breath Each creature in the cone must succeed on a Strength saving throw or be pushed 20 feet away from you and be knocked prone.\n\nOnce you use your Metallic Breath Weapon, you can't do so again until you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[{"id":"dragonborn-metallic-ftd--brass","name":"Brass)","kind":"lineage","source":"FTD","page":12,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 fire damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to fire damage."}],"removes":["Metallic Ancestry"],"benefits":{"resist":{"fixed":["fire"]}}},{"id":"dragonborn-metallic-ftd--bronze","name":"Bronze)","kind":"lineage","source":"FTD","page":12,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 lightning damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to lightning damage."}],"removes":["Metallic Ancestry"],"benefits":{"resist":{"fixed":["lightning"]}}},{"id":"dragonborn-metallic-ftd--copper","name":"Copper)","kind":"lineage","source":"FTD","page":12,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 acid damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to acid damage."}],"removes":["Metallic Ancestry"],"benefits":{"resist":{"fixed":["acid"]}}},{"id":"dragonborn-metallic-ftd--gold","name":"Gold)","kind":"lineage","source":"FTD","page":12,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 fire damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to fire damage."}],"removes":["Metallic Ancestry"],"benefits":{"resist":{"fixed":["fire"]}}},{"id":"dragonborn-metallic-ftd--silver","name":"Silver)","kind":"lineage","source":"FTD","page":12,"traits":[{"name":"Breath Weapon","text":"When you take the Attack action on your turn, you can replace one of your attacks with an exhalation of magical energy in a 15-foot cone. Each creature in that area must make a Dexterity saving throw (DC = 8 + your Constitution modifier + your proficiency bonus). On a failed save, the creature takes 1d10 cold damage. On a successful save, it takes half as much damage. This damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).\n\nYou can use your Breath Weapon a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Draconic Resistance","text":"You have resistance to cold damage."}],"removes":["Metallic Ancestry"],"benefits":{"resist":{"fixed":["cold"]}}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/FTD/Metallic%20Dragonborn.webp"]},{"id":"duergar-mpmm","name":"Duergar","source":"MPMM","page":12,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"enlarge-reduce-phb","name":"Enlarge/Reduce","how":"innate","uses":"1/day","at":"3"},{"spell":"invisibility-phb","name":"Invisibility","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["poison"]},"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 120 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Duergar Magic","text":"Starting at 3rd level, you can cast the enlarge/reduce spell on yourself with this trait, without requiring a material component. Starting at 5th level, you can also cast the invisibility spell on yourself with this trait, without requiring a material component. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"name":"Dwarven Resilience","text":"You have advantage on saving throws you make to avoid or end the poisoned condition on yourself. You also have resistance to poison damage."},{"name":"Psionic Fortitude","text":"You have advantage on saving throws you make to avoid or end the charmed or stunned condition on yourself."}],"lineage":"VRGR","age":{"mature":null,"max":350},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Duergar.webp"]},{"id":"dwarf-phb","name":"Dwarf","source":"PHB","page":18,"edition":"2014","size":["Medium"],"speed":{"walk":7.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2}}],"proficiencies":[{"kind":"tool","choose":{"from":["smith's tools","brewer's supplies","mason's tools"],"count":1}},{"kind":"language","fixed":["common","dwarvish"]},{"kind":"weapon","fixed":["battleaxe","handaxe","light hammer","warhammer"]}],"resist":{"fixed":["poison"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Dwarven Resilience","text":"You have advantage on saving throws against poison, and you have resistance against poison damage."},{"name":"Dwarven Combat Training","text":"You have proficiency with the battleaxe, handaxe, light hammer, and warhammer."},{"name":"Tool Proficiency","text":"You gain proficiency with the artisan's tools of your choice: Smith's tools, brewer's supplies, or mason's tools."},{"name":"Stonecunning","text":"Whenever you make an Intelligence (History) check related to the origin of stonework, you are considered proficient in the History skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus."}],"lineage":"","age":{"mature":20,"max":350},"heightWeight":null,"options":[{"id":"dwarf-phb--duergar-mtf","name":"Duergar","kind":"subrace","source":"MTF","page":81,"traits":[{"name":"Superior Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Duergar Resilience","text":"You have advantage on saving throws against poison, and you have resistance against poison damage. You also have advantage on saving throws against illusions and against being charmed or paralyzed."},{"name":"Duergar Magic","text":"When you reach 3rd level, you can cast the Enlarge/Reduce spell on yourself once with this trait, using only the spell's enlarge option. When you reach 5th level, you can cast the Invisibility spell on yourself once with this trait. You don't need material components for either spell, and you can't cast them while you're in direct sunlight, although sunlight has no effect on them once cast. You regain the ability to cast these spells with this trait when you finish a long rest. Intelligence is your spellcasting ability for these spells."},{"name":"Sunlight Sensitivity","text":"You have disadvantage on attack rolls and Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."}],"removes":["Darkvision","Dwarven Resilience"],"benefits":{"ability":[{"fixed":{"con":2,"str":1}}],"proficiencies":[{"kind":"tool","choose":{"from":["smith's tools","brewer's supplies","mason's tools"],"count":1}},{"kind":"language","fixed":["common","dwarvish","undercommon"]},{"kind":"weapon","fixed":["battleaxe","handaxe","light hammer","warhammer"]}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"spell":"enlarge-reduce-phb","name":"Enlarge/Reduce","how":"innate","uses":"1/day","at":"3"},{"spell":"invisibility-phb","name":"Invisibility","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":36}]}},{"id":"dwarf-phb--hill","name":"Hill","kind":"subrace","source":"PHB","page":20,"traits":[{"name":"Dwarven Toughness","text":"Your hit point maximum increases by 1, and it increases by 1 every time you gain a level."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"wis":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Dwarf.webp"]},{"id":"dwarf-phb--mark-of-warding-erlw","name":"Mark of Warding","kind":"subrace","source":"ERLW","page":51,"traits":[{"name":"Warder's Intuition","text":"When you make an Intelligence (Investigation) check or an ability check using thieves' tools, you can roll a d4 and add the number rolled to the ability check."},{"name":"Wards and Seals","text":"You can cast the alarm and mage armor spells with this trait. Starting at 3rd level, you can also cast the arcane lock spell with it. Once you cast any of these spells with this trait, you can't cast that spell with it again until you finish a long rest. Intelligence is your spellcasting ability for these spells, and you don't need material components for them when you cast them with this trait."},{"name":"Spells of the Mark","text":"If you have the Spellcasting or the Pact Magic class feature, the spells on the Mark of Warding Spells table are added to the spell list of your spellcasting class.\n\nMark of Warding Spells:\n| Spell Level | Spells |\n| 1st | alarm, armor of Agathys |\n| 2nd | arcane lock, knock |\n| 3rd | glyph of warding, magic circle |\n| 4th | Leomund's secret chest, Mordenkainen's faithful hound |\n| 5th | antilife shell |"}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"int":1}}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"spell":"alarm-phb","name":"Alarm","how":"known","uses":"","at":"1"},{"spell":"mage-armor-phb","name":"Mage Armor","how":"known","uses":"","at":"1"},{"spell":"alarm-phb","name":"Alarm","how":"expanded","uses":"","at":"s1"},{"spell":"armor-of-agathys-phb","name":"Armor of Agathys","how":"expanded","uses":"","at":"s1"},{"spell":"arcane-lock-phb","name":"Arcane Lock","how":"expanded","uses":"","at":"s2"},{"spell":"knock-phb","name":"Knock","how":"expanded","uses":"","at":"s2"},{"spell":"glyph-of-warding-phb","name":"Glyph of Warding","how":"expanded","uses":"","at":"s3"},{"spell":"magic-circle-phb","name":"Magic Circle","how":"expanded","uses":"","at":"s3"},{"spell":"leomund-s-secret-chest-phb","name":"Leomund's Secret Chest","how":"expanded","uses":"","at":"s4"},{"spell":"mordenkainen-s-faithful-hound-phb","name":"Mordenkainen's Faithful Hound","how":"expanded","uses":"","at":"s4"},{"spell":"antilife-shell-phb","name":"Antilife Shell","how":"expanded","uses":"","at":"s5"}]}]}}},{"id":"dwarf-phb--mountain","name":"Mountain","kind":"subrace","source":"PHB","page":20,"traits":[{"name":"Dwarven Armor Training","text":"You have proficiency with light and medium armor."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"str":2}}],"proficiencies":[{"kind":"tool","choose":{"from":["smith's tools","brewer's supplies","mason's tools"],"count":1}},{"kind":"language","fixed":["common","dwarvish"]},{"kind":"weapon","fixed":["battleaxe","handaxe","light hammer","warhammer"]},{"kind":"armor","fixed":["light","medium"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Dwarf.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Dwarf.webp"],"srd":true},{"id":"dwarf-xphb","name":"Dwarf","source":"XPHB","page":188,"edition":"2024","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"resist":{"fixed":["poison"]},"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 120 feet."},{"name":"Dwarven Resilience","text":"You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition."},{"name":"Dwarven Toughness","text":"Your Hit Point maximum increases by 1, and it increases by 1 again whenever you gain a level."},{"name":"Stonecunning","text":"As a Bonus Action, you gain Tremorsense with a range of 60 feet for 10 minutes. You must be on a stone surface or touching a stone surface to use this Tremorsense. The stone can be natural or worked.\n\nYou can use this Bonus Action a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Dwarf.webp"],"srd":true},{"id":"dwarf-kaladesh-psk","name":"Dwarf (Kaladesh)","source":"PSK","page":19,"edition":"","size":["Medium"],"speed":{"walk":7.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2,"wis":1}}],"proficiencies":[{"kind":"tool","any":{"anyArtisansTool":2}},{"kind":"language","fixed":["common","dwarvish"]}],"resist":{"fixed":["poison"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Accustomed to life underground in your race's ancient past, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Dwarven Resilience","text":"You have advantage on saving throws against poison, and you have resistance against poison damage."},{"name":"Dwarven Toughness","text":"Your hit point maximum increases by 1, and it increases by 1 every time you gain a level."},{"name":"Artisan's Expertise","text":"You gain proficiency with two kinds of artisan's tools of your choice. Your proficiency bonus is doubled for any ability check you make that uses either of the chosen proficiencies. In addition, whenever you make an Intelligence (History) check related to the origin of any architectural construction (including buildings, public works such as canals and aqueducts, and the massive cogwork that underlies much of the construction of Ghirapur), you are considered proficient in the History skill and add double your proficiency bonus to the check, instead of your normal proficiency bonus."}],"lineage":"","age":{"mature":50,"max":350},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Dwarf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Dwarf2.webp"]},{"id":"eladrin-mpmm","name":"Eladrin","source":"MPMM","page":13,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Fey Step","text":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nWhen you reach 3rd level, your Fey Step gain an additional effect based on your season; if the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race):\n\n• Autumn Immediately after you use your Fey Step, up to two creatures of your choice that you can see within 10 feet of you must succeed on a Wisdom saving throw or be charmed by you for 1 minute, or until you or your companions deal any damage to the creatures.\n• Winter When you use your Fey Step, one creature of your choice that you can see within 5 feet of you before you teleport must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn.\n• Spring When you use your Fey Step, you can touch one willing creature within 5 feet of you. That creature then teleports instead of you, appearing in an unoccupied space of your choice that you can see within 30 feet of you.\n• Summer Immediately after you use your Fey Step, each creature of your choice that you can see within 5 feet of you takes fire damage equal to your proficiency bonus."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Trance","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness.\n\nWhenever you finish this trance, you can change your season, and you can gain two proficiencies that you don't have, each one with a 5 or a 5 of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."}],"lineage":"VRGR","age":{"mature":null,"max":750},"heightWeight":null,"options":[],"description":"Choose your eladrin's season: autumn, winter, spring, or summer. When finishing a long rest, you can change your season. See the \"Info\" tab for more information.","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Eladrin.webp"]},{"id":"elf-lfl","name":"Elf","source":"LFL","page":null,"edition":"2024","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"proficiencies":[{"kind":"skill","choose":{"from":["insight","perception","survival"],"count":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"Lorwyn","items":[{"choose":"level=0|class=Druid","label":"Cantrip Druid","count":1,"how":"known","uses":"_","at":"1"},{"spell":"command-xphb","name":"Command","how":"innate","uses":"1/day","at":"3"},{"spell":"silence-xphb","name":"Silence","how":"innate","uses":"1/day","at":"5"}]},{"name":"Shadowmoor","items":[{"spell":"starry-wisp-xphb","name":"Starry Wisp","how":"known","uses":"","at":"1"},{"spell":"heroism-xphb","name":"Heroism","how":"innate","uses":"1/day","at":"3"},{"spell":"gentle-repose-xphb","name":"Gentle Repose","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Elven Lineage","text":"You are part of a lineage that grants you supernatural abilities. Choose a lineage from the Elven Lineages table. You gain the level 1 benefit of that lineage.\n\nWhen you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage).\n\nElven Lineages:\n| Lineage | Level 1 | Level 3 | Level 5 |\n| Lorwyn | You know the Thorn Whip cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Druid spell list. | Command | Silence |\n| Shadowmoor | The range of your Darkvision increases to 120 feet. You also know the Starry Wisp cantrip. | Heroism | Gentle Repose |"},{"name":"Fey Ancestry","text":"You have Advantage on saving throws you make to avoid or end the Charmed condition."},{"name":"Keen Senses","text":"You have proficiency in the Insight, Perception, or Survival skill."},{"name":"Trance","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"elf-lfl--lorwyn-lineage","name":"Lorwyn Lineage","kind":"lineage","source":"LFL","page":null,"traits":[{"name":"Elven Lineage (Lorwyn)","text":"You are part of a lineage that grants you supernatural abilities. You know the Thorn Whip cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Druid spell list.\n\nWhen you reach character level 3, you learn the Command spell. When you reach character level 5, you also learn the Silence spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."}],"removes":["Elven Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"choose":"level=0|class=Druid","label":"Cantrip Druid","count":1,"how":"known","uses":"_","at":"1"},{"spell":"command-xphb","name":"Command","how":"innate","uses":"1/day","at":"3"},{"spell":"silence-xphb","name":"Silence","how":"innate","uses":"1/day","at":"5"}]}]}}},{"id":"elf-lfl--shadowmoor-lineage","name":"Shadowmoor Lineage","kind":"lineage","source":"LFL","page":null,"traits":[{"name":"Elven Lineage (Shadowmoor)","text":"You are part of a lineage that grants you supernatural abilities. The range of your Darkvision increases to 120 feet. You also know the Starry Wisp cantrip.\n\nWhen you reach character level 3, you learn the Heroism spell. When you reach character level 5, you also learn the Gentle Repose spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."}],"removes":["Elven Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"starry-wisp-xphb","name":"Starry Wisp","how":"known","uses":"","at":"1"},{"spell":"heroism-xphb","name":"Heroism","how":"innate","uses":"1/day","at":"3"},{"spell":"gentle-repose-xphb","name":"Gentle Repose","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":36}]}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Elf%20(Lorwyn).webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Elf%20(Shadowmoor).webp"]},{"id":"elf-phb","name":"Elf","source":"PHB","page":21,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Fey Ancestry","text":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"name":"Trance","text":"Elves don't need to sleep. Instead, they meditate deeply, remaining semiconscious, for 4 hours a day. (The Common word for such meditation is \"trance.\") While meditating, you can dream after a fashion; such dreams are actually mental exercises that have become reflexive through years of practice. After resting in this way, you gain the same benefit that a human does from 8 hours of sleep.\n\nIf you meditate during a long rest, you finish the rest after only 4 hours. You otherwise obey all the rules for a long rest; only the duration is changed."}],"lineage":"","age":{"mature":100,"max":750},"heightWeight":null,"options":[{"id":"elf-phb--drow","name":"Drow","kind":"subrace","source":"PHB","page":24,"traits":[{"name":"Superior Darkvision","text":"Accustomed to the depths of the Underdark, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Sunlight Sensitivity","text":"You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."},{"name":"Drow Magic","text":"You know the dancing lights cantrip. When you reach 3rd level, you can cast the faerie fire spell once with this trait; you regain the ability to cast it when you finish a long rest. When you reach 5th level, you can also cast the darkness spell once per day with this trait; you regain the ability to cast it when you finish a long rest. Charisma is your spellcasting ability for these spells."},{"name":"Drow Weapon Training","text":"You have proficiency with rapiers, shortswords, and hand crossbows."}],"removes":["Darkvision"],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"weapon","fixed":["rapier","shortsword","hand crossbow"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"dancing-lights-phb","name":"Dancing Lights","how":"known","uses":"","at":"1"},{"spell":"faerie-fire-phb","name":"Faerie Fire","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-phb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":36}]}},{"id":"elf-phb--eladrin-dmg","name":"Eladrin","kind":"subrace","source":"DMG","page":286,"traits":[{"name":"Elf Weapon Training","text":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"name":"Fey Step","text":"You can cast the misty step spell once using this trait. You regain the ability to do so when you finish a short or long rest."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"int":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"weapon","fixed":["longsword","shortsword","shortbow","longbow"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"misty-step-phb","name":"Misty Step","how":"known","uses":"1/rest","at":"1"}]}]}}},{"id":"elf-phb--eladrin-mtf","name":"Eladrin","kind":"subrace","source":"MTF","page":61,"traits":[{"name":"Fey Step","text":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. Once you use this trait, you can't do so again until you finish a short or long rest.\n\nWhen you reach 3rd level, your Fey Step gains an additional effect based on your season; if the effect requires a saving throw, the DC equals 8 + your proficiency bonus + your Charisma modifier:\n\n• Autumn Immediately after you use your Fey Step, up to two creatures of your choice that you can see within 10 feet of you must succeed on a Wisdom saving throw or be charmed by you for 1 minute, or until you or your companions deal any damage to it.\n• Winter When you use your Fey Step, one creature of your choice that you can see within 5 feet of you before you teleport must succeed on a Wisdom saving throw or be frightened of you until the end of your next turn.\n• Spring When you use your Fey Step, you can touch one willing creature within 5 feet of you. That creature then teleports instead of you, appearing in an unoccupied space of your choice that you can see within 30 feet of you.\n• Summer Immediately after you use your Fey Step, each creature of your choice that you can see within 5 feet of you takes fire damage equal to your Charisma modifier (minimum of 1 damage)."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Elf.webp"]},{"id":"elf-phb--high","name":"High","kind":"subrace","source":"PHB","page":23,"traits":[{"name":"Elf Weapon Training","text":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"name":"Cantrip","text":"You know one cantrip of your choice from the wizard spell list. Intelligence is your spellcasting ability for it."},{"name":"Extra Language","text":"You can speak, read, and write one extra language of your choosing."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"int":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"],"any":{"anyStandard":1}},{"kind":"weapon","fixed":["longsword","shortsword","shortbow","longbow"]}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"choose":"level=0|class=Wizard","label":"Cantrip Wizard","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Elf.webp"]},{"id":"elf-phb--mark-of-shadow-erlw","name":"Mark of Shadow","kind":"subrace","source":"ERLW","page":49,"traits":[{"name":"Cunning Intuition","text":"When you make a Charisma (Performance) or Dexterity (Stealth) check, you can roll a d4 and add the number rolled to the ability check."},{"name":"Shape Shadows","text":"You know the minor illusion cantrip. Starting at 3rd level, you can cast the invisibility spell once with this trait, and you regain the ability to cast it when you finish a long rest. Charisma is your spellcasting ability for these spells."},{"name":"Spells of the Mark","text":"If you have the Spellcasting or the Pact Magic class feature, the spells on the Mark of Shadow Spells table are added to the spell list of your spellcasting class.\n\nMark of Shadow Spells:\n| Spell Level | Spells |\n| 1st | disguise self, silent image |\n| 2nd | darkness, pass without trace |\n| 3rd | clairvoyance, major image |\n| 4th | greater invisibility, hallucinatory terrain |\n| 5th | mislead |"}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"minor-illusion-phb","name":"Minor Illusion","how":"known","uses":"","at":"1"},{"spell":"invisibility-phb","name":"Invisibility","how":"innate","uses":"1/day","at":"3"},{"spell":"disguise-self-phb","name":"Disguise Self","how":"expanded","uses":"","at":"s1"},{"spell":"silent-image-phb","name":"Silent Image","how":"expanded","uses":"","at":"s1"},{"spell":"darkness-phb","name":"Darkness","how":"expanded","uses":"","at":"s2"},{"spell":"pass-without-trace-phb","name":"Pass without Trace","how":"expanded","uses":"","at":"s2"},{"spell":"clairvoyance-phb","name":"Clairvoyance","how":"expanded","uses":"","at":"s3"},{"spell":"major-image-phb","name":"Major Image","how":"expanded","uses":"","at":"s3"},{"spell":"greater-invisibility-phb","name":"Greater Invisibility","how":"expanded","uses":"","at":"s4"},{"spell":"hallucinatory-terrain-phb","name":"Hallucinatory Terrain","how":"expanded","uses":"","at":"s4"},{"spell":"mislead-phb","name":"Mislead","how":"expanded","uses":"","at":"s5"}]}]}}},{"id":"elf-phb--pallid-egw","name":"Pallid","kind":"subrace","source":"EGW","page":21,"traits":[{"name":"Incisive Sense","text":"You have advantage on Intelligence (Investigation) and Wisdom (Insight) checks."},{"name":"Blessing of the Moon Weaver","text":"You know the light cantrip. When you reach 3rd level, you can cast the sleep spell once with this trait and regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the invisibility spell (targeting yourself only) once with this trait and regain the ability to do so when you finish a long rest. Casting these spells with this trait doesn't require material components. Wisdom is your spellcasting ability for these spells."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"spell":"light-phb","name":"Light","how":"known","uses":"","at":"1"},{"spell":"sleep-phb","name":"Sleep","how":"innate","uses":"1/day","at":"3"},{"spell":"invisibility-phb","name":"Invisibility","how":"innate","uses":"1/day","at":"5"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EGW/Elf%20(Pallid).webp"]},{"id":"elf-phb--sea-mtf","name":"Sea","kind":"subrace","source":"MTF","page":62,"traits":[{"name":"Sea Elf Training","text":"You have proficiency with the spear, trident, light crossbow, and net."},{"name":"Child of the Sea","text":"You have a swimming speed of 30 feet, and you can breathe air and water."},{"name":"Friend of the Sea","text":"Using gestures and sounds, you can communicate simple ideas with any beast that has an innate swimming speed."},{"name":"Extra Language","text":"You can speak, read, and write Aquan."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"language","fixed":["common","elvish","aquan"]},{"kind":"weapon","fixed":["spear","trident","light crossbow","net"]}]},"speed":{"walk":9,"swim":9}},{"id":"elf-phb--shadar-kai-mtf","name":"Shadar-kai","kind":"subrace","source":"MTF","page":62,"traits":[{"name":"Necrotic Resistance","text":"You have resistance to necrotic damage."},{"name":"Blessing of the Raven Queen","text":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. Once you use this trait, you can't do so again until you finish a long rest.\n\nStarting at 3rd level, you also gain resistance to all damage when you teleport using this trait. The resistance lasts until the start of your next turn. During that time, you appear ghostly and translucent."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"resist":{"fixed":["necrotic"]}}},{"id":"elf-phb--wood","name":"Wood","kind":"subrace","source":"PHB","page":24,"traits":[{"name":"Elf Weapon Training","text":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"name":"Fleet of Foot","text":"Your base walking speed increases to 35 feet."},{"name":"Mask of the Wild","text":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"weapon","fixed":["longsword","shortsword","shortbow","longbow"]}]},"speed":{"walk":10.5},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Elf.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Elf.webp"],"srd":true},{"id":"elf-xphb","name":"Elf","source":"XPHB","page":189,"edition":"2024","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"proficiencies":[{"kind":"skill","choose":{"from":["insight","perception","survival"],"count":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"Drow","items":[{"spell":"dancing-lights-xphb","name":"Dancing Lights","how":"known","uses":"","at":"1"},{"spell":"faerie-fire-xphb","name":"Faerie Fire","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-xphb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]},{"name":"High Elf","items":[{"choose":"level=0|class=Wizard","label":"Cantrip Wizard","count":1,"how":"known","uses":"_","at":"1"},{"spell":"detect-magic-xphb","name":"Detect Magic","how":"innate","uses":"1/day","at":"3"},{"spell":"misty-step-xphb","name":"Misty Step","how":"innate","uses":"1/day","at":"5"}]},{"name":"Wood Elf","items":[{"spell":"druidcraft-xphb","name":"Druidcraft","how":"known","uses":"","at":"1"},{"spell":"longstrider-xphb","name":"Longstrider","how":"innate","uses":"1/day","at":"3"},{"spell":"pass-without-trace-xphb","name":"Pass without Trace","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Elven Lineage","text":"You are part of a lineage that grants you supernatural abilities. Choose a lineage from the Elven Lineages table. You gain the level 1 benefit of that lineage.\n\nWhen you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage).\n\nElven Lineages:\n| Lineage | Level 1 | Level 3 | Level 5 |\n| Drow | The range of your Darkvision increases to 120 feet. You also know the Dancing Lights cantrip. | Faerie Fire | Darkness |\n| High Elf | You know the Prestidigitation cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Wizard spell list. | Detect Magic | Misty Step |\n| Wood Elf | Your Speed increases to 35 feet. You also know the Druidcraft cantrip. | Longstrider | Pass without Trace |"},{"name":"Fey Ancestry","text":"You have Advantage on saving throws you make to avoid or end the Charmed condition."},{"name":"Keen Senses","text":"You have proficiency in the Insight, Perception, or Survival skill."},{"name":"Trance","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"elf-xphb--drow-lineage","name":"Drow Lineage","kind":"lineage","source":"XPHB","page":189,"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 120 feet."},{"name":"Elven Lineage (Drow)","text":"You are part of a lineage that grants you supernatural abilities. The range of your Darkvision increases to 120 feet. You also know the Dancing Lights cantrip.\n\nWhen you reach character level 3, you learn the Faerie Fire spell. When you reach character level 5, you also learn the Darkness spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."}],"removes":["Elven Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"dancing-lights-xphb","name":"Dancing Lights","how":"known","uses":"","at":"1"},{"spell":"faerie-fire-xphb","name":"Faerie Fire","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-xphb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":36}]}},{"id":"elf-xphb--high-elf-lineage","name":"High Elf Lineage","kind":"lineage","source":"XPHB","page":189,"traits":[{"name":"Elven Lineage (High Elf)","text":"You are part of a lineage that grants you supernatural abilities. You know the Prestidigitation cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Wizard spell list.\n\nWhen you reach character level 3, you learn the Detect Magic spell. When you reach character level 5, you also learn the Misty Step spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."}],"removes":["Elven Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"choose":"level=0|class=Wizard","label":"Cantrip Wizard","count":1,"how":"known","uses":"_","at":"1"},{"spell":"detect-magic-xphb","name":"Detect Magic","how":"innate","uses":"1/day","at":"3"},{"spell":"misty-step-xphb","name":"Misty Step","how":"innate","uses":"1/day","at":"5"}]}]}}},{"id":"elf-xphb--wood-elf-lineage","name":"Wood Elf Lineage","kind":"lineage","source":"XPHB","page":189,"traits":[{"name":"Elven Lineage (Wood Elf)","text":"You are part of a lineage that grants you supernatural abilities. Your Speed increases to 35 feet. You also know the Druidcraft cantrip.\n\nWhen you reach character level 3, you learn the Longstrider spell. When you reach character level 5, you also learn the Pass without Trace spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage)."}],"removes":["Elven Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"druidcraft-xphb","name":"Druidcraft","how":"known","uses":"","at":"1"},{"spell":"longstrider-xphb","name":"Longstrider","how":"innate","uses":"1/day","at":"3"},{"spell":"pass-without-trace-xphb","name":"Pass without Trace","how":"innate","uses":"1/day","at":"5"}]}]}},"speed":{"walk":10.5}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/148-05-022.elf-city.webp"],"srd":true},{"id":"elf-kaladesh-psk","name":"Elf (Kaladesh)","source":"PSK","page":20,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"weapon","fixed":["longsword","shortsword","shortbow","longbow"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Elf Weapon Training","text":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"name":"Fey Ancestry","text":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"name":"Trance","text":"Elves don't need to sleep. Instead, they meditate deeply, remaining semiconscious, for 4 hours a day. (The Common word for such meditation is \"trance.\") While meditating, you can dream after a fashion; such dreams are actually mental exercises that have become reflexive through years of practice. After resting in this way, you gain the same benefit that a human does from 8 hours of sleep.\n\nIf you meditate during a long rest, you finish the rest after only 4 hours. You otherwise obey all the rules for a long rest; only the duration is changed."},{"name":"Elf Culture","text":"The elves of Kaladesh don't organize themselves into nations or tribes. Still, they recognize three distinct cultural groups among their kind—though in truth these groupings are more like attitudes or alignments with regard to the rest of society and the use of technology. Choose one of these cultures."}],"lineage":"","age":{"mature":100,"max":750},"heightWeight":null,"options":[{"id":"elf-kaladesh-psk--bishatar-and-tirahar","name":"Bishatar and Tirahar","kind":"subrace","source":"PSK","page":21,"traits":[{"name":"Fleet of Foot","text":"Your ground speed increases to 35 feet."},{"name":"Mask of the Wild","text":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."}],"removes":["Elf Culture"],"speed":{"walk":10.5},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Elf2.webp"]},{"id":"elf-kaladesh-psk--vahadar","name":"Vahadar","kind":"subrace","source":"PSK","page":21,"traits":[{"name":"Cantrip","text":"You know one cantrip of your choice from the druid spell list. Wisdom is your spellcasting ability for it."},{"name":"Extra Language","text":"You can speak, read, and write one extra language of your choosing."}],"removes":["Elf Culture"],"benefits":{"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"choose":"level=0|class=Druid","label":"Cantrip Druid","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Elf2.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Elf2.webp"]},{"id":"elf-zendikar-psz","name":"Elf (Zendikar)","source":"PSZ","page":18,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"wis":2}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Accustomed to twilit forests and the night sky, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Fey Ancestry","text":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."}],"lineage":"","age":{"mature":100,"max":750},"heightWeight":null,"options":[{"id":"elf-zendikar-psz--joraga-nation","name":"Joraga Nation","kind":"subrace","source":"PSZ","page":19,"traits":[{"name":"Mask of the Wild","text":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."},{"name":"Elf Weapon Training","text":"You have proficiency with the longsword, shortsword, shortbow, and longbow."},{"name":"Fleet of Foot","text":"Your ground speed increases to 35 feet."}],"removes":[],"benefits":{"ability":[{"fixed":{"wis":2,"dex":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"weapon","fixed":["longsword","shortsword","shortbow","longbow"]}]},"speed":{"walk":10.5},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf2.webp"]},{"id":"elf-zendikar-psz--mul-daya-nation","name":"Mul Daya Nation","kind":"subrace","source":"PSZ","page":19,"traits":[{"name":"Superior Darkvision","text":"Your Darkvision has a radius of 120 feet."},{"name":"Mul Daya Magic","text":"You know the chill touch cantrip. When you reach 3rd level, you can cast the hex spell once with this trait and regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the darkness spell once with this trait and regain the ability to do so when you finish a long rest. Wisdom is your spellcasting ability for these spells."},{"name":"Sunlight Sensitivity","text":"You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."},{"name":"Elf Weapon Training","text":"You have proficiency with the longsword, shortsword, shortbow, and longbow."}],"removes":["Darkvision"],"benefits":{"ability":[{"fixed":{"wis":2,"str":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"weapon","fixed":["longsword","shortsword","shortbow","longbow"]}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"spell":"chill-touch-phb","name":"Chill Touch","how":"known","uses":"","at":"1"},{"spell":"hex-phb","name":"Hex","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-phb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]}]},"senses":[{"type":"darkvision","range":36}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf2.webp"]},{"id":"elf-zendikar-psz--tajuru-nation","name":"Tajuru Nation","kind":"subrace","source":"PSZ","page":18,"traits":[{"name":"Skill Versatility","text":"You have proficiency with any combination of two other skills or 5 of your choice."}],"removes":[],"benefits":{"ability":[{"fixed":{"wis":2,"cha":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common","elvish"]},{"kind":"skillToolLanguage","choose":{"from":["anySkill","anyTool"],"count":2}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf2.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Elf2.webp"]},{"id":"faerie-lfl","name":"Faerie","source":"LFL","page":null,"edition":"2024","size":["Small"],"speed":{"walk":9,"fly":"walk"},"creatureTypes":["fey"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"druidcraft-phb","name":"Druidcraft","how":"known","uses":"","at":"1"},{"spell":"faerie-fire-phb","name":"Faerie Fire","how":"innate","uses":"1/day","at":"3"},{"spell":"enlarge-reduce-phb","name":"Enlarge/Reduce","how":"innate","uses":"1/day","at":"5"}]}]}},"feats":[],"traits":[{"name":"Fairy Magic","text":"You know the druidcraft cantrip. Starting at 3rd level, you can cast the faerie fire spell with this trait. Starting at 5th level, you can also cast the enlarge/reduce spell with this trait. Once you cast faerie fire or enlarge/reduce with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"name":"Flight","text":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."},{"name":"Faerie Lineage","text":"As a native of either Lorwyn and Shadowmoor, you may gain additional traits.\n\n• Lorwyn You do not gain any additional traits.\n• Shadowmoor You have Darkvision with a range of 120 feet."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"faerie-lfl--lorwyn","name":"Lorwyn","kind":"lineage","source":"LFL","page":null,"traits":[],"removes":["Faerie Lineage"]},{"id":"faerie-lfl--shadowmoor","name":"Shadowmoor","kind":"lineage","source":"LFL","page":null,"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 120 feet."}],"removes":["Faerie Lineage"],"benefits":{"senses":[{"type":"darkvision","range":36}]}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Faerie.webp"]},{"id":"fairy-mpmm","name":"Fairy","source":"MPMM","page":14,"edition":"2014","size":["Small"],"speed":{"walk":9,"fly":"walk"},"creatureTypes":["fey"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"druidcraft-phb","name":"Druidcraft","how":"known","uses":"","at":"1"},{"spell":"faerie-fire-phb","name":"Faerie Fire","how":"innate","uses":"1/day","at":"3"},{"spell":"enlarge-reduce-phb","name":"Enlarge/Reduce","how":"innate","uses":"1/day","at":"5"}]}]}},"feats":[],"traits":[{"name":"Fairy Magic","text":"You know the druidcraft cantrip. Starting at 3rd level, you can cast the faerie fire spell with this trait. Starting at 5th level, you can also cast the enlarge/reduce spell with this trait. Once you cast faerie fire or enlarge/reduce with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"name":"Flight","text":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Fairy.webp"]},{"id":"fairy-wbtw","name":"Fairy","source":"WBtW","page":12,"edition":"2014","size":["Small"],"speed":{"walk":9,"fly":"walk"},"creatureTypes":["fey"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"druidcraft-phb","name":"Druidcraft","how":"known","uses":"","at":"1"},{"spell":"faerie-fire-phb","name":"Faerie Fire","how":"innate","uses":"1/day","at":"3"},{"spell":"enlarge-reduce-phb","name":"Enlarge/Reduce","how":"innate","uses":"1/day","at":"5"}]}]}},"feats":[],"traits":[{"name":"Flight","text":"Because of your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."},{"name":"Fairy Magic","text":"You know the druidcraft cantrip.\n\nStarting at 3rd level, you can cast the faerie fire spell with this trait. Starting at 5th level, you can also cast the enlarge/reduce spell with this trait. Once you cast faerie fire or enlarge/reduce with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/WBtW/Fairy.webp"]},{"id":"firbolg-mpmm","name":"Firbolg","source":"MPMM","page":15,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"detect-magic-phb","name":"Detect Magic","how":"innate","uses":"","at":"1"},{"spell":"disguise-self-phb","name":"Disguise Self","how":"innate","uses":"","at":"1"}]}]}},"feats":[],"traits":[{"name":"Firbolg Magic","text":"You can cast detect magic and disguise self spells with this trait. When you use this version of disguise self, you can seem up to 3 feet shorter or taller. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"name":"Hidden Step","text":"As a bonus action, you can magically turn invisible until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Speech of Beast and Leaf","text":"You have the ability to communicate in a limited manner with Beasts, Plants, and vegetation. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."}],"lineage":"VRGR","age":{"mature":null,"max":500},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Firbolg.webp"]},{"id":"firbolg-vgm","name":"Firbolg","source":"VGM","page":107,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"wis":2}}],"proficiencies":[{"kind":"language","fixed":["common","elvish","giant"]}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"spell":"detect-magic-phb","name":"Detect Magic","how":"known","uses":"1/rest","at":"1"},{"spell":"disguise-self-phb","name":"Disguise Self","how":"known","uses":"1/rest","at":"1"}]}]}},"feats":[],"traits":[{"name":"Firbolg Magic","text":"You can cast detect magic and disguise self with this trait, using Wisdom as your spellcasting ability for them. Once you cast either spell, you can't cast it again with this trait until you finish a short or long rest. When you use this version of disguise self, you can seem up to 3 feet shorter than normal, allowing you to more easily blend in with humans and elves."},{"name":"Hidden Step","text":"As a bonus action, you can magically turn invisible until the start of your next turn or until you attack, make a damage roll, or force someone to make a saving throw. Once you use this trait, you can't use it again until you finish a short or long rest."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Speech of Beast and Leaf","text":"You have the ability to communicate in a limited manner with beasts and plants. They can understand the meaning of your words, though you have no special ability to understand them in return. You have advantage on all Charisma checks you make to influence them."}],"lineage":"","age":{"mature":30,"max":500},"heightWeight":{"baseHeight":74,"heightMod":"2d12","baseWeight":175,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Firbolg.webp"]},{"id":"flamekin-lfl","name":"Flamekin","source":"LFL","page":null,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"produce-flame-xphb","name":"Produce Flame","how":"known","uses":"","at":"1"},{"spell":"burning-hands-xphb","name":"Burning Hands","how":"innate","uses":"1/day","at":"3"},{"spell":"flame-blade-xphb","name":"Flame Blade","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["fire"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fire Resistance","text":"You have resistance to fire damage."},{"name":"Reach to the Blaze","text":"You know the produce flame cantrip. Starting at 3rd level, you can cast the burning hands spell with this trait. Starting at 5th level, you can also cast the flame blade spell with this trait, without a material component. Once you cast burning hands or flame blade with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"lineage":"","age":{"mature":null,"max":120},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Flamekin.webp"]},{"id":"genasi-eepc","name":"Genasi","source":"EEPC","page":9,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2}}],"proficiencies":[{"kind":"language","fixed":["common","primordial"]}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":120},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[{"id":"genasi-eepc--air","name":"Air","kind":"subrace","source":"EEPC","page":9,"traits":[{"name":"Unending Breath","text":"You can hold your breath indefinitely while you're not incapacitated."},{"name":"Mingle with the Wind","text":"You can cast the levitate spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"dex":1}}],"spells":{"ability":{"fixed":"con"},"groups":[{"name":"","items":[{"spell":"levitate-phb","name":"Levitate","how":"known","uses":"","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EEPC/Genasi.webp"]},{"id":"genasi-eepc--earth","name":"Earth","kind":"subrace","source":"EEPC","page":9,"traits":[{"name":"Earth Walk","text":"You can move across 3 made of earth or stone without expending extra movement."},{"name":"Merge with Stone","text":"You can cast the pass without trace spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"str":1}}],"spells":{"ability":{"fixed":"con"},"groups":[{"name":"","items":[{"spell":"pass-without-trace-phb","name":"Pass without Trace","how":"known","uses":"","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EEPC/Genasi.webp"]},{"id":"genasi-eepc--fire","name":"Fire","kind":"subrace","source":"EEPC","page":9,"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. Your ties to the Elemental Plane of Fire make your darkvision unusual: everything you see in darkness is in a shade of red."},{"name":"Fire Resistance","text":"You have resistance to fire damage."},{"name":"Reach to the Blaze","text":"You know the produce flame cantrip. Once you reach 3rd level, you can cast the burning hands spell once with this trait as a 1st-level spell, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"int":1}}],"spells":{"ability":{"fixed":"con"},"groups":[{"name":"","items":[{"spell":"produce-flame-phb","name":"Produce Flame","how":"known","uses":"","at":"1"},{"spell":"burning-hands-phb","name":"Burning Hands","how":"innate","uses":"1/day","at":"3"}]}]},"resist":{"fixed":["fire"]},"senses":[{"type":"darkvision","range":18}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EEPC/Genasi.webp"]},{"id":"genasi-eepc--water","name":"Water","kind":"subrace","source":"EEPC","page":10,"traits":[{"name":"Acid Resistance","text":"You have resistance to acid damage."},{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Swim","text":"You have a swimming speed of 30 feet."},{"name":"Call to the Wave","text":"You know the shape water cantrip. When you reach 3rd level, you can cast the create or destroy water spell as a 2nd-level spell once with this trait, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2,"wis":1}}],"spells":{"ability":{"fixed":"con"},"groups":[{"name":"","items":[{"spell":"shape-water-xge","name":"Shape Water","how":"known","uses":"","at":"1"},{"spell":null,"name":"Create Or Destroy Water#2","how":"innate","uses":"1/day","at":"3"}]}]},"resist":{"fixed":["acid"]}},"speed":{"walk":9,"swim":9},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EEPC/Genasi.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EEPC/Genasi.webp"]},{"id":"genasi-mpmm","name":"Genasi","source":"MPMM","page":16,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."}],"lineage":"VRGR","age":{"mature":null,"max":120},"heightWeight":null,"options":[{"id":"genasi-mpmm--air","name":"Air","kind":"subrace","source":"MPMM","page":16,"traits":[{"name":"Unending Breath","text":"You can hold your breath indefinitely while you're not incapacitated."},{"name":"Lightning Resistance","text":"You have resistance to lightning damage."},{"name":"Mingle with the Wind","text":"You know the shocking grasp cantrip. Starting at 3rd level, you can cast the feather fall spell with this trait, without requiring a material component. Starting 5th level, you can also cast the levitate spell with this trait, without requiring a material component. Once you cast feather fall or levitate with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"removes":[],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"shocking-grasp-phb","name":"Shocking Grasp","how":"known","uses":"","at":"1"},{"spell":"feather-fall-phb","name":"Feather Fall","how":"innate","uses":"1/day","at":"3"},{"spell":"levitate-phb","name":"Levitate","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["lightning"]}},"speed":{"walk":10.5},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Genasi.webp"]},{"id":"genasi-mpmm--earth","name":"Earth","kind":"subrace","source":"MPMM","page":17,"traits":[{"name":"Earth Walk","text":"You can move across 3 without expending extra movement if you are using your walking speed on the ground or a floor."},{"name":"Merge with Stone","text":"You know the blade ward cantrip. You can cast it as normal, and you can also cast it as a bonus action a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest.\n\nStarting at 5th level, you can cast the pass without trace spell with this trait, without requiring a material component. Once you cast that spell with this trait, you can't do so again until you finish a long rest. You can also cast it using any spell slots you have of 2nd level or higher.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"removes":[],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"blade-ward-phb","name":"Blade Ward","how":"known","uses":"","at":"1"},{"spell":"pass-without-trace-phb","name":"Pass without Trace","how":"innate","uses":"","at":"5"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Genasi.webp"]},{"id":"genasi-mpmm--fire","name":"Fire","kind":"subrace","source":"MPMM","page":17,"traits":[{"name":"Fire Resistance","text":"You have resistance to fire damage."},{"name":"Reach to the Blaze","text":"You know the produce flame cantrip. Starting at 3rd level, you can cast the burning hands spell with this trait. Starting at 5th level, you can also cast the flame blade spell with this trait, without a material component. Once you cast burning hands or flame blade with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"removes":[],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"produce-flame-phb","name":"Produce Flame","how":"known","uses":"","at":"1"},{"spell":"burning-hands-phb","name":"Burning Hands","how":"innate","uses":"1/day","at":"3"},{"spell":"flame-blade-phb","name":"Flame Blade","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["fire"]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Genasi.webp"]},{"id":"genasi-mpmm--water","name":"Water","kind":"subrace","source":"MPMM","page":17,"traits":[{"name":"Acid Resistance","text":"You have resistance to acid damage."},{"name":"Amphibious","text":"You breathe air and water."},{"name":"Call to the Wave","text":"You know the acid splash cantrip. Starting at 3rd level, you can cast the create or destroy water spell with this trait. Starting at 5th level, you can also cast the water walk spell with this trait, without requiring a material component. Once you cast create or destroy water or water walk with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"removes":[],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"acid-splash-phb","name":"Acid Splash","how":"known","uses":"","at":"1"},{"spell":"create-or-destroy-water-phb","name":"Create or Destroy Water","how":"innate","uses":"1/day","at":"3"},{"spell":"water-walk-phb","name":"Water Walk","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["acid"]}},"speed":{"walk":9,"swim":"walk"},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Genasi.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Genasi.webp"]},{"id":"giff-aag","name":"Giff","source":"AAG","page":12,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}},{"kind":"weapon","fixed":["firearms"]}]},"feats":[],"traits":[{"name":"Astral Spark","text":"Your psychic connection to the Astral Plane enables you to mystically access a spark of divine power, which you can channel through your weapons. When you hit a target with a simple or martial weapon, you can cause the target to take extra force damage equal to your proficiency bonus.\n\nYou can use this trait a number of times equal to your proficiency bonus, but you can use it no more than once per turn. You regain all expended uses when you finish a long rest."},{"name":"Firearms Mastery","text":"You have a mystical connection to firearms that traces back to the gods of the giff, who delighted in such weapons. You have proficiency with all firearms and ignore the loading property of any firearm. In addition, attacking at long range with a firearm doesn't impose disadvantage on your attack roll."},{"name":"Hippo Build","text":"You have advantage on Strength-based ability checks and Strength saving throws. In addition, you count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AAG/Giff.webp"]},{"id":"gith-mtf","name":"Gith","source":"MTF","page":96,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":1}}],"proficiencies":[{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[{"id":"gith-mtf--githyanki","name":"Githyanki","kind":"subrace","source":"MTF","page":96,"traits":[{"name":"Decadent Mastery","text":"You learn one language of your choice, and you are proficient with one skill or 5 of your choice. In the timeless city of Tu'narath, githyanki have bountiful time to master odd bits of knowledge."},{"name":"Martial Prodigy","text":"You are proficient with light and medium armor and with shortswords, longswords, and greatswords."},{"name":"Githyanki Psionics","text":"You know the mage hand cantrip, and the hand is invisible when you cast the cantrip with this trait.\n\nWhen you reach 3rd level, you can cast jump once with this trait, and you regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the misty step spell once with this trait, and you regain the ability to do so when you finish a long rest.\n\nIntelligence is your spellcasting ability for these spells. When you cast them with this trait, they don't require components."}],"removes":[],"benefits":{"ability":[{"fixed":{"int":1,"str":2}}],"proficiencies":[{"kind":"language","fixed":["common","other"]},{"kind":"weapon","fixed":["shortsword","longsword","greatsword"]},{"kind":"armor","fixed":["light","medium"]},{"kind":"skillToolLanguage","choose":{"from":["anySkill","anyTool"],"count":1}}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"spell":"mage-hand-phb","name":"Mage Hand","how":"known","uses":"","at":"1"},{"spell":"jump-phb","name":"Jump","how":"innate","uses":"1/day","at":"3"},{"spell":"misty-step-phb","name":"Misty Step","how":"innate","uses":"1/day","at":"5"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MTF/Githyanki.webp"]},{"id":"gith-mtf--githzerai","name":"Githzerai","kind":"subrace","source":"MTF","page":96,"traits":[{"name":"Mental Discipline","text":"You have advantage on saving throws against the charmed and frightened conditions. Under the tutelage of monastic masters, githzerai learn to govern their own minds."},{"name":"Githzerai Psionics","text":"You know the mage hand cantrip, and the hand is invisible when you cast the cantrip with this trait.\n\nWhen you reach 3rd level, you can cast shield once with this trait, and you regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the detect thoughts spell once with this trait, and you regain the ability to do so when you finish a long rest.\n\nWisdom is your spellcasting ability for these spells. When you cast them with this trait, they don't require components."}],"removes":[],"benefits":{"ability":[{"fixed":{"int":1,"wis":2}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"spell":"mage-hand-phb","name":"Mage Hand","how":"known","uses":"","at":"1"},{"spell":"shield-phb","name":"Shield","how":"innate","uses":"1/day","at":"3"},{"spell":"detect-thoughts-phb","name":"Detect Thoughts","how":"innate","uses":"1/day","at":"5"}]}]}}}],"description":""},{"id":"githyanki-mpmm","name":"Githyanki","source":"MPMM","page":18,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","any":{"any":1}},{"kind":"tool","any":{"any":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"mage-hand-phb","name":"Mage Hand","how":"known","uses":"","at":"1"},{"spell":"jump-phb","name":"Jump","how":"innate","uses":"1/day","at":"3"},{"spell":"misty-step-phb","name":"Misty Step","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["psychic"]}},"feats":[],"traits":[{"name":"Astral Knowledge","text":"You can mystically access a reservoir of experiences of entities connected to the Astral Plane. Whenever you finish a long rest, you gain proficiency in one skill of your choice and with one weapon or tool of your choice, selected from the Player's Handbook, as you momentarily project your consciousness into the Astral Plane. These proficiencies last until the end of your next long rest."},{"name":"Githyanki Psionics","text":"You know the mage hand cantrip, and the hand is invisible when you cast the cantrip with this trait.\n\nStarting at 3rd level, you can cast the jump spell with this trait. Starting at 5th level, you can also cast misty step with it. Once you cast jump or misty step with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race). None of these spells require spell components when you cast them with this trait."},{"name":"Psychic Resilience","text":"You have resistance to psychic damage."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Githyanki.webp"]},{"id":"githzerai-mpmm","name":"Githzerai","source":"MPMM","page":19,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"mage-hand-phb","name":"Mage Hand","how":"known","uses":"","at":"1"},{"spell":"shield-phb","name":"Shield","how":"innate","uses":"1/day","at":"3"},{"spell":"detect-thoughts-phb","name":"Detect Thoughts","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["psychic"]}},"feats":[],"traits":[{"name":"Githzerai Psionics","text":"You know the mage hand cantrip, and the hand is invisible when you cast the cantrip with this trait.\n\nStarting at 3rd level, you can cast the shield spell with this trait. Starting at 5th level, you can also cast the detect thoughts spell with it. Once you cast shield or detect thoughts spell with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast either of those spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race). None of these spells require spell components when you cast them with this trait."},{"name":"Mental Discipline","text":"Your innate psychic defenses grant you advantage on saving throws you make to avoid or end the charmed and frightened conditions on yourself."},{"name":"Psychic Resilience","text":"You have resistance to psychic damage."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Githzerai.webp"]},{"id":"gnoll-dmg","name":"Gnoll","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"int":-2}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Bite","text":"Your fanged maw is a natural weapon, which you can use to make unarmed strikes. If you hit with it, you deal piercing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Rampage","text":"When you reduce a creature to 0 hit points with a melee attack on your turn, you can take a bonus action to move up to half your speed and make a bite attack."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"gnome-phb","name":"Gnome","source":"PHB","page":35,"edition":"2014","size":["Small"],"speed":{"walk":7.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":2}}],"proficiencies":[{"kind":"language","fixed":["common","gnomish"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Gnome Cunning","text":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic."}],"lineage":"","age":{"mature":40,"max":500},"heightWeight":{"baseHeight":35,"heightMod":"2d4","baseWeight":35,"weightMod":""},"options":[{"id":"gnome-phb--deep-mtf","name":"Deep","kind":"subrace","source":"MTF","page":113,"traits":[{"name":"Superior Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Stone Camouflage","text":"You have advantage on Dexterity (Stealth) checks to hide in rocky terrain."}],"removes":["Darkvision"],"benefits":{"ability":[{"fixed":{"int":2,"dex":1}}],"proficiencies":[{"kind":"language","fixed":["common","gnomish","undercommon"]}],"senses":[{"type":"darkvision","range":36}]}},{"id":"gnome-phb--deep-svirfneblin-scag","name":"Deep/Svirfneblin","kind":"subrace","source":"SCAG","page":115,"traits":[{"name":"Superior Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Stone Camouflage","text":"You have advantage on Dexterity (Stealth) checks to hide in rocky terrain."}],"removes":["Darkvision"],"benefits":{"ability":[{"fixed":{"int":2,"dex":1}}],"proficiencies":[{"kind":"language","fixed":["common","gnomish","undercommon"]}],"senses":[{"type":"darkvision","range":36}]}},{"id":"gnome-phb--forest","name":"Forest","kind":"subrace","source":"PHB","page":37,"traits":[{"name":"Natural Illusionist","text":"You know the minor illusion cantrip. Intelligence is your spellcasting ability for it."},{"name":"Speak with Small Beasts","text":"Through sounds and gestures, you can communicate simple ideas with Small or smaller beasts. Forest gnomes love animals and often keep squirrels, badgers, rabbits, moles, woodpeckers, and other creatures as beloved pets."}],"removes":[],"benefits":{"ability":[{"fixed":{"int":2,"dex":1}}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"spell":"minor-illusion-phb","name":"Minor Illusion","how":"known","uses":"","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Gnome.webp"]},{"id":"gnome-phb--mark-of-scribing-erlw","name":"Mark of Scribing","kind":"subrace","source":"ERLW","page":47,"traits":[{"name":"Gifted Scribe","text":"When you make an Intelligence (History) check or an ability check using calligrapher's supplies, you can roll a d4 and add the number rolled to the ability check."},{"name":"Scribe's Insight","text":"You know the message cantrip. You can also cast comprehend languages once with this trait, and you regain the ability to cast it when you finish a short or long rest. Starting at 3rd level, you can cast the magic mouth spell with this trait, and you regain the ability to cast it when you finish a long rest. Intelligence is your spellcasting ability for these spells."},{"name":"Spells of the Mark","text":"If you have the Spellcasting or the Pact Magic class feature, the spells on the Mark of Scribing Spells table are added to the spell list of your spellcasting class.\n\nMark of Scribing Spells:\n| Spell Level | Spells |\n| 1st | comprehend languages, illusory script |\n| 2nd | animal messenger, silence |\n| 3rd | sending, tongues |\n| 4th | arcane eye, confusion |\n| 5th | dream |"}],"removes":[],"benefits":{"ability":[{"fixed":{"int":2,"cha":1}}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"spell":"message-phb","name":"Message","how":"known","uses":"","at":"1"},{"spell":"comprehend-languages-phb","name":"Comprehend Languages","how":"innate","uses":"1/rest","at":"1"},{"spell":"magic-mouth-phb","name":"Magic Mouth","how":"innate","uses":"1/day","at":"3"},{"spell":"comprehend-languages-phb","name":"Comprehend Languages","how":"expanded","uses":"","at":"s1"},{"spell":"illusory-script-phb","name":"Illusory Script","how":"expanded","uses":"","at":"s1"},{"spell":"animal-messenger-phb","name":"Animal Messenger","how":"expanded","uses":"","at":"s2"},{"spell":"silence-phb","name":"Silence","how":"expanded","uses":"","at":"s2"},{"spell":"sending-phb","name":"Sending","how":"expanded","uses":"","at":"s3"},{"spell":"tongues-phb","name":"Tongues","how":"expanded","uses":"","at":"s3"},{"spell":"arcane-eye-phb","name":"Arcane Eye","how":"expanded","uses":"","at":"s4"},{"spell":"confusion-phb","name":"Confusion","how":"expanded","uses":"","at":"s4"},{"spell":"dream-phb","name":"Dream","how":"expanded","uses":"","at":"s5"}]}]}}},{"id":"gnome-phb--rock","name":"Rock","kind":"subrace","source":"PHB","page":37,"traits":[{"name":"Artificer's Lore","text":"Whenever you make an Intelligence (History) check related to magic items, alchemical objects, or technological devices, you can add twice your proficiency bonus, instead of any proficiency bonus you normally apply."},{"name":"Tinker","text":"You have proficiency with artisan's tools (tinker's tools). Using those tools, you can spend 1 hour and 10 gp worth of materials to construct a Tiny clockwork device (AC 5, 1 hp). The device ceases to function after 24 hours (unless you spend 1 hour repairing it to keep the device functioning), or when you use your action to dismantle it; at that time, you can reclaim the materials used to create it. You can have up to three such devices active at a time.\n\nWhen you create a device, choose one of the following options:\n\nClockwork Toy. This toy is a clockwork animal, monster, or person, such as a frog, mouse, bird, dragon, or soldier. When placed on the ground, the toy moves 5 feet across the ground on each of your turns in a random direction. It makes noises as appropriate to the creature it represents.\n\nFire Starter. The device produces a miniature flame, which you can use to light a candle, torch, or campfire. Using the device requires your action.\n\nMusic Box. When opened, this music box plays a single song at a moderate volume. The box stops playing when it reaches the song's end or when it is closed."}],"removes":[],"benefits":{"ability":[{"fixed":{"int":2,"con":1}}],"proficiencies":[{"kind":"tool","fixed":["tinker's tools"]},{"kind":"language","fixed":["common","gnomish"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Gnome.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Gnome.webp"],"srd":true},{"id":"gnome-xphb","name":"Gnome","source":"XPHB","page":191,"edition":"2024","size":["Small"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"Forest Gnome","items":[{"spell":"minor-illusion-xphb","name":"Minor Illusion","how":"known","uses":"","at":"1"},{"spell":"speak-with-animals-xphb","name":"Speak with Animals","how":"innate","uses":"pb/day","at":"1"}]},{"name":"Rock Gnome","items":[{"spell":"mending-xphb","name":"Mending","how":"known","uses":"","at":"1"},{"spell":"prestidigitation-xphb","name":"Prestidigitation","how":"known","uses":"","at":"1"}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Gnomish Cunning","text":"You have Advantage on Intelligence, Wisdom, and Charisma saving throws."},{"name":"Gnomish Lineage","text":"You are part of a lineage that grants you supernatural abilities. Choose one of the following options; whichever one you choose, Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the lineage):\n\n• Forest Gnome You know the Minor Illusion cantrip. You also always have the Speak with Animals spell prepared. You can cast it without a spell slot a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. You can also use any spell slots you have to cast the spell.\n• Rock Gnome You know the Mending and Prestidigitation cantrips. In addition, you can spend 10 minutes casting Prestidigitation to create a Tiny clockwork device (AC 5, 1 HP), such as a toy, fire starter, or music box. When you create the device, you determine its function by choosing one effect from Prestidigitation; the device produces that effect whenever you or another creature takes a Bonus Action to activate it with a touch. If the chosen effect has options within it, you choose one of those options for the device when you create it. For example, if you choose the spell's ignite-extinguish effect, you determine whether the device ignites or extinguishes fire; the device doesn't do both. You can have three such devices in existence at a time, and each falls apart 8 hours after its creation or when you dismantle it with a touch as a Utilize action."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"gnome-xphb--forest-gnome-lineage","name":"Forest Gnome Lineage","kind":"lineage","source":"XPHB","page":191,"traits":[{"name":"Gnomish Lineage (Forest Gnome)","text":"You know the Minor Illusion cantrip. You also always have the Speak with Animals spell prepared. You can cast it without a spell slot a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. You can also use any spell slots you have to cast the spell."}],"removes":["Gnomish Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"minor-illusion-xphb","name":"Minor Illusion","how":"known","uses":"","at":"1"},{"spell":"speak-with-animals-xphb","name":"Speak with Animals","how":"innate","uses":"pb/day","at":"1"}]}]}}},{"id":"gnome-xphb--rock-gnome-lineage","name":"Rock Gnome Lineage","kind":"lineage","source":"XPHB","page":191,"traits":[{"name":"Gnomish Lineage (Rock Gnome)","text":"You know the Mending and Prestidigitation cantrips. In addition, you can spend 10 minutes casting Prestidigitation to create a Tiny clockwork device (AC 5, 1 HP), such as a toy, fire starter, or music box. When you create the device, you determine its function by choosing one effect from Prestidigitation; the device produces that effect whenever you or another creature takes a Bonus Action to activate it with a touch. If the chosen effect has options within it, you choose one of those options for the device when you create it. For example, if you choose the spell's ignite-extinguish effect, you determine whether the device ignites or extinguishes fire; the device doesn't do both. You can have three such devices in existence at a time, and each falls apart 8 hours after its creation or when you dismantle it with a touch as a Utilize action."}],"removes":["Gnomish Lineage"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"mending-xphb","name":"Mending","how":"known","uses":"","at":"1"},{"spell":"prestidigitation-xphb","name":"Prestidigitation","how":"known","uses":"","at":"1"}]}]}}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Gnome.webp"],"srd":true},{"id":"gnome-deep-dmg","name":"Gnome (Deep)","source":"DMG","page":282,"edition":"2014","size":["Small"],"speed":{"walk":6},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"dex":2}}],"proficiencies":[{"kind":"language","fixed":["gnomish","terran","undercommon"]}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"spell":"nondetection-phb","name":"Nondetection","how":"known","uses":"","at":"1"},{"spell":"blindness-deafness-phb","name":"Blindness/Deafness","how":"known","uses":"","at":"1"},{"spell":"blur-phb","name":"Blur","how":"known","uses":"","at":"1"},{"spell":"disguise-self-phb","name":"Disguise Self","how":"known","uses":"","at":"1"}]}]},"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Innate Spellcasting","text":"You have an innate ability to cast the following spells, requiring no material components:\n\n• At will: nondetection (self only)\n• 1/day each: blindness/deafness, blur, disguise self\n\nIntelligence is your spellcasting ability for these spells."},{"name":"Stone Camouflage","text":"You have advantage on Dexterity (Stealth) checks to hide in rocky terrain."},{"name":"Gnome Cunning","text":"You have advantage on Intelligence, Wisdom, and Charisma saving throws against magic."},{"name":"Superior Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"goblin-dmg","name":"Goblin","source":"DMG","page":282,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":-2,"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."},{"name":"Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"goblin-erlw","name":"Goblin","source":"ERLW","page":26,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Fury of the Small","text":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."},{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."}],"lineage":"","age":{"mature":8,"max":60},"heightWeight":{"baseHeight":41,"heightMod":"2d4","baseWeight":35,"weightMod":""},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Goblinoids.webp"]},{"id":"goblin-ggr","name":"Goblin","source":"GGR","page":16,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Fury of the Small","text":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."},{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."}],"lineage":"","age":{"mature":8,"max":60},"heightWeight":{"baseHeight":41,"heightMod":"2d4","baseWeight":35,"weightMod":""},"options":[],"description":""},{"id":"goblin-mpmm","name":"Goblin","source":"MPMM","page":20,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Fury of the Small","text":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your proficiency bonus.\n\nYou can use this trait a number of times equal to your proficiency bonus, regaining all expended uses when you finish a long rest, and you can use it no more than once per turn."},{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Goblin.webp"]},{"id":"goblin-psz","name":"Goblin","source":"PSZ","page":16,"edition":"","size":["Small"],"speed":{"walk":7.5},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"resist":{"fixed":["fire","psychic"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Grit","text":"You have resistance to fire damage and psychic damage. In addition, when you are wearing no armor, your AC is equal to 11 + your Dexterity modifier."}],"lineage":"","age":{"mature":12,"max":50},"heightWeight":null,"options":[{"id":"goblin-psz--ixalan-psx","name":"Ixalan","kind":"subrace","source":"PSX","page":16,"traits":[{"name":"Agile Climber","text":"You have a climbing speed of 25 feet. You can't use your climbing speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can't use your climbing speed if you are encumbered.)"}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Goblin.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Goblin2.webp"]},{"id":"goblin-psz--zendikar-grotag-tribe","name":"Zendikar; Grotag Tribe","kind":"subrace","source":"PSZ","page":17,"traits":[{"name":"Grotag Tamer","text":"You have proficiency in the Animal Handling skill."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2}}],"proficiencies":[{"kind":"skill","fixed":["animal handling"]},{"kind":"language","fixed":["common","goblin"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin2.webp"]},{"id":"goblin-psz--zendikar-lavastep-tribe","name":"Zendikar; Lavastep Tribe","kind":"subrace","source":"PSZ","page":17,"traits":[{"name":"Lavastep Grit","text":"You have advantage on Dexterity (Stealth) checks made to hide in rocky or subterranean environments."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin2.webp"]},{"id":"goblin-psz--zendikar-tuktuk-tribe","name":"Zendikar; Tuktuk Tribe","kind":"subrace","source":"PSZ","page":17,"traits":[{"name":"Tuktuk Cunning","text":"You have proficiency with thieves' tools."}],"removes":[],"benefits":{"ability":[{"fixed":{"con":2}}],"proficiencies":[{"kind":"tool","fixed":["thieves' tools"]},{"kind":"language","fixed":["common","goblin"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin2.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Goblin2.webp"]},{"id":"goblin-vgm","name":"Goblin","source":"VGM","page":119,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Fury of the Small","text":"When you damage a creature with an attack or a spell and the creature's size is larger than yours, you can cause the attack or spell to deal extra damage to the creature. The extra damage equals your level. Once you use this trait, you can't use it again until you finish a short or long rest."},{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."}],"lineage":"","age":{"mature":8,"max":60},"heightWeight":{"baseHeight":41,"heightMod":"2d4","baseWeight":35,"weightMod":""},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Goblin.webp"]},{"id":"goblin-dankwood-awm","name":"Goblin (Dankwood)","source":"AWM","page":35,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Speak with Small Beasts","text":"Through sounds and gestures, you can communicate simple ideas with Small or smaller beasts. Dankwood goblins love animals and often keep squirrels, badgers, rabbits, moles, woodpeckers, and other creatures as beloved pets."},{"name":"Nimble Escape","text":"You can take the Disengage or Hide action as a bonus action on each of your turns."}],"lineage":"","age":{"mature":8,"max":60},"heightWeight":null,"options":[],"description":""},{"id":"goliath-mpmm","name":"Goliath","source":"MPMM","page":21,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["athletics"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["cold"]}},"feats":[],"traits":[{"name":"Little Giant","text":"You have proficiency in the Athletics skill, and you count as one size larger when determining your carrying weight and the weight you can push, drag, or lift."},{"name":"Mountain Born","text":"You have resistance to cold damage. You also naturally acclimate to high altitudes, even if you've never been to one. This includes elevations above 20,000 feet."},{"name":"Stone's Endurance","text":"You can supernaturally draw on unyielding stone to shrug off harm. When you take damage, you can use your reaction to roll a d12. Add your Constitution modifier to the number rolled and reduce the damage by that total.\n\nYou can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Goliath.webp"]},{"id":"goliath-vgm","name":"Goliath","source":"VGM","page":108,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["athletics"]},{"kind":"language","fixed":["common","giant"]}],"resist":{"fixed":["cold"]}},"feats":[],"traits":[{"name":"Natural Athlete","text":"You have proficiency in the Athletics skill."},{"name":"Stone's Endurance","text":"You can focus yourself to occasionally shrug off injury. When you take damage, you can use your reaction to roll a d12. Add your Constitution modifier to the number rolled, and reduce the damage by that total. After you use this trait, you can't use it again until you finish a short or long rest."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Mountain Born","text":"You have resistance to cold damage. You're also acclimated to high altitude, including elevations above 20,000 feet."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":74,"heightMod":"2d10","baseWeight":200,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Goliath.webp"]},{"id":"goliath-xphb","name":"Goliath","source":"XPHB","page":192,"edition":"2024","size":["Medium"],"speed":{"walk":10.5},"creatureTypes":["humanoid"],"benefits":{},"feats":[],"traits":[{"name":"Giant Ancestry","text":"You are descended from Giants. Choose one of the following benefits—a supernatural boon from your ancestry; you can use the chosen benefit a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Cloud's Jaunt (Cloud Giant) As a Bonus Action, you magically teleport up to 30 feet to an unoccupied space you can see.\n• Fire's Burn (Fire Giant) When you hit a target with an attack roll and deal damage to it, you can also deal 1d10 Fire damage to that target.\n• Frost's Chill (Frost Giant) When you hit a target with an attack roll and deal damage to it, you can also deal 1d6 Cold damage to that target and reduce its Speed by 10 feet until the start of your next turn.\n• Hill's Tumble (Hill Giant) When you hit a Large or smaller creature with an attack roll and deal damage to it, you can give that target the Prone condition.\n• Stone's Endurance (Stone Giant) When you take damage, you can take a Reaction to roll 1d12. Add your Constitution modifier to the number rolled and reduce the damage by that total.\n• Storm's Thunder (Storm Giant) When you take damage from a creature within 60 feet of you, you can take a Reaction to deal 1d8 Thunder damage to that creature."},{"name":"Large Form","text":"Starting at character level 5, you can change your size to Large as a Bonus Action if you're in a big enough space. This transformation lasts for 10 minutes or until you end it (no action required). For that duration, you have Advantage on Strength checks, and your Speed increases by 10 feet. Once you use this trait, you can't use it again until you finish a Long Rest."},{"name":"Powerful Build","text":"You have Advantage on any ability check you make to end the Grappled condition. You also count as one size larger when determining your carrying capacity."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"goliath-xphb--cloud-giant-ancestry","name":"Cloud Giant Ancestry","kind":"lineage","source":"XPHB","page":192,"traits":[{"name":"Giant Ancestry (Cloud)","text":"You are descended from Giants, granting you a supernatural boon; you can use this boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Cloud's Jaunt As a Bonus Action, you magically teleport up to 30 feet to an unoccupied space you can see."}],"removes":["Giant Ancestry"]},{"id":"goliath-xphb--fire-giant-ancestry","name":"Fire Giant Ancestry","kind":"lineage","source":"XPHB","page":192,"traits":[{"name":"Giant Ancestry (Fire)","text":"You are descended from Giants, granting you a supernatural boon; you can use this boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Fire's Burn When you hit a target with an attack roll and deal damage to it, you can also deal 1d10 Fire damage to that target."}],"removes":["Giant Ancestry"]},{"id":"goliath-xphb--frost-giant-ancestry","name":"Frost Giant Ancestry","kind":"lineage","source":"XPHB","page":192,"traits":[{"name":"Giant Ancestry (Frost)","text":"You are descended from Giants, granting you a supernatural boon; you can use this boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Frost's Chill When you hit a target with an attack roll and deal damage to it, you can also deal 1d6 Cold damage to that target and reduce its Speed by 10 feet until the start of your next turn."}],"removes":["Giant Ancestry"]},{"id":"goliath-xphb--hill-giant-ancestry","name":"Hill Giant Ancestry","kind":"lineage","source":"XPHB","page":192,"traits":[{"name":"Giant Ancestry (Hill)","text":"You are descended from Giants, granting you a supernatural boon; you can use this boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Hill's Tumble When you hit a Large or smaller creature with an attack roll and deal damage to it, you can give that target the Prone condition."}],"removes":["Giant Ancestry"]},{"id":"goliath-xphb--stone-giant-ancestry","name":"Stone Giant Ancestry","kind":"lineage","source":"XPHB","page":192,"traits":[{"name":"Giant Ancestry (Stone)","text":"You are descended from Giants, granting you a supernatural boon; you can use this boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Stone's Endurance When you take damage, you can take a Reaction to roll 1d12. Add your Constitution modifier to the number rolled and reduce the damage by that total."}],"removes":["Giant Ancestry"]},{"id":"goliath-xphb--storm-giant-ancestry","name":"Storm Giant Ancestry","kind":"lineage","source":"XPHB","page":192,"traits":[{"name":"Giant Ancestry (Storm)","text":"You are descended from Giants, granting you a supernatural boon; you can use this boon a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest:\n\n• Storm's Thunder When you take damage from a creature within 60 feet of you, you can take a Reaction to deal 1d8 Thunder damage to that creature."}],"removes":["Giant Ancestry"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Goliath.webp"],"srd":true},{"id":"grimlock-dmg","name":"Grimlock","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"cha":-2}}],"proficiencies":[{"kind":"language","fixed":["undercommon"]}],"senses":[{"type":"blindsight","range":9}]},"feats":[],"traits":[{"name":"Blindsight","text":"You have no eyes, and cannot be blinded. You can perceive your surroundings within 30 ft., or 10 ft. while deafened. You are considered blind beyond this radius."},{"name":"Keen Hearing and Smell","text":"You have advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Stone Camouflage","text":"You have advantage on Dexterity (Stealth) checks made to hide in rocky terrain."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"grung-oga","name":"Grung","source":"OGA","page":4,"edition":"2014","size":["Small"],"speed":{"walk":7.5,"climb":7.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["other"]}],"immune":{"fixed":["poison"]},"conditionImmune":{"fixed":["poisoned"]}},"feats":[],"traits":[{"name":"Arboreal Alertness","text":"You have proficiency in the Perception skill."},{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Poison Immunity","text":"You're immune to poison damage and the poisoned condition."},{"name":"Poisonous Skin","text":"Any creature that grapples you or otherwise comes into direct contact with your skin must succeed on a DC 12 Constitution saving throw or become poisoned for 1 minute. A poisoned creature no longer in direct contact with you can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n\nYou can also apply this poison to any piercing weapon as part of an attack with that weapon, though when you hit the poison reacts differently. The target must succeed on a DC 12 Constitution saving throw or take 2d4 poison damage."},{"name":"Standing Leap","text":"Your long jump is up to 25 feet and your high jump is up to 15 feet, with or without a running start."},{"name":"Water Dependency","text":"If you fail to immerse yourself in water for at least 1 hour during a day, you suffer one level of exhaustion at the end of that day. You can only recover from this exhaustion through magic or by immersing yourself in water for at least 1 hour."}],"lineage":"","age":{"mature":1,"max":50},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/OGA/Grung.webp"]},{"id":"hadozee-aag","name":"Hadozee","source":"AAG","page":13,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9,"climb":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Dexterous Feet","text":"As a bonus action, you can use your feet to manipulate an object, open or close a door or container, or pick up or set down a Tiny object."},{"name":"Glide","text":"When you fall at least 10 feet above the ground, you can use your reaction to extend your skin membranes to glide horizontally a number of feet equal to your walking speed, and you take 0 damage from the fall. You determine the direction of the glide."},{"name":"Hadozee Dodge","text":"The magic that runs in your veins heightens your natural defenses. When you take damage, you can use your reaction to roll a d6. Add your proficiency bonus to the number rolled, and reduce the damage you take by an amount equal to that total (minimum of 0 damage).\n\nYou can use this trait a number of times equal to your proficiency bonus. You regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AAG/Hadozee.webp"]},{"id":"half-elf-base-phb","name":"Half-Elf (Base)","source":"PHB","page":38,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":2},"choose":{"from":["str","dex","con","int","wis"],"count":2,"amount":1}}],"proficiencies":[{"kind":"skill","any":{"any":2}},{"kind":"language","fixed":["common","elvish"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Thanks to your elf blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws against being charmed, and magic can't put you to sleep."},{"name":"Skill Versatility","text":"You gain proficiency in two skills of your choice."}],"lineage":"","age":{"mature":20,"max":180},"heightWeight":{"baseHeight":57,"heightMod":"2d8","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Half-Elf.webp"],"srd":true},{"id":"half-orc-base-phb","name":"Half-Orc (Base)","source":"PHB","page":40,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["intimidation"]},{"kind":"language","fixed":["common","orc"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Thanks to your orc blood, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Menacing","text":"You gain proficiency in the Intimidation skill."},{"name":"Relentless Endurance","text":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."},{"name":"Savage Attacks","text":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."}],"lineage":"","age":{"mature":14,"max":75},"heightWeight":{"baseHeight":58,"heightMod":"2d10","baseWeight":140,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Half-Orc.webp"],"srd":true},{"id":"halfling-phb","name":"Halfling","source":"PHB","page":26,"edition":"2014","size":["Small"],"speed":{"walk":7.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","halfling"]}]},"feats":[],"traits":[{"name":"Lucky","text":"When you roll a 1 on an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll."},{"name":"Brave","text":"You have advantage on saving throws against being frightened."},{"name":"Halfling Nimbleness","text":"You can move through the space of any creature that is of a size larger than yours."}],"lineage":"","age":{"mature":20,"max":250},"heightWeight":{"baseHeight":31,"heightMod":"2d4","baseWeight":35,"weightMod":""},"options":[{"id":"halfling-phb--ghostwise-scag","name":"Ghostwise","kind":"subrace","source":"SCAG","page":110,"traits":[{"name":"Silent Speech","text":"You can speak telepathically to any creature within 30 feet of you. The creature understands you only if the two of you share a language. You can speak telepathically in this way to one creature at a time."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Halfling.webp"]},{"id":"halfling-phb--lightfoot","name":"Lightfoot","kind":"subrace","source":"PHB","page":28,"traits":[{"name":"Naturally Stealthy","text":"You can attempt to hide even when you are obscured only by a creature that is at least one size larger than you."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Halfling.webp"]},{"id":"halfling-phb--lotusden-egw","name":"Lotusden","kind":"subrace","source":"EGW","page":164,"traits":[{"name":"Child of the Wood","text":"You know the druidcraft cantrip. When you reach 3rd level, you can cast the entangle spell once with this trait and regain the ability to do so when you finish a long rest. When you reach 5th level, you can cast the spike growth spell once with this trait and regain the ability to do so when you finish a long rest. Casting these spells with this trait doesn't require material components. Wisdom is your spellcasting ability for these spells."},{"name":"Timberwalk","text":"Ability checks made to track you have disadvantage, and you can move across 3 made of nonmagical plants and undergrowth without expending extra movement."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"spell":"druidcraft-phb","name":"Druidcraft","how":"known","uses":"","at":"1"},{"spell":"entangle-phb","name":"Entangle","how":"innate","uses":"1/day","at":"3"},{"spell":"spike-growth-phb","name":"Spike Growth","how":"innate","uses":"1/day","at":"5"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EGW/Halfling%20(Lotusden).webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Halfling.webp"]},{"id":"halfling-phb--mark-of-healing-erlw","name":"Mark of Healing","kind":"subrace","source":"ERLW","page":43,"traits":[{"name":"Medical Intuition","text":"When you make a Wisdom (Medicine) check or an ability check using an herbalism kit, you can roll a d4 and add the number rolled to the ability check."},{"name":"Healing Touch","text":"You can cast the cure wounds spell with this trait. Starting at 3rd level, you can also cast lesser restoration with it. Once you cast either spell with this trait, you can't cast that spell with it again until you finish a long rest. Wisdom is your spellcasting ability for these spells."},{"name":"Spells of the Mark","text":"If you have the Spellcasting or the Pact Magic class feature, the spells on the Mark of Healing Spells table are added to the spell list of your spellcasting class.\n\nMark of Healing Spells:\n| Spell Level | Spells |\n| 1st | cure wounds, healing word |\n| 2nd | lesser restoration, prayer of healing |\n| 3rd | aura of vitality, mass healing word |\n| 4th | aura of purity, aura of life |\n| 5th | greater restoration |"}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"spell":"cure-wounds-phb","name":"Cure Wounds","how":"innate","uses":"","at":"1"},{"spell":"lesser-restoration-phb","name":"Lesser Restoration","how":"innate","uses":"1/day","at":"3"},{"spell":"cure-wounds-phb","name":"Cure Wounds","how":"expanded","uses":"","at":"s1"},{"spell":"healing-word-phb","name":"Healing Word","how":"expanded","uses":"","at":"s1"},{"spell":"lesser-restoration-phb","name":"Lesser Restoration","how":"expanded","uses":"","at":"s2"},{"spell":"prayer-of-healing-phb","name":"Prayer of Healing","how":"expanded","uses":"","at":"s2"},{"spell":"aura-of-vitality-phb","name":"Aura of Vitality","how":"expanded","uses":"","at":"s3"},{"spell":"mass-healing-word-phb","name":"Mass Healing Word","how":"expanded","uses":"","at":"s3"},{"spell":"aura-of-purity-phb","name":"Aura of Purity","how":"expanded","uses":"","at":"s4"},{"spell":"aura-of-life-phb","name":"Aura of Life","how":"expanded","uses":"","at":"s4"},{"spell":"greater-restoration-phb","name":"Greater Restoration","how":"expanded","uses":"","at":"s5"}]}]}}},{"id":"halfling-phb--mark-of-hospitality-erlw","name":"Mark of Hospitality","kind":"subrace","source":"ERLW","page":44,"traits":[{"name":"Ever Hospitable","text":"When you make a Charisma (Persuasion) check or an ability check involving brewer's supplies or cook's utensils, you can roll a d4 and add the number rolled to the ability check."},{"name":"Innkeeper's Magic","text":"You know the prestidigitation cantrip. You can also cast the purify food and drink and unseen servant spells with this trait. Once you cast either spell with this trait, you can't cast that spell with it again until you finish long rest. Charisma is your spellcasting ability for these spells."},{"name":"Spells of the Mark","text":"If you have the Spellcasting or the Pact Magic class feature, the spells on the Mark of Hospitality Spells table are added to the spell list of your spellcasting class.\n\nMark of Hospitality Spells:\n| Spell Level | Spells |\n| 1st | goodberry, sleep |\n| 2nd | aid, calm emotions |\n| 3rd | create food and water, Leomund's tiny hut |\n| 4th | aura of purity, Mordenkainen's private sanctum |\n| 5th | hallow |"}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"prestidigitation-phb","name":"Prestidigitation","how":"known","uses":"","at":"1"},{"spell":"purify-food-and-drink-phb","name":"Purify Food and Drink","how":"known","uses":"","at":"1"},{"spell":"unseen-servant-phb","name":"Unseen Servant","how":"known","uses":"","at":"1"},{"spell":"goodberry-phb","name":"Goodberry","how":"expanded","uses":"","at":"s1"},{"spell":"sleep-phb","name":"Sleep","how":"expanded","uses":"","at":"s1"},{"spell":"aid-phb","name":"Aid","how":"expanded","uses":"","at":"s2"},{"spell":"calm-emotions-phb","name":"Calm Emotions","how":"expanded","uses":"","at":"s2"},{"spell":"create-food-and-water-phb","name":"Create Food and Water","how":"expanded","uses":"","at":"s3"},{"spell":"leomund-s-tiny-hut-phb","name":"Leomund's Tiny Hut","how":"expanded","uses":"","at":"s3"},{"spell":"aura-of-purity-phb","name":"Aura of Purity","how":"expanded","uses":"","at":"s4"},{"spell":"mordenkainen-s-private-sanctum-phb","name":"Mordenkainen's Private Sanctum","how":"expanded","uses":"","at":"s4"},{"spell":"hallow-phb","name":"Hallow","how":"expanded","uses":"","at":"s5"}]}]}}},{"id":"halfling-phb--stout","name":"Stout","kind":"subrace","source":"PHB","page":28,"traits":[{"name":"Stout Resilience","text":"You have advantage on saving throws against poison, and you have resistance against poison damage."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"con":1}}],"resist":{"fixed":["poison"]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Halfling.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Halfling.webp"],"srd":true},{"id":"halfling-xphb","name":"Halfling","source":"XPHB","page":193,"edition":"2024","size":["Small"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{},"feats":[],"traits":[{"name":"Brave","text":"You have Advantage on saving throws you make to avoid or end the Frightened condition."},{"name":"Halfling Nimbleness","text":"You can move through the space of any creature that is a size larger than you, but you can't stop in the same space."},{"name":"Luck","text":"When you roll a 1 on the d20 of a D20 Test, you can reroll the die, and you must use the new roll."},{"name":"Naturally Stealthy","text":"You can take the Hide action even when you are obscured only by a creature that is at least one size larger than you."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Halfling.webp"],"srd":true},{"id":"harengon-mpmm","name":"Harengon","source":"MPMM","page":22,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Hare-Trigger","text":"You can add your proficiency bonus to your initiative rolls."},{"name":"Leporine Senses","text":"You have proficiency in the Perception skill."},{"name":"Lucky Footwork","text":"When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're prone or your speed is 0."},{"name":"Rabbit Hop","text":"As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Harengon.webp"]},{"id":"harengon-wbtw","name":"Harengon","source":"WBtW","page":13,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Hare-Trigger","text":"You can add your proficiency bonus to your initiative rolls."},{"name":"Leporine Senses","text":"You have proficiency in the Perception skill."},{"name":"Lucky Footwork","text":"When you fail a Dexterity saving throw, you can use your reaction to roll a d4 and add it to the save, potentially turning the failure into a success. You can't use this reaction if you're prone or your speed is 0."},{"name":"Rabbit Hop","text":"As a bonus action, you can jump a number of feet equal to five times your proficiency bonus, without provoking opportunity attacks. You can use this trait only if your speed is greater than 0. You can use it a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/WBtW/Harengon.webp"]},{"id":"hexblood-rhw","name":"Hexblood","source":"RHW","page":29,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["fey"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"disguise-self-xphb","name":"Disguise Self","how":"prepared","uses":"1/day each","at":null},{"spell":"hex-xphb","name":"Hex","how":"prepared","uses":"1/day each","at":null}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Eerie Token","text":"As a Bonus Action, you can create a magical token by harmlessly removing a lock of hair, detaching a nail, or using some other method. While the token exists, you gain the following benefits:\n\n• Distant Message As a Magic action, you can send a telepathic message of 25 words or fewer to a creature holding or carrying the token, as long as you are within 10 miles of it.\n• Remote Viewing If you are within 10 miles of the token, you can take a Magic action to extend your senses through the token for 1 minute, until you have the Incapacitated condition, or until you end this state (no action required). During this state, you can see and hear from the token as if you were located where it is. When this state ends, the token is harmlessly destroyed. Unless the token is destroyed early, it lasts until you finish a Long Rest. Once you create a token using this feature, you can't do so again until you finish a Long Rest.\n• Hex Magic You always have the Disguise Self and Hex spells prepared. You can cast each spell once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select this species)."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/RHW/Hexblood.webp"]},{"id":"hexblood-vrgr","name":"Hexblood","source":"VRGR","page":18,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["fey"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","any":{"any":2}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"disguise-self-phb","name":"Disguise Self","how":"known","uses":"","at":"1"},{"spell":"hex-phb","name":"Hex","how":"known","uses":"","at":"1"}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Ancestral Legacy","text":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it.\n\nIf you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness as shades of gray."},{"name":"Eerie Token","text":"As a bonus action, you can harmlessly remove a lock of your hair, one of your nails, or one of your teeth. This token is imbued with magic until you finish a long rest. While the token is imbued in this way, you can take these actions:\n\n• Telepathic Message As an action, you can send a telepathic message to the creature holding or carrying the token, as long as you are within 10 miles of it. The message can contain up to twenty-five words.\n• Remote Viewing If you are within 10 miles of the token, you can enter a trance as an action. The trance lasts for 1 minute, but it ends early if you dismiss it (no action required) or are incapacitated. During this trance, you can see and hear from the token as if you were located where it is. While you are using your senses at the token's location, you are blinded and deafened in regard to your own surroundings. When the trance ends, the token is harmlessly destroyed.\n\nOnce you create a token using this feature, you can't do so again until you finish a long rest, at which point your missing part regrows."},{"name":"Hex Magic","text":"You can cast the disguise self and hex spells with this trait. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose the ability when you gain this lineage).\n\nBecoming a Hag. Hags can undertake a ritual to irreversibly transform a hexblood they created into a new hag, either one of their own kind or that embodies the hexblood's nature. This requires that both the hag and hexblood be in the same place and consent to the lengthy ritual—circumstances most hexbloods shun but might come to accept over the course of centuries. Once a hexblood undergoes this irreversible ritual, they emerge as a hag NPC no longer under the control of the hexblood's player, unless the DM rules otherwise."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VRGR/Hexblood.webp"]},{"id":"hobgoblin-dmg","name":"Hobgoblin","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["common","goblin"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Martial Advantage","text":"Once per turn, you can deal an extra 2d6 damage to a creature you hit with a weapon attack if that creature is within 5 ft. of an ally of yours that isn't incapacitated."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"hobgoblin-erlw","name":"Hobgoblin","source":"ERLW","page":26,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2,"int":1}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]},{"kind":"weapon","choose":{"from":[],"count":2,"filter":"type=martial weapon|miscellaneous=mundane"}},{"kind":"armor","fixed":["light"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Martial Training","text":"You are proficient with two martial weapons of your choice and with light armor."},{"name":"Saving Face","text":"Hobgoblins are careful not to show weakness in front of their allies, for fear of losing status. If you miss with an attack roll or fail an ability check or a saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +5). Once you use this trait, you can't use it again until you finish a short or long rest."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Goblinoids.webp"]},{"id":"hobgoblin-mpmm","name":"Hobgoblin","source":"MPMM","page":23,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Fey Gift","text":"You can use this trait to take the Help action as a bonus action, and you can do so a number of times equal to your proficiency bonus. You regain all expended uses when you finish a long rest.\n\nStarting at 3rd level, choose one of the options below each time you take the Help action with this trait:\n\n• Hospitality You and the creature you help each gain a number of temporary hit points equal to 1d6 plus your proficiency bonus.\n• Passage You and the creature you help each increase your walking speeds by 10 feet until the start of your next turn.\n• Spite Until the start of your next turn, the first time the creature you help hits a target with an attack roll, that target has disadvantage on the next attack roll it makes within the next minute."},{"name":"Fortune from the Many","text":"If you miss with an attack roll or fail an ability check or a saving throw, you can draw on your bonds of reciprocity to gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +3). You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Hobgoblin.webp"]},{"id":"hobgoblin-vgm","name":"Hobgoblin","source":"VGM","page":119,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2,"int":1}}],"proficiencies":[{"kind":"language","fixed":["common","goblin"]},{"kind":"weapon","choose":{"from":[],"count":2,"filter":"type=martial weapon|miscellaneous=mundane"}},{"kind":"armor","fixed":["light"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Martial Training","text":"You are proficient with two martial weapons of your choice and with light armor."},{"name":"Saving Face","text":"Hobgoblins are careful not to show weakness in front of their allies, for fear of losing status. If you miss with an attack roll or fail an ability check or a saving throw, you can gain a bonus to the roll equal to the number of allies you can see within 30 feet of you (maximum bonus of +5). Once you use this trait, you can't use it again until you finish a short or long rest."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Hobgoblin.webp"]},{"id":"human-base-phb","name":"Human (Base)","source":"PHB","page":29,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Human.webp"],"srd":true},{"id":"human-xphb","name":"Human","source":"XPHB","page":194,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"proficiencies":[{"kind":"skill","any":{"any":1}}]},"feats":[{"any":true,"count":1,"category":"Origin"}],"traits":[{"name":"Resourceful","text":"You gain Heroic Inspiration whenever you finish a Long Rest."},{"name":"Skillful","text":"You gain proficiency in one skill of your choice."},{"name":"Versatile","text":"You gain an Origin feat of your choice (see 5). Skilled is recommended."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Human.webp"],"srd":true},{"id":"human-innistrad-psi","name":"Human (Innistrad)","source":"PSI","page":8,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[{"id":"human-innistrad-psi--gavony","name":"Gavony","kind":"subrace","source":"PSI","page":8,"traits":[],"removes":[],"benefits":{"ability":[{"fixed":{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad3.webp"]},{"id":"human-innistrad-psi--kessig","name":"Kessig","kind":"subrace","source":"PSI","page":8,"traits":[{"name":"Forest Folk","text":"You have proficiency in the Survival skill."},{"name":"Fleet of Foot","text":"Your base walking speed is 40 feet."},{"name":"Sure-footed","text":"When you use the Dash action, 3 doesn't cost you extra movement on that turn."},{"name":"Spring Attack","text":"When you make a melee attack against a creature, you don't provoke opportunity attacks from that creature for the rest of your turn, whether you hit or not."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":1,"wis":1}}],"proficiencies":[{"kind":"skill","fixed":["survival"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"speed":{"walk":12},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad3.webp"]},{"id":"human-innistrad-psi--nephalia","name":"Nephalia","kind":"subrace","source":"PSI","page":8,"traits":[{"name":"Breadth of Knowledge","text":"You gain proficiency in any combination of four skills or with four 5 of your choice."}],"removes":[],"benefits":{"ability":[{"fixed":{"int":1,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}},{"kind":"skillToolLanguage","choose":{"from":["anySkill","anyTool"],"count":4}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad3.webp"]},{"id":"human-innistrad-psi--stensia","name":"Stensia","kind":"subrace","source":"PSI","page":8,"traits":[{"name":"Daunting","text":"You have proficiency in the Intimidation skill."},{"name":"Tough","text":"Your hit point maximum increases by 2, and it increases by 2 every time you gain a level."}],"removes":[],"benefits":{"ability":[{"fixed":{"str":1,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["intimidation"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad3.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSI/Innistrad3.webp"]},{"id":"human-ixalan-psx","name":"Human (Ixalan)","source":"PSX","page":11,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Human.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Human2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Human3.webp"]},{"id":"human-kaladesh-psk","name":"Human (Kaladesh)","source":"PSK","page":22,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Human.webp"]},{"id":"human-zendikar-psz","name":"Human (Zendikar)","source":"PSZ","page":9,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"dex":1,"con":1,"int":1,"wis":1,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Human.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Human2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Human3.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Human4.webp"]},{"id":"kalashtar-efa","name":"Kalashtar","source":"EFA","page":35,"edition":"2024","size":["Medium"],"speed":{"walk":9},"creatureTypes":["aberration"],"benefits":{"resist":{"fixed":["psychic"]}},"feats":[],"traits":[{"name":"Dual Mind","text":"You have Advantage on Wisdom and Charisma saving throws."},{"name":"Mental Discipline","text":"You have Resistance to Psychic damage."},{"name":"Mind Link","text":"You have telepathy with a range in feet equal to 10 times your level. When you're using this trait to speak telepathically to a creature, you can take a Magic action to give that creature the ability to speak telepathically with you for 1 hour or until you take another Magic action to end this effect."},{"name":"Severed from Dreams","text":"You can't be the target of the Dream spell. In addition, when you finish a Long Rest, you gain proficiency in one skill of your choice. This proficiency lasts until you finish another Long Rest."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EFA/Kalashtar.webp"]},{"id":"kalashtar-erlw","name":"Kalashtar","source":"ERLW","page":29,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"wis":2,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}],"resist":{"fixed":["psychic"]}},"feats":[],"traits":[{"name":"Dual Mind","text":"You have advantage on all Wisdom saving throws."},{"name":"Mental Discipline","text":"You have resistance to psychic damage."},{"name":"Mind Link","text":"You can speak telepathically to any creature you can see, provided the creature is within a number of feet of you equal to 10 times your level. You don't need to share a language with the creature for it to understand your telepathic utterances, but the creature must be able to understand at least one language.\n\nWhen you're using this trait to speak telepathically to a creature, you can use your action to give that creature the ability to speak telepathically with you for 1 hour or until you end this effect as an action. To use this ability, the creature must be able to see you and must be within this trait's range. You can give this ability to only one creature at a time; giving it to a creature takes it away from another creature who has it."},{"name":"Severed from Dreams","text":"Kalashtar sleep, but they don't connect to the plane of dreams as other creatures do. Instead, their minds draw from the memories of their otherworldly spirit while they sleep. As such, you are immune to spells and other magical effects that require you to dream, like dream, but not to spells and other magical effects that put you to sleep, like sleep."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":64,"heightMod":"2d6","baseWeight":110,"weightMod":"1d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Kalashtar.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Kalashtar%20001.webp"]},{"id":"kender-dsotdq","name":"Kender","source":"DSotDQ","page":27,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["insight","investigation","sleight of hand","stealth","survival"],"count":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Fearless","text":"You have advantage on saving throws you make to avoid or end the frightened condition on yourself. When you fail a saving throw to avoid or end the frightened condition on yourself, you can choose to succeed instead. Once you succeed on a saving throw in this way, you can't do so again until you finish a long rest."},{"name":"Kender Curiosity","text":"Thanks to the mystical origin of your people, you gain proficiency with one of the following skills of your choice: Insight, Investigation, Sleight of Hand, Stealth, or Survival."},{"name":"Taunt","text":"You have an extraordinary ability to fluster creatures. As a bonus action, you can unleash a string of provoking words at a creature within 60 feet of yourself that can hear and understand you. The target must succeed on a Wisdom saving throw, or it has disadvantage on attack rolls against targets other than you until the start of your next turn. The DC equals 8 + your proficiency bonus + your Intelligence, Wisdom, or Charisma modifier (choose when you select this race).\n\nYou can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/DSotDQ/Kender.webp"]},{"id":"kenku-dmg","name":"Kenku","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","auran"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Ambusher","text":"In the first round of a combat, you have advantage on attack rolls against any creature who is surprised."},{"name":"Mimicry","text":"You can mimic any sounds you have heard, including voices. A creature that hears the sounds can tell they are imitations with a successful DC 14 Wisdom (Insight) check."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"kenku-mpmm","name":"Kenku","source":"MPMM","page":24,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","any":{"any":2}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Expert Duplication","text":"When you copy writing or craftwork produced by yourself or someone else, you have advantage on any ability checks you make to produce an exact duplicate."},{"name":"Kenku Recall","text":"Thanks to your supernaturally good memory, you have proficiency in two skills of your choice.\n\nMoreover, when you make an ability check using any skill in which you have proficiency, you can give yourself advantage on the check before rolling the d20. You can give yourself advantage in this way a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Mimicry","text":"You can accurately mimic sounds you have heard, including voices. A creature that hears the sounds you make can tell they are imitations only with a successful Wisdom (Insight) check against a DC of 8 + your proficiency bonus + your Charisma modifier."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Kenku.webp"]},{"id":"kenku-vgm","name":"Kenku","source":"VGM","page":109,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["acrobatics","deception","sleight of hand","stealth"],"count":2}},{"kind":"language","fixed":["common","auran"]}]},"feats":[],"traits":[{"name":"Expert Forgery","text":"You can duplicate other creatures' handwriting and craftwork. You have advantage on all checks made to produce forgeries or duplicates of existing objects."},{"name":"Kenku Training","text":"You are proficient in your choice of two of the following skills: Acrobatics, Deception, Stealth, and Sleight of Hand."},{"name":"Mimicry","text":"You can mimic sounds you have heard, including voices. A creature that hears the sounds can tell they are imitations with a successful Wisdom (Insight) check opposed by your Charisma (Deception) check."}],"lineage":"","age":{"mature":12,"max":60},"heightWeight":{"baseHeight":52,"heightMod":"2d8","baseWeight":50,"weightMod":"1d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Kenku.webp"]},{"id":"khenra-psa","name":"Khenra","source":"PSA","page":17,"edition":"","size":["Medium"],"speed":{"walk":10.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","other"]},{"kind":"weapon","fixed":["longsword","spear","javelin"]}]},"feats":[],"traits":[{"name":"Khenra Weapon Training","text":"You have proficiency with the khopesh (longsword), spear, and javelin."},{"name":"Khenra Twins","text":"If your twin is alive and you can see your twin, whenever you roll a 1 on an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll. If your twin is dead (or if you were born without a twin), you can't be frightened."}],"lineage":"","age":{"mature":13,"max":60},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Khenra.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Khenra2.webp"]},{"id":"khoravar-efa","name":"Khoravar","source":"EFA","page":36,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"choose":"level=0|class=Cleric;Druid;Wizard","label":"Cantrip Cleric/Druid/Wizard","count":1,"how":"known","uses":"_","at":"1"}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Fey Ancestry","text":"You have Advantage on saving throws you make to avoid or end the Charmed condition."},{"name":"Fey Gift","text":"You know the Friends cantrip. Whenever you finish a Long Rest, you can replace that cantrip with a different cantrip from the Cleric, Druid, or Wizard spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for it (choose the ability when you select this species)."},{"name":"Lethargy Resilience","text":"When you fail a saving throw to avoid or end the Unconscious condition, you can succeed instead. Once you use this trait, you can't do so again until you finish 1d4 Long Rests."},{"name":"Skill Versatility","text":"You gain proficiency in one skill or with one tool of your choice. Whenever you finish a Long Rest, you can replace it with another skill or tool proficiency."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EFA/Khoravar.webp"]},{"id":"kithkin-lfl","name":"Kithkin","source":"LFL","page":null,"edition":"2024","size":["Small"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Brave","text":"You have Advantage on saving throws you make to avoid or end the Frightened condition."},{"name":"Halfling Nimbleness","text":"You can move through the space of any creature that is a size larger than you, but you can't stop in the same space."},{"name":"Luck","text":"When you roll a 1 on the d20 of a D20 Test, you can reroll the die, and you must use the new roll."},{"name":"Naturally Stealthy","text":"You can take the Hide action even when you are obscured only by a creature that is at least one size larger than you."},{"name":"Kithkin Lineage","text":"As a native of either Lorwyn and Shadowmoor, you may gain additional traits.\n\n• Lorwyn You do not gain any additional traits.\n• Shadowmoor You have Darkvision with a range of 120 feet."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"kithkin-lfl--lorwyn","name":"Lorwyn","kind":"lineage","source":"LFL","page":null,"traits":[],"removes":["Kithkin Lineage"]},{"id":"kithkin-lfl--shadowmoor","name":"Shadowmoor","kind":"lineage","source":"LFL","page":null,"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 120 feet."}],"removes":["Kithkin Lineage"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Kithkin%20(Shadowmoor).webp"]},{"id":"kobold-dmg","name":"Kobold","source":"DMG","page":282,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":-4,"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","draconic"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Pack Tactics","text":"You have advantage on an attack roll against a creature if at least one of your allies is within 5 feet of the creature and the ally isn't incapacitated."},{"name":"Sunlight Sensitivity","text":"You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."},{"name":"Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"kobold-mpmm","name":"Kobold","source":"MPMM","page":25,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["arcana","investigation","medicine","sleight of hand","survival"],"count":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"choose":"level=0|class=Sorcerer","label":"Cantrip Sorcerer","count":1,"how":"known","uses":"","at":null}]}]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."},{"name":"Draconic Cry","text":"As a bonus action, you let out a cry at your enemies within 10 feet of you. Until the start of your next turn, you and your allies have advantage on attack rolls against any of those enemies who could hear you. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Kobold Legacy","text":"Kobold's connections to dragons can manifest in unpredictable ways in an individual kobold. Choose one of the following legacy options for your kobold.\n\n• Craftiness You have proficiency in one of the following skills of your choice: Arcana, Investigation, Medicine, Sleight of Hand, or Survival.\n• Defiance You have advantage on saving throws to avoid or end the frightened condition on yourself.\n• Draconic Sorcery You know one cantrip of your choice from the sorcerer spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for that cantrip (choose when you select this race)."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[{"id":"kobold-mpmm--craftiness","name":"Craftiness","kind":"lineage","source":"MPMM","page":25,"traits":[{"name":"Kobold Legacy (Craftiness)","text":"You have proficiency in one of the following skills of your choice: Arcana, Investigation, Medicine, Sleight of Hand, or Survival."}],"removes":["Kobold Legacy"]},{"id":"kobold-mpmm--defiance","name":"Defiance","kind":"lineage","source":"MPMM","page":25,"traits":[{"name":"Kobold Legacy (Defiance)","text":"You have advantage on saving throws to avoid or end the frightened condition on yourself."}],"removes":["Kobold Legacy"],"benefits":{"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]}},{"id":"kobold-mpmm--draconic-sorcery","name":"Draconic Sorcery","kind":"lineage","source":"MPMM","page":25,"traits":[{"name":"Kobold Legacy (Draconic Sorcery)","text":"You know one cantrip of your choice from the sorcerer spell list. Intelligence, Wisdom, or Charisma is your spellcasting ability for that cantrip (choose when you select this race)."}],"removes":["Kobold Legacy"],"benefits":{"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Kobold.webp"]},{"id":"kobold-vgm","name":"Kobold","source":"VGM","page":119,"edition":"2014","size":["Small"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2}}],"proficiencies":[{"kind":"language","fixed":["common","draconic"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Grovel, Cower, and Beg","text":"As an action on your turn, you can cower pathetically to distract nearby foes. Until the end of your next turn, your allies gain advantage on attack rolls against enemies within 10 feet of you that you can see. Once you use this trait, you can't use it again until you finish a short or long rest."},{"name":"Pack Tactics","text":"You have advantage on an attack roll against a creature if at least one of your allies is within 5 feet of the creature and the ally isn't incapacitated."},{"name":"Sunlight Sensitivity","text":"You have disadvantage on attack rolls and on Wisdom (Perception) checks that rely on sight when you, the target of your attack, or whatever you are trying to perceive is in direct sunlight."}],"lineage":"","age":{"mature":6,"max":120},"heightWeight":{"baseHeight":25,"heightMod":"2d4","baseWeight":25,"weightMod":""},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Kobold.webp"]},{"id":"kor-psz","name":"Kor","source":"PSZ","page":10,"edition":"","size":["Medium"],"speed":{"walk":9,"climb":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"wis":1}}],"proficiencies":[{"kind":"skill","fixed":["athletics","acrobatics"]},{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Brave","text":"You have advantage on saving throws against being frightened."},{"name":"Climbing","text":"You also have a climbing speed of 30 feet as long as you are not encumbered or wearing heavy armor."},{"name":"Kor Climbing","text":"You have proficiency in the Athletics and Acrobatics skills."},{"name":"Lucky","text":"When you roll a 1 on the d20 for an attack roll, ability check, or saving throw, you can reroll the die and must use the new roll."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Kor.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Kor2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Kor3.webp"]},{"id":"kuo-toa-dmg","name":"Kuo-Toa","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["undercommon"]}],"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Otherworldly Perception","text":"You can sense the presence of any creature within 30 feet of you that is invisible or on the Ethereal Plane. You can pinpoint such a creature that is moving."},{"name":"Slippery","text":"You have advantage on ability checks and saving throws made to escape a grapple."},{"name":"Sunlight Sensitivity","text":"While in sunlight, you have disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."},{"name":"Superior Darkvision","text":"You have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"leonin-mot","name":"Leonin","source":"MOT","page":20,"edition":"2014","size":["Medium"],"speed":{"walk":10.5},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"con":2}}],"proficiencies":[{"kind":"skill","choose":{"from":["athletics","intimidation","perception","survival"],"count":1}},{"kind":"language","fixed":["common","other"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Claws","text":"Your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you can deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Hunter's Instincts","text":"You have proficiency in one of the following skills of your choice: Athletics, Intimidation, Perception, or Survival."},{"name":"Daunting Roar","text":"As a bonus action, you can let out an especially menacing roar. Creatures of your choice within 10 feet of you that can hear you must succeed on a Wisdom saving throw or become frightened of you until the end of your next turn. The DC of the save equals 8 + your proficiency bonus + your Constitution modifier. Once you use this trait, you can't use it again until you finish a short or long rest."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":66,"heightMod":"2d10","baseWeight":180,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Leonin.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Leonin%20Matron.webp"]},{"id":"lizardfolk-dmg","name":"Lizardfolk","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"int":-2}}],"proficiencies":[{"kind":"language","fixed":["draconic"]}]},"feats":[],"traits":[{"name":"Hold Breath","text":"You can hold your breath for up to 15 minutes at a time."},{"name":"Natural Armor","text":"Your scales function as natural armor, granting you a +3 bonus to Armor Class."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"lizardfolk-mpmm","name":"Lizardfolk","source":"MPMM","page":26,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","medicine","nature","perception","stealth","survival"],"count":2}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Bite","text":"You have a fanged maw that you can use to make unarmed strikes. When you hit with it, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Hold Breath","text":"You can hold your breath for up to 15 minutes at a time."},{"name":"Hungry Jaws","text":"You can throw yourself into a feeding frenzy. As a bonus action, you can make a special attack with your Bite. If the attack hits, it deals its normal damage, and you gain temporary hit points equal to your proficiency bonus. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."},{"name":"Natural Armor","text":"You have tough, scaly skin. When you aren't wearing armor, your base AC is 13 + Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."},{"name":"Nature's Intuition","text":"Thanks to your mystical connection to nature, you gain proficiency with two of the following skills of your choice: Animal Handling, Medicine, Nature, Perception, Stealth, or Survival."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Lizardfolk.webp"]},{"id":"lizardfolk-vgm","name":"Lizardfolk","source":"VGM","page":111,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2,"wis":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","nature","perception","stealth","survival"],"count":2}},{"kind":"language","fixed":["common","draconic"]}]},"feats":[],"traits":[{"name":"Swim Speed","text":"You have a swimming speed of 30 feet."},{"name":"Bite","text":"Your fanged maw is a natural weapon, which you can use to make unarmed strikes. If you hit with it, you deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Cunning Artisan","text":"As part of a short rest, you can harvest bone and hide from a slain beast, construct, dragon, monstrosity, or plant creature of size small or larger to create one of the following items: a shield, a club, a javelin, or 1d4 darts or blowgun needles. To use this trait, you need a blade, such as a dagger, or appropriate artisan's tools, such as leatherworker's tools."},{"name":"Hold Breath","text":"You can hold your breath for up to 15 minutes at a time."},{"name":"Hunter's Lore","text":"You gain proficiency with two of the following skills of your choice: Animal Handling, Nature, Perception, Stealth, and Survival."},{"name":"Natural Armor","text":"You have tough, scaly skin. When you aren't wearing armor, your AC is 13 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."},{"name":"Hungry Jaws","text":"In battle, you can throw yourself into a vicious feeding frenzy. As a bonus action, you can make a special attack with your bite. If the attack hits, it deals its normal damage, and you gain temporary hit points equal to your Constitution modifier (minimum of 1), and you can't use this trait again until you finish a short or long rest."}],"lineage":"","age":{"mature":14,"max":60},"heightWeight":{"baseHeight":57,"heightMod":"2d10","baseWeight":120,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Lizardfolk.webp"]},{"id":"locathah-lr","name":"Locathah","source":"LR","page":24,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"dex":1}}],"proficiencies":[{"kind":"skill","fixed":["athletics","perception"]},{"kind":"language","fixed":["aquan","common"]}]},"feats":[],"traits":[{"name":"Natural Armor","text":"You have tough, scaly skin. When you aren't wearing armor, your AC is 12 + your Dexterity modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor."},{"name":"Observant & Athletic","text":"You have proficiency in the Athletics and Perception skills."},{"name":"Leviathan Will","text":"You have advantage on saving throws against being charmed, frightened, paralyzed, poisoned, stunned, or put to sleep."},{"name":"Limited Amphibiousness","text":"You can breathe air and water, but you need to be submerged at least once every 4 hours to avoid suffocating."}],"lineage":"","age":{"mature":10,"max":80},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LR/Locathah.webp"]},{"id":"lorwyn-changeling-lfl","name":"Lorwyn Changeling","source":"LFL","page":null,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["fey"],"benefits":{"proficiencies":[{"kind":"skill","choose":{"from":["deception","performance"],"count":1}}],"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Shape Self","text":"As an action, you can reshape your body to a two-legged Humanoid shape or to a four-legged Beast shape. While you have a Humanoid shape, you can wear clothing and armor made for a Humanoid of your size."},{"name":"Darkvision","text":"You have Darkvision with a range of 120 feet."},{"name":"Delightful Imitator","text":"You have proficiency in the Deception or Performance skill."},{"name":"Unpredictable Movement","text":"When you roll Initiative, you can immediately move up to half your Speed, provided you don't have Disadvantage on the Initiative roll."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Changeling.webp"]},{"id":"loxodon-ggr","name":"Loxodon","source":"GGR","page":17,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2,"wis":1}}],"proficiencies":[{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Loxodon Serenity","text":"You have advantage on saving throws against being charmed or frightened."},{"name":"Natural Armor","text":"You have thick, leathery skin. When you aren't wearing armor, your AC is 12 + your Constitution modifier. You can use your natural armor to determine your AC if the armor you wear would leave you with a lower AC. A shield's benefits apply as normal while you use your natural armor.\n\nTip: AC Calculations Don't Stack. When the game gives you more than one way to calculate your Armor Class, you can use only one of them. You choose the one to use. For example, if you have the loxodon's Natural Armor trait and the monk's Unarmored Defense feature, you don't mix them together. Instead, you choose which one determines your AC."},{"name":"Trunk","text":"You can grasp things with your trunk, and you can use it as a snorkel. It has a reach of 5 feet, and it can lift a number of pounds equal to five times your Strength score. You can use it to do the following simple tasks: lift, drop, hold, push, or pull an object or a creature; open or close a door or a container; grapple someone; or make an unarmed strike. Your DM might allow other simple tasks to be added to that list of options.\n\nYour trunk can't wield weapons or shields or do anything that requires manual precision, such as using tools or magic items or performing the somatic components of a spell."},{"name":"Keen Smell","text":"Thanks to your sensitive trunk, you have advantage on Wisdom (Perception), Wisdom (Survival), and Intelligence (Investigation) checks that involve smell."}],"lineage":"","age":{"mature":20,"max":450},"heightWeight":{"baseHeight":79,"heightMod":"2d10","baseWeight":295,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/GGR/Loxodon.webp"]},{"id":"lupin-rhw","name":"Lupin","source":"RHW","page":30,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"proficiencies":[{"kind":"skill","choose":{"from":["perception","stealth","survival"],"count":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Feral Pounce","text":"Your Unarmed Strikes deal Slashing damage instead of Bludgeoning damage. In addition, when you hit a creature with an Unarmed Strike as part of the Attack action on your turn, you can use both the Damage and the Shove options. You can use this benefit only once per turn."},{"name":"Howl","text":"As a Bonus Action, you let out an unearthly howl. Each creature of your choice within 15 feet of you must succeed on a Wisdom saving throw (DC 8 plus your Constitution modifier and Proficiency Bonus) or have Disadvantage on attack rolls and saving throws until the start of your next turn.\n\nYou can use this trait a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Werewolf Instincts","text":"You have proficiency in the Perception, Stealth, or Survival skill."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/RHW/Lupin.webp"]},{"id":"merfolk-dmg","name":"Merfolk","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":3,"swim":12},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["common","aquan"]}]},"feats":[],"traits":[{"name":"Amphibious","text":"You can breathe air and water."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"merfolk-psz","name":"Merfolk","source":"PSZ","page":13,"edition":"","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Swimming","text":"You have a swimming speed of 30 feet."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[{"id":"merfolk-psz--ixalan-blue-psx","name":"Ixalan; Blue","kind":"subrace","source":"PSX","page":12,"traits":[{"name":"Cantrip","text":"You know one cantrip of your choice from the wizard spell list. Intelligence is your spellcasting ability for it."},{"name":"Lore of the Waters","text":"You gain proficiency in the History and Nature skills."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":1,"int":2}}],"proficiencies":[{"kind":"skill","fixed":["history","nature"]},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"choose":"level=0|class=Wizard","label":"Cantrip Wizard","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Merfolk.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Merfolk2.webp"]},{"id":"merfolk-psz--ixalan-green-psx","name":"Ixalan; Green","kind":"subrace","source":"PSX","page":12,"traits":[{"name":"Cantrip","text":"You know one cantrip of your choice from the druid spell list. Wisdom is your spellcasting ability for it."},{"name":"Mask of the Wild","text":"You can attempt to hide even when you are only lightly obscured by foliage, heavy rain, falling snow, mist, and other natural phenomena."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":1,"wis":2}}],"proficiencies":[{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"choose":"level=0|class=Druid","label":"Cantrip Druid","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Merfolk.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Merfolk2.webp"]},{"id":"merfolk-psz--zendikar-cosi-creed","name":"Zendikar; Cosi Creed","kind":"subrace","source":"PSZ","page":13,"traits":[{"name":"Cantrip","text":"You know one cantrip of your choice from the bard spell list. Charisma is your spellcasting ability for it."},{"name":"Creed of the Trickster","text":"You have proficiency in the Sleight of Hand and Stealth skills."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":2,"int":1}}],"proficiencies":[{"kind":"skill","fixed":["sleight of hand","stealth"]},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"choose":"level=0|class=Bard","label":"Cantrip Bard","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk2.webp"]},{"id":"merfolk-psz--zendikar-emeria-creed","name":"Zendikar; Emeria Creed","kind":"subrace","source":"PSZ","page":13,"traits":[{"name":"Cantrip","text":"You know one cantrip of your choice from the druid spell list. Wisdom is your spellcasting ability for it."},{"name":"Wind Creed Manipulation","text":"You have proficiency in the Deception and Persuasion skills."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":1,"wis":2}}],"proficiencies":[{"kind":"skill","fixed":["deception","persuasion"]},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}],"spells":{"ability":{"fixed":"wis"},"groups":[{"name":"","items":[{"choose":"level=0|class=Druid","label":"Cantrip Druid","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk2.webp"]},{"id":"merfolk-psz--zendikar-ula-creed","name":"Zendikar; Ula Creed","kind":"subrace","source":"PSZ","page":13,"traits":[{"name":"Cantrip","text":"You know one cantrip of your choice from the wizard spell list. Intelligence is your spellcasting ability for it."},{"name":"Water Creed Navigation","text":"You have proficiency with navigator's tools and in the Survival skill."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":1,"int":2}}],"proficiencies":[{"kind":"skill","fixed":["survival"]},{"kind":"tool","fixed":["navigator's tools"]},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}],"spells":{"ability":{"fixed":"int"},"groups":[{"name":"","items":[{"choose":"level=0|class=Wizard","label":"Cantrip Wizard","count":1,"how":"known","uses":"_","at":"1"}]}]}},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk2.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Merfolk2.webp"]},{"id":"minotaur-ggr","name":"Minotaur","source":"GGR","page":18,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["intimidation","persuasion"],"count":1}},{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Horns","text":"Your horns are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Goring Rush","text":"Immediately after you use the Dash action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action."},{"name":"Hammering Horns","text":"Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be no more than one size larger than you and within 5 feet of you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."},{"name":"Imposing Presence","text":"You have proficiency in one of the following skills of your choice: Intimidation or Persuasion."}],"lineage":"","age":{"mature":17,"max":150},"heightWeight":{"baseHeight":64,"heightMod":"2d8","baseWeight":175,"weightMod":"2d6"},"options":[],"description":"These traits are also suitable for minotaurs in other D&D worlds where these people have avoided the demonic influence of Baphomet.","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/GGR/Minotaur.webp"]},{"id":"minotaur-mot","name":"Minotaur","source":"MOT","page":22,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["intimidation","persuasion"],"count":1}},{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Horns","text":"Your horns are natural melee weapons, which you can use to make unarmed strikes. If you hit with them, you deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Goring Rush","text":"Immediately after you use the Dash action on your turn and move at least 20 feet, you can make one melee attack with your horns as a bonus action."},{"name":"Hammering Horns","text":"Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to shove that target with your horns. The target must be no more than one size larger than you and within 5 feet of you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you push it up to 10 feet away from you."},{"name":"Imposing Presence","text":"You have proficiency in one of the following skills of your choice: Intimidation or Persuasion."}],"lineage":"","age":{"mature":17,"max":150},"heightWeight":{"baseHeight":64,"heightMod":"2d8","baseWeight":175,"weightMod":"2d6"},"options":[],"description":"These traits are also suitable for minotaurs in other D&D worlds where these people have avoided the demonic influence of Baphomet.","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Minotaur.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Minotaur%202.webp"]},{"id":"minotaur-mpmm","name":"Minotaur","source":"MPMM","page":27,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Horns","text":"You have horns that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier piercing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Goring Rush","text":"Immediately after you take the Dash action on your turn and move at least 20 feet, you can make one melee attack with your Horns as a bonus action."},{"name":"Hammering Horns","text":"Immediately after you hit a creature with a melee attack as part of the Attack action on your turn, you can use a bonus action to attempt to push that target with your horns. The target must be within 5 feet of you and no more than one size larger than you. Unless it succeeds on a Strength saving throw against a DC equal to 8 + your proficiency bonus + your Strength modifier, you can push it up to 10 feet away from you."},{"name":"Labyrinthine Recall","text":"You always know which direction is north, and you have advantage on any Wisdom (Survival) check you make to navigate or track."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Minotaur.webp"]},{"id":"minotaur-amonkhet-psa","name":"Minotaur (Amonkhet)","source":"PSA","page":19,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["intimidation"]},{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Natural Weapon","text":"You can use your horns as a natural weapon to make unarmed strikes. If you hit with your horns, you deal bludgeoning damage equal to 1d6 + your Strength modifier."},{"name":"Menacing","text":"You gain proficiency in the Intimidation skill."},{"name":"Relentless Endurance","text":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."},{"name":"Savage Attacks","text":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."}],"lineage":"","age":{"mature":20,"max":40},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Minotaur%20(Amonkhet).webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Minotaur%20(Amonkhet)2.webp"]},{"id":"naga-psa","name":"Naga","source":"PSA","page":21,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2,"int":1}}],"proficiencies":[{"kind":"tool","fixed":["poisoner's kit"]},{"kind":"language","fixed":["common","other"]}],"immune":{"fixed":["poison"]},"conditionImmune":{"fixed":["poisoned"]}},"feats":[],"traits":[{"name":"Speed Burst","text":"By lowering your body to the ground and propelling yourself with your arms, you can move more quickly for a time. As a bonus action on your turn, if you have both hands free, you can increase your walking speed by 5 feet until the end of your turn."},{"name":"Natural Weapons","text":"Your fanged maw and constricting serpentine body are natural weapons, which you can use to make unarmed strikes.\n\nIf you hit with your bite, you deal piercing damage equal to 1d4 + your Strength modifier, and your target must make a Constitution saving throw (DC 8 + your proficiency bonus + your Constitution modifier). On a failed save, the target takes 1d4 poison damage.\n\nIf you hit with your constrict attack, you deal bludgeoning damage equal to 1d6 + your Strength modifier, and the target is grappled (escape DC 8 + your proficiency bonus + your Strength modifier). Until this grapple ends, the target is restrained, and you can't constrict another target."},{"name":"Poison Immunity","text":"You are immune to poison damage and can't be poisoned."},{"name":"Poison Affinity","text":"You gain proficiency with the poisoner's kit."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Naga.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSA/Naga2.webp"]},{"id":"orc-dmg","name":"Orc","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"int":-2}}],"proficiencies":[{"kind":"language","fixed":["common","orc"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Aggressive","text":"As a bonus action, you can move up to your speed toward a hostile creature that you can see."},{"name":"Darkvision","text":"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"orc-egw","name":"Orc","source":"EGW","page":178,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","insight","intimidation","medicine","perception","survival"],"count":2}},{"kind":"language","fixed":["common","orc"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Aggressive","text":"As a bonus action, you can move up to your movement speed toward a hostile creature you can see or hear. You must end this move closer to the enemy than you started."},{"name":"Primal Intuition","text":"You have proficiency in two of the following skills of your choice: Animal Handling, Insight, Intimidation, Medicine, Perception, and Survival."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}],"lineage":"","age":{"mature":12,"max":50},"heightWeight":null,"options":[],"description":""},{"id":"orc-erlw","name":"Orc","source":"ERLW","page":31,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","insight","intimidation","medicine","nature","perception","survival"],"count":2}},{"kind":"language","fixed":["common","orc"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Aggressive","text":"As a bonus action, you can move up to your movement speed toward a hostile creature you can see or hear. You must end this move closer to the enemy than you started."},{"name":"Primal Intuition","text":"You have proficiency in two of the following skills of your choice: Animal Handling, Insight, Intimidation, Medicine, Nature, Perception, and Survival."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}],"lineage":"","age":{"mature":12,"max":50},"heightWeight":{"baseHeight":64,"heightMod":"2d8","baseWeight":175,"weightMod":"2d6"},"options":[],"description":""},{"id":"orc-mpmm","name":"Orc","source":"MPMM","page":28,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Adrenaline Rush","text":"You can take the Dash action as a bonus action. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nWhenever you use this trait, you gain a number of temporary hit points equal to your proficiency bonus."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."},{"name":"Relentless Endurance","text":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. Once you use this trait, you can't do so again until you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Orc.webp"]},{"id":"orc-vgm","name":"Orc","source":"VGM","page":120,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","insight","intimidation","medicine","nature","perception","survival"],"count":2}},{"kind":"language","fixed":["common","orc"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Aggressive","text":"As a bonus action, you can move up to your movement speed toward a hostile creature you can see or hear. You must end this move closer to the enemy than you started."},{"name":"Primal Intuition","text":"You have proficiency in two of the following skills of your choice: Animal Handling, Insight, Intimidation, Medicine, Nature, Perception, and Survival."},{"name":"Powerful Build","text":"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift."}],"lineage":"","age":{"mature":12,"max":50},"heightWeight":{"baseHeight":64,"heightMod":"2d8","baseWeight":175,"weightMod":"2d6"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Orc.webp"]},{"id":"orc-xphb","name":"Orc","source":"XPHB","page":195,"edition":"2024","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Adrenaline Rush","text":"You can take the Dash action as a Bonus Action. When you do so, you gain a number of Temporary Hit Points equal to your Proficiency Bonus.\n\nYou can use this trait a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Short or Long Rest."},{"name":"Darkvision","text":"You have Darkvision with a range of 120 feet."},{"name":"Relentless Endurance","text":"When you are reduced to 0 Hit Points but not killed outright, you can drop to 1 Hit Point instead. Once you use this trait, you can't do so again until you finish a Long Rest."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Orc.webp"],"srd":true},{"id":"orc-ixalan-psx","name":"Orc (Ixalan)","source":"PSX","page":15,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":1}}],"proficiencies":[{"kind":"skill","fixed":["intimidation"]},{"kind":"language","fixed":["common","orc"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Menacing","text":"You gain proficiency in the Intimidation skill."},{"name":"Relentless Endurance","text":"When you are reduced to 0 hit points but not killed outright, you can drop to 1 hit point instead. You can't use this feature again until you finish a long rest."},{"name":"Savage Attacks","text":"When you score a critical hit with a melee weapon attack, you can roll one of the weapon's damage dice one additional time and add it to the extra damage of the critical hit."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":{"mature":14,"max":75},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Orc.webp"]},{"id":"owlin-scc","name":"Owlin","source":"SCC","page":29,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9,"fly":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["stealth"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":36}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 120 feet of yourself as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Flight","text":"Thanks to your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor."},{"name":"Silent Feathers","text":"You have proficiency in the Stealth skill."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/SCC/Owlin.webp"]},{"id":"plasmoid-aag","name":"Plasmoid","source":"AAG","page":14,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["ooze"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["acid","poison"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Amorphous","text":"You can squeeze through a space as narrow as 1 inch wide, provided you are wearing and carrying nothing. You have advantage on ability checks you make to initiate or escape a grapple."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of yourself as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Hold Breath","text":"You can hold your breath for 1 hour."},{"name":"Natural Resilience","text":"You have resistance to acid and poison damage, and you have advantage on saving throws against being poisoned."},{"name":"Shape Self","text":"As an action, you can reshape your body to give yourself a head, one or two arms, one or two legs, and makeshift hands and feet, or you can revert to a limbless blob. While you have a humanlike shape, you can wear clothing and armor made for a Humanoid of your size.\n\nAs a bonus action, you can extrude a pseudopod that is up to 6 inches wide and 10 feet long or reabsorb it into your body. As part of the same bonus action, you can use this pseudopod to manipulate an object, open or close a door or container, or pick up or set down a Tiny object. The pseudopod contains no sensory organs and can't attack, activate magic items, or lift more than 10 pounds."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AAG/Plasmoid.webp"]},{"id":"reborn-rhw","name":"Reborn","source":"RHW","page":31,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"proficiencies":[{"kind":"skill","any":{"any":1}}],"resist":{"fixed":[],"choose":{"from":["cold","necrotic","poison"],"count":1}}},"feats":[],"traits":[{"name":"Escaped Death","text":"You have Advantage on Death Saving Throws."},{"name":"Everlasting","text":"You don't gain Exhaustion levels from dehydration, malnutrition, or suffocation. You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."},{"name":"Knowledge from a Past Life","text":"You gain proficiency in one skill of your choice.\n\nIn addition, you can temporarily peer into the past to aid you in the present. When you fail an ability check, you can roll 1d6 and add the number rolled to the d20, potentially turning the failure into a success. You can do this a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."},{"name":"Strange Endurance","text":"You have Resistance to one of the following damage types of your choice: Cold, Necrotic, or Poison."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/RHW/Reborn.webp"]},{"id":"reborn-vrgr","name":"Reborn","source":"VRGR","page":20,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["poison"]}},"feats":[],"traits":[{"name":"Ancestral Legacy","text":"If you replace a race with this lineage, you can keep the following elements of that race: any skill proficiencies you gained from it and any climbing, flying, or swimming speed you gained from it.\n\nIf you don't keep any of those elements or you choose this lineage at character creation, you gain proficiency in two skills of your choice."},{"name":"Deathless Nature","text":"You have escaped death, a fact represented by the following benefits:\n\n• You have advantage on saving throws against disease and being poisoned, and you have resistance to poison damage.\n• You have advantage on death saving throws.\n• You don't need to eat, drink, or breathe.\n• You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in an inactive, motionless state, during which you retain consciousness."},{"name":"Knowledge from a Past Life","text":"You temporarily remember glimpses of the past, perhaps faded memories from ages ago or a previous life. When you make an ability check that uses a skill, you can roll a d6 immediately after seeing the number on the d20 and add the number on the d6 to the check. You can use this feature a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VRGR/Reborn.webp"]},{"id":"rimekin-lfl","name":"Rimekin","source":"LFL","page":null,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"ray-of-frost-xphb","name":"Ray of Frost","how":"known","uses":"","at":"1"},{"spell":"ice-knife-xphb","name":"Ice Knife","how":"innate","uses":"1/day","at":"3"},{"spell":"flame-blade-xphb","name":"Flame Blade","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["cold"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Cold Fire Magic","text":"You know the Ray of Frost cantrip. When you reach character levels 3 and 5, you learn the Ice Knife spell and the Flame Blade spell, respectively. You always have those spells prepared. You can cast each once without a spell slot, and you regain the ability to cast these spells in this way when you finish a Long Rest. You can also cast the spells using any spell slots you have of the appropriate level. When you cast Flame Blade using this trait, the spell deals Cold damage instead of Fire damage.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose the ability when you select this species)."},{"name":"Cold Resistance","text":"You have Resistance to Cold damage."},{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/LFL/Rimekin.webp"]},{"id":"satyr-mot","name":"Satyr","source":"MOT","page":24,"edition":"2014","size":["Medium"],"speed":{"walk":10.5},"creatureTypes":["fey"],"benefits":{"ability":[{"fixed":{"dex":1,"cha":2}}],"proficiencies":[{"kind":"skill","fixed":["performance","persuasion"]},{"kind":"tool","any":{"anyMusicalInstrument":1}},{"kind":"language","fixed":["common","sylvan"]}]},"feats":[],"traits":[{"name":"Fey","text":"Your creature type is fey, rather than humanoid."},{"name":"Ram","text":"You can use your head and horns to make unarmed strikes. If you hit with them, you deal bludgeoning damage equal to 1d4 + your Strength modifier."},{"name":"Magic Resistance","text":"You have advantage on saving throws against spells and other magical effects."},{"name":"Mirthful Leaps","text":"Whenever you make a long or high jump, you can roll a d8 and add the number rolled to the number of feet you cover, even when making a standing jump. This extra distance costs movement as normal."},{"name":"Reveler","text":"You have proficiency in the Performance and Persuasion skills, and you have proficiency with one musical instrument of your choice."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d8","baseWeight":100,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Satyr.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Satyr%202.webp"]},{"id":"satyr-mpmm","name":"Satyr","source":"MPMM","page":29,"edition":"2014","size":["Medium"],"speed":{"walk":10.5},"creatureTypes":["fey"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["performance","persuasion"]},{"kind":"tool","any":{"anyMusicalInstrument":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Ram","text":"You can use your head and horns to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier bludgeoning damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Magic Resistance","text":"You have advantage on saving throws against spells."},{"name":"Mirthful Leaps","text":"Whenever you make a long jump or a high jump, you can roll a d8 and add the number rolled to the number of feet you cover, even when making a standing jump. This extra distance costs movement as usual."},{"name":"Reveler","text":"As an embodiment of revelry, you have proficiency in the Performance and Persuasion skills, and you have proficiency with one musical instrument of your choice."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Satyr.webp"]},{"id":"sea-elf-mpmm","name":"Sea Elf","source":"MPMM","page":30,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":"walk"},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["cold"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Child of the Sea","text":"You can breathe air and water, and you have resistance to cold damage."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Friend of the Sea","text":"Aquatic animals have an extraordinary affinity with your people. You can communicate simple ideas to any Beast that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Trance","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness.\n\nWhenever you finish this trance, you can gain two proficiencies that you don't have, each one with a 5 or a 5 of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."}],"lineage":"VRGR","age":{"mature":null,"max":750},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Sea%20Elf.webp"]},{"id":"shadar-kai-mpmm","name":"Shadar-Kai","source":"MPMM","page":31,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["necrotic"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Blessing of the Raven Queen","text":"As a bonus action, you can magically teleport up to 30 feet to an unoccupied space you can see. You can use this trait a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nStarting at 3rd level, you also gain resistance to all damage when you teleport using this trait. The resistance lasts until the start of your next turn. During that time, you appear ghostly and translucent."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Fey Ancestry","text":"You have advantage on saving throws you make to avoid or end the charmed condition on yourself."},{"name":"Keen Senses","text":"You have proficiency in the Perception skill."},{"name":"Necrotic Resistance","text":"You have resistance to necrotic damage."},{"name":"Trance","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a long rest in 4 hours if you spend those hours in a trancelike meditation, during which you retain consciousness.\n\nWhenever you finish this trance, you can gain two proficiencies that you don't have, each one with a 5 or a 5 of your choice selected from the Player's Handbook. You mystically acquire these proficiencies by drawing them from shared elven memory, and you retain them until you finish your next long rest."}],"lineage":"VRGR","age":{"mature":null,"max":750},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Shadar-kai.webp"]},{"id":"shifter-efa","name":"Shifter","source":"EFA","page":37,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"proficiencies":[{"kind":"skill","choose":{"from":["acrobatics","athletics","intimidation","survival"],"count":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Bestial Instincts","text":"Channeling the beast within, you gain proficiency in one of the following skills of your choice: Acrobatics, Athletics, Intimidation, or Survival."},{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Shifting","text":"As a Bonus Action, you can shape-shift to assume a more bestial appearance. This transformation lasts for 1 minute or until you revert to your normal appearance as a Bonus Action. When you shift, you gain Temporary Hit Points equal to 2 times your Proficiency Bonus. You can shift a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.\n\nWhenever you shift, you gain the benefit of one of the following options (choose when you select this species)\n\n• Beasthide You gain 1d6 additional Temporary Hit Points. While shifted, you have a +1 bonus to your Armor Class.\n• Longtooth When you shift and as a Bonus Action on your other turns while shifted, you can use your elongated fangs to make an Unarmed Strike. If you hit with this Unarmed Strike and deal damage, you can deal Piercing damage equal to 1d6 plus your Strength modifier, instead of the normal damage of an Unarmed Strike.\n• Swiftstride While you are shifted, your Speed increases by 10 feet. Additionally, you can move up to 10 feet as a Reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke Opportunity Attacks.\n• Wildhunt While shifted, you have Advantage on Wisdom checks. Additionally, no creature within 30 feet of you can have Advantage on an attack roll against you unless you have the Incapacitated condition."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"shifter-efa--beasthide","name":"Beasthide","kind":"lineage","source":"EFA","page":37,"traits":[{"name":"Shifting (Beasthide)","text":"As a Bonus Action, you can shape-shift to assume a more bestial appearance. This transformation lasts for 1 minute or until you revert to your normal appearance as a Bonus Action. When you shift, you gain Temporary Hit Points equal to 2 times your Proficiency Bonus. You can shift a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.\n\nWhenever you shift, you gain 1d6 additional Temporary Hit Points. While shifted, you have a +1 bonus to your Armor Class."}],"removes":["Shifting"]},{"id":"shifter-efa--longtooth","name":"Longtooth","kind":"lineage","source":"EFA","page":37,"traits":[{"name":"Shifting (Longtooth)","text":"As a Bonus Action, you can shape-shift to assume a more bestial appearance. This transformation lasts for 1 minute or until you revert to your normal appearance as a Bonus Action. When you shift, you gain Temporary Hit Points equal to 2 times your Proficiency Bonus. You can shift a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.\n\nWhen you shift and as a Bonus Action on your other turns while shifted, you can use your elongated fangs to make an Unarmed Strike. If you hit with this Unarmed Strike and deal damage, you can deal Piercing damage equal to 1d6 plus your Strength modifier, instead of the normal damage of an Unarmed Strike."}],"removes":["Shifting"]},{"id":"shifter-efa--swiftstride","name":"Swiftstride","kind":"lineage","source":"EFA","page":37,"traits":[{"name":"Shifting (Swiftstride)","text":"As a Bonus Action, you can shape-shift to assume a more bestial appearance. This transformation lasts for 1 minute or until you revert to your normal appearance as a Bonus Action. When you shift, you gain Temporary Hit Points equal to 2 times your Proficiency Bonus. You can shift a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.\n\nWhile you are shifted, your Speed increases by 10 feet. Additionally, you can move up to 10 feet as a Reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke Opportunity Attacks."}],"removes":["Shifting"]},{"id":"shifter-efa--wildhunt","name":"Wildhunt","kind":"lineage","source":"EFA","page":37,"traits":[{"name":"Shifting (Wildhunt)","text":"As a Bonus Action, you can shape-shift to assume a more bestial appearance. This transformation lasts for 1 minute or until you revert to your normal appearance as a Bonus Action. When you shift, you gain Temporary Hit Points equal to 2 times your Proficiency Bonus. You can shift a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.\n\nWhile shifted, you have Advantage on Wisdom checks. Additionally, no creature within 30 feet of you can have Advantage on an attack roll against you unless you have the Incapacitated condition."}],"removes":["Shifting"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EFA/Shifter.webp"]},{"id":"shifter-erlw","name":"Shifter","source":"ERLW","page":33,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"proficiencies":[{"kind":"language","fixed":["common"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Shifting","text":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to your level + your Constitution modifier (minimum of 1 temporary hit point). You also gain additional benefits that depend on your shifter subrace, described below.\n\nOnce you shift, you can't do so again until you finish a short or long rest."}],"lineage":"","age":{"mature":10,"max":70},"heightWeight":{"baseHeight":54,"heightMod":"2d8","baseWeight":90,"weightMod":"2d4"},"options":[{"id":"shifter-erlw--beasthide","name":"Beasthide","kind":"subrace","source":"ERLW","page":34,"traits":[{"name":"Natural Athlete","text":"You have proficiency in the Athletics skill."},{"name":"Shifting Feature","text":"Whenever you shift, you gain 1d6 additional temporary hit points. While shifted, you have a +1 bonus to your Armor Class."}],"removes":[],"benefits":{"ability":[{"fixed":{"str":1,"con":2}}],"proficiencies":[{"kind":"skill","fixed":["athletics"]},{"kind":"language","fixed":["common"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Shifter%20001.webp"]},{"id":"shifter-erlw--longtooth","name":"Longtooth","kind":"subrace","source":"ERLW","page":34,"traits":[{"name":"Fierce","text":"You have proficiency in the Intimidation skill."},{"name":"Shifting Feature","text":"While shifted, you can use your elongated fangs to make an unarmed strike as a bonus action. If you hit with your fangs, you can deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}],"removes":[],"benefits":{"ability":[{"fixed":{"str":2,"dex":1}}],"proficiencies":[{"kind":"skill","fixed":["intimidation"]},{"kind":"language","fixed":["common"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Shifter%20001.webp"]},{"id":"shifter-erlw--swiftstride","name":"Swiftstride","kind":"subrace","source":"ERLW","page":34,"traits":[{"name":"Graceful","text":"You have proficiency in the Acrobatics skill."},{"name":"Shifting Feature","text":"While shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke opportunity attacks."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}],"proficiencies":[{"kind":"skill","fixed":["acrobatics"]},{"kind":"language","fixed":["common"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Shifter%20001.webp"]},{"id":"shifter-erlw--wildhunt","name":"Wildhunt","kind":"subrace","source":"ERLW","page":34,"traits":[{"name":"Natural Tracker","text":"You have proficiency in the Survival skill."},{"name":"Shifting Feature","text":"While shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you, unless you're incapacitated."}],"removes":[],"benefits":{"ability":[{"fixed":{"dex":1,"wis":2}}],"proficiencies":[{"kind":"skill","fixed":["survival"]},{"kind":"language","fixed":["common"]}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Shifter%20(Wildhunt).webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Shifter%20001.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Shifter%20001.webp"]},{"id":"shifter-mpmm","name":"Shifter","source":"MPMM","page":32,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["acrobatics","athletics","intimidation","survival"],"count":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Bestial Instincts","text":"Channeling the beast within, you have proficiency in one of the following skills of your choice: Acrobatics, Athletics, Intimidation, or Survival."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were in dim light. You discern colors in that darkness only as shades of gray."},{"name":"Shifting","text":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus. You can shift a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nWhenever you shift, you gain an additional benefit based on one of the following options (choose when you select this race):\n\n• Beasthide You gain 1d6 additional temporary hit points. While shifted, you have a +1 bonus to your Armor Class.\n• Longtooth When you shift and as a bonus action on your other turns while shifted, you can use your elongated fangs to make an unarmed strike. If you hit with your fangs, you can deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike.\n• Swiftstride While shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke opportunity attacks.\n• Wildhunt While shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you unless you're incapacitated."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[{"id":"shifter-mpmm--beasthide","name":"Beasthide","kind":"lineage","source":"MPMM","page":32,"traits":[{"name":"Shifting (Beasthide)","text":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus + 1d6, and you regain all expended uses when you finish a long rest.\n\nWhile shifted, you have a +1 bonus to your Armor Class."}],"removes":["Shifting"]},{"id":"shifter-mpmm--longtooth","name":"Longtooth","kind":"lineage","source":"MPMM","page":32,"traits":[{"name":"Shifting (Longtooth)","text":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nWhen you shift and as a bonus action on your other turns while shifted, you can use your elongated fangs to make an unarmed strike. If you hit with your fangs, you can deal piercing damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."}],"removes":["Shifting"]},{"id":"shifter-mpmm--swiftstride","name":"Swiftstride","kind":"lineage","source":"MPMM","page":32,"traits":[{"name":"Shifting (Swiftstride)","text":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nWhile shifted, your walking speed increases by 10 feet. Additionally, you can move up to 10 feet as a reaction when a creature ends its turn within 5 feet of you. This reactive movement doesn't provoke opportunity attacks."}],"removes":["Shifting"]},{"id":"shifter-mpmm--wildhunt","name":"Wildhunt","kind":"lineage","source":"MPMM","page":32,"traits":[{"name":"Shifting (Wildhunt)","text":"As a bonus action, you can assume a more bestial appearance. This transformation lasts for 1 minute, until you die, or until you revert to your normal appearance as a bonus action. When you shift, you gain temporary hit points equal to 2 × your proficiency bonus, and you regain all expended uses when you finish a long rest.\n\nWhile shifted, you have advantage on Wisdom checks, and no creature within 30 feet of you can make an attack roll with advantage against you unless you're incapacitated."}],"removes":["Shifting"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Shifter.webp"]},{"id":"simic-hybrid-ggr","name":"Simic Hybrid","source":"GGR","page":20,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2},"choose":{"from":["str","dex","int","wis","cha"],"count":1,"amount":1}}],"proficiencies":[{"kind":"language","choose":{"from":["elvish","other"],"count":1},"fixed":["common"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Animal Enhancement","text":"Your body has been altered to incorporate certain animal characteristics. You choose one animal enhancement now and a second enhancement at 5th level.\n\nAt 1st level, choose one of the following options:\n\n• Manta Glide You have ray-like fins that you can use as wings to slow your fall or allow you to glide. When you fall and aren't incapacitated, you can subtract up to 100 feet from the fall when calculating falling damage, and you can move up to 2 feet horizontally for every 1 foot you descend.\n• Nimble Climber You have a climbing speed equal to your walking speed.\n• Underwater Adaptation You can breathe air and water, and you have a swimming speed equal to your walking speed.\n\nAt 5th level, your body evolves further, developing new characteristics. Choose one of the options you didn't take at 1st level, or one of the following options:\n\n• Grappling Appendage You have two special appendages growing alongside your arms. Choose whether they're both claws or tentacles. As an action, you can use one of them to try to grapple a creature. Each one is also a natural weapon, which you can use to make an unarmed strike. If you hit with it, the target takes bludgeoning damage equal to 1d6 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike. Immediately after hitting, you can try to grapple the target as a bonus action. These appendages can't precisely manipulate anything and can't wield weapons, magic items, or other specialized equipment.\n• Carapace Your skin in places is covered by a thick shell. You gain a +1 bonus to AC when you're not wearing heavy armor.\n• Acid Spit As an action, you can spray acid from glands in your mouth, targeting one creature or object you can see within 30 feet of you. The target takes 2d10 acid damage unless it succeeds on a Dexterity saving throw against a DC equal to 8 + your Constitution modifier + your proficiency bonus. This damage increases by 1d10 when you reach 11th level (3d10) and 17th level (4d10). You can use this trait a number of times equal to your Constitution modifier (minimum of once), and you regain all expended uses of it when you finish a long rest."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/GGR/Simic%20Hybrid.webp"]},{"id":"siren-psx","name":"Siren","source":"PSX","page":17,"edition":"","size":["Medium"],"speed":{"walk":7.5,"fly":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":2}}],"proficiencies":[{"kind":"language","fixed":["common","other"]}],"spells":{"ability":null,"groups":[{"name":"","items":[{"spell":"friends-phb","name":"Friends","how":"known","uses":"","at":"1"}]}]}},"feats":[],"traits":[{"name":"Siren's Song","text":"You know the friends cantrip and can cast it without material components."},{"name":"Flight","text":"You have a flying speed of 30 feet. You can't use your flying speed while you wear medium or heavy armor. (If your campaign uses the variant rule for encumbrance, you can't use your flying speed if you are encumbered.)"}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Siren.webp"]},{"id":"skeleton-dmg","name":"Skeleton","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["undead"],"benefits":{"ability":[{"fixed":{"dex":2,"int":-4,"cha":-4}}],"immune":{"fixed":["poison"]},"conditionImmune":{"fixed":["exhaustion","poisoned"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Brittle Bones","text":"You are vulnerable to bludgeoning damage."},{"name":"Undead Nature","text":"You are immune to poison damage and exhaustion, and you can't be poisoned. You don't require air, food, drink, or sleep."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"tabaxi-mpmm","name":"Tabaxi","source":"MPMM","page":33,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9,"climb":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","fixed":["perception","stealth"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Cat's Claws","text":"You can use your claws to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Cat's Talent","text":"You have proficiency in the Perception and Stealth skills."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Feline Agility","text":"Your reflexes and agility allow you to move with a burst of speed. When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can't use it again until you move 0 feet on one of your turns."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Tabaxi.webp"]},{"id":"tabaxi-vgm","name":"Tabaxi","source":"VGM","page":113,"edition":"2014","size":["Medium"],"speed":{"walk":9,"climb":6},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"dex":2,"cha":1}}],"proficiencies":[{"kind":"skill","fixed":["perception","stealth"]},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have a cat's keen senses, especially in the dark. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Feline Agility","text":"Your reflexes and agility allow you to move with a burst of speed. When you move on your turn in combat, you can double your speed until the end of the turn. Once you use this trait, you can't use it again until you move 0 feet on one of your turns."},{"name":"Cat's Claws","text":"Because of your claws, you have a climbing speed of 20 feet. In addition, your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Cat's Talents","text":"You have proficiency in the Perception and Stealth skills."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":58,"heightMod":"2d10","baseWeight":90,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Tabaxi.webp"]},{"id":"thri-kreen-aag","name":"Thri-kreen","source":"AAG","page":15,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["monstrosity"],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Chameleon Carapace","text":"While you aren't wearing armor, your carapace gives you a base Armor Class of 13 + your Dexterity modifier.\n\nAs an action, you can change the color of your carapace to match the color and texture of your surroundings, giving you advantage on Dexterity (Stealth) checks made to hide in those surroundings."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of yourself as if it were bright light, and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Secondary Arms","text":"You have two slightly smaller secondary arms below your primary pair of arms. The secondary arms can manipulate an object, open or close a door or container, pick up or set down a Tiny object, or wield a weapon that has the light property."},{"name":"Sleepless","text":"You do not require sleep and can remain conscious during a long rest, though you must still refrain from strenuous activity to gain the benefit of the rest."},{"name":"Thri-kreen Telepathy","text":"Without the assistance of magic, you can't speak the non-thri-kreen languages you know. Instead you use telepathy to convey your thoughts. You have the magical ability to transmit your thoughts mentally to willing creatures within 120 feet of yourself. A contacted creature doesn't need to share a language with you to understand your thoughts, but it must be able to understand at least one language. Your telepathic link to a creature is broken if you and the creature move more than 120 feet apart, if either of you is incapacitated, or if either of you mentally breaks the contact (no action required)."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AAG/Thri-kreen.webp"]},{"id":"tiefling-base-phb","name":"Tiefling (Base)","source":"PHB","page":42,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":1,"cha":2}}],"proficiencies":[{"kind":"language","fixed":["common","infernal"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"thaumaturgy-phb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":null,"name":"Hellish Rebuke#2","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-phb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["fire"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"Thanks to your infernal heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Hellish Resistance","text":"You have resistance to fire damage."},{"name":"Infernal Legacy","text":"You know the thaumaturgy cantrip. Once you reach 3rd level, you can cast the hellish rebuke spell as a 2nd-level spell with this trait; you regain the ability to cast it when you finish a long rest. Once you reach 5th level, you can also cast the darkness spell once per day with this trait; you regain the ability to cast it when you finish a long rest. Charisma is your spellcasting ability for these spells."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":57,"heightMod":"2d8","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PHB/Tiefling.webp"],"srd":true},{"id":"tiefling-xphb","name":"Tiefling","source":"XPHB","page":197,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["humanoid"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"Abyssal","items":[{"spell":"thaumaturgy-xphb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":"poison-spray-xphb","name":"Poison Spray","how":"known","uses":"","at":"1"},{"spell":"ray-of-sickness-xphb","name":"Ray of Sickness","how":"innate","uses":"1/day","at":"3"},{"spell":"hold-person-xphb","name":"Hold Person","how":"innate","uses":"1/day","at":"5"}]},{"name":"Chthonic","items":[{"spell":"thaumaturgy-xphb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":"chill-touch-xphb","name":"Chill Touch","how":"known","uses":"","at":"1"},{"spell":"false-life-xphb","name":"False Life","how":"innate","uses":"1/day","at":"3"},{"spell":"ray-of-enfeeblement-xphb","name":"Ray of Enfeeblement","how":"innate","uses":"1/day","at":"5"}]},{"name":"Infernal","items":[{"spell":"thaumaturgy-xphb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":"fire-bolt-xphb","name":"Fire Bolt","how":"known","uses":"","at":"1"},{"spell":"hellish-rebuke-xphb","name":"Hellish Rebuke","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-xphb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":[],"choose":{"from":["poison","necrotic","fire"],"count":1}},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You have Darkvision with a range of 60 feet."},{"name":"Fiendish Legacy","text":"You are the recipient of a legacy that grants you supernatural abilities. Choose a legacy from the Fiendish Legacies table. You gain the level 1 benefit of the chosen legacy.\n\nWhen you reach character levels 3 and 5, you learn a higher-level spell, as shown on the table. You always have that spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the legacy).\n\nFiendish Legacies:\n| Legacy | Level 1 | Level 3 | Level 5 |\n| Abyssal | You have Resistance to Poison damage. You also know the Poison Spray cantrip. | Ray of Sickness | Hold Person |\n| Chthonic | You have Resistance to Necrotic damage. You also know the Chill Touch cantrip. | False Life | Ray of Enfeeblement |\n| Infernal | You have Resistance to Fire damage. You also know the Fire Bolt cantrip. | Hellish Rebuke | Darkness |"},{"name":"Otherworldly Presence","text":"You know the Thaumaturgy cantrip. When you cast it with this trait, the spell uses the same spellcasting ability you use for your Fiendish Legacy Trait."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"tiefling-xphb--abyssal-legacy","name":"Abyssal Legacy","kind":"lineage","source":"XPHB","page":197,"traits":[{"name":"Fiendish Legacy (Abyssal)","text":"You are the recipient of a legacy that grants you supernatural abilities. You have Resistance to Poison damage. You also know the Poison Spray cantrip.\n\nWhen you reach character level 3, you learn the Ray of Sickness spell. When you reach character level 5, you also learn the Hold Person spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the legacy)."}],"removes":["Fiendish Legacy"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"thaumaturgy-xphb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":"poison-spray-xphb","name":"Poison Spray","how":"known","uses":"","at":"1"},{"spell":"ray-of-sickness-xphb","name":"Ray of Sickness","how":"innate","uses":"1/day","at":"3"},{"spell":"hold-person-xphb","name":"Hold Person","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["poison"]},"senses":[{"type":"darkvision","range":36}]}},{"id":"tiefling-xphb--chthonic-legacy","name":"Chthonic Legacy","kind":"lineage","source":"XPHB","page":197,"traits":[{"name":"Fiendish Legacy (Chthonic)","text":"You are the recipient of a legacy that grants you supernatural abilities. You have Resistance to Necrotic damage. You also know the Chill Touch cantrip.\n\nWhen you reach character level 3, you learn the False Life spell. When you reach character level 5, you also learn the Ray of Enfeeblement spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the legacy)."}],"removes":["Fiendish Legacy"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"thaumaturgy-xphb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":"chill-touch-xphb","name":"Chill Touch","how":"known","uses":"","at":"1"},{"spell":"false-life-xphb","name":"False Life","how":"innate","uses":"1/day","at":"3"},{"spell":"ray-of-enfeeblement-xphb","name":"Ray of Enfeeblement","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["necrotic"]}}},{"id":"tiefling-xphb--infernal-legacy","name":"Infernal Legacy","kind":"lineage","source":"XPHB","page":197,"traits":[{"name":"Fiendish Legacy (Infernal)","text":"You are the recipient of a legacy that grants you supernatural abilities. You have Resistance to Fire damage. You also know the Fire Bolt cantrip.\n\nWhen you reach character level 3, you learn the Hellish Rebuke spell. When you reach character level 5, you also learn the Darkness spell. You always have these spells prepared, and you can cast each spell once without a spell slot. Once you cast either of these spells with this trait, you can't cast that spell with it again until you finish a Long Rest. You can also cast the spell using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait (choose the ability when you select the legacy)."}],"removes":["Fiendish Legacy"],"benefits":{"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"thaumaturgy-xphb","name":"Thaumaturgy","how":"known","uses":"","at":"1"},{"spell":"fire-bolt-xphb","name":"Fire Bolt","how":"known","uses":"","at":"1"},{"spell":"hellish-rebuke-xphb","name":"Hellish Rebuke","how":"innate","uses":"1/day","at":"3"},{"spell":"darkness-xphb","name":"Darkness","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["fire"]}}}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/Tiefling.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/156-05-029.infernal-chthonic-abyssal.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/XPHB/157-05-028.armored-tiefling.webp"],"srd":true},{"id":"tortle-mpmm","name":"Tortle","source":"MPMM","page":34,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"skill","choose":{"from":["animal handling","medicine","nature","perception","stealth","survival"],"count":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Claws","text":"You have claws that you can use to make unarmed strikes. When you hit with them, the strike deals 1d6 + your Strength modifier slashing damage, instead of the bludgeoning damage normal for an unarmed strike."},{"name":"Hold Breath","text":"You can hold your breath for up to 1 hour."},{"name":"Natural Armor","text":"Your shell provides you a base AC of 17 (your Dexterity modifier doesn't affect this number). You can't wear light, medium, or heavy armor, but if you are using a shield, you can apply the shield's bonus as normal."},{"name":"Nature's Intuition","text":"Thanks to your mystical connection to nature, you gain proficiency with one of the following skills of your choice: Animal Handling, Medicine, Nature, Perception, Stealth, or Survival."},{"name":"Shell Defense","text":"You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to your AC, and you have advantage on Strength and Constitution saving throws. While in your shell, you are prone, your speed is 0 and can't increase, you have disadvantage on Dexterity saving throws, you can't take reactions, and the only action you can take is a bonus action to emerge from your shell."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Tortle.webp"]},{"id":"tortle-ttp","name":"Tortle","source":"TTP","page":3,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"wis":1}}],"proficiencies":[{"kind":"skill","fixed":["survival"]},{"kind":"language","fixed":["aquan","common"]}]},"feats":[],"traits":[{"name":"Claws","text":"Your claws are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of bludgeoning damage normal for an unarmed strike."},{"name":"Hold Breath","text":"You can hold your breath for up to 1 hour at a time. Tortles aren't natural swimmers, but they can remain underwater for some time before needing to come up for air."},{"name":"Natural Armor","text":"Due to your shell and the shape of your body, you are ill-suited to wearing armor. Your shell provides ample protection, however; it gives you a base AC of 17 (your Dexterity modifier doesn't affect this number). You gain no benefit from wearing armor, but if you are using a shield, you can apply the shield's bonus as normal."},{"name":"Shell Defense","text":"You can withdraw into your shell as an action. Until you emerge, you gain a +4 bonus to AC, and you have advantage on Strength and Constitution saving throws. While in your shell, you are prone, your speed is 0 and can't increase, you have disadvantage on Dexterity saving throws, you can't take reactions, and the only action you can take is a bonus action to emerge from your shell."},{"name":"Survival Instinct","text":"You gain proficiency in the Survival skill. Tortles have finely honed survival instincts."}],"lineage":"","age":{"mature":15,"max":50},"heightWeight":null,"options":[],"description":"The Tortle Package is considered part of Xanathar's Guide to Everything for Adventurers League character creation.","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/TTP/Tortle.webp"]},{"id":"triton-mot","name":"Triton","source":"MOT","page":26,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"con":1,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common","primordial"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"fog-cloud-phb","name":"Fog Cloud","how":"innate","uses":"1/day","at":"1"},{"spell":"gust-of-wind-phb","name":"Gust of Wind","how":"innate","uses":"1/day","at":"3"},{"spell":"wall-of-water-xge","name":"Wall of Water","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["cold"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Swim Speed","text":"You have a swimming speed of 30 feet."},{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Control Air and Water","text":"A child of the sea, you can call on the magic of elemental air and water. You can cast fog cloud with this trait. Starting at 3rd level, you can cast gust of wind with it, and starting at 5th level, you can also cast wall of water with it. Once you cast a spell with this trait, you can't cast that spell with it again until you finish a long rest. Charisma is your spellcasting ability for these spells."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Emissary of the Sea","text":"Aquatic beasts have an extraordinary affinity with your people. You can communicate simple ideas with beasts that can breathe water. They can understand the meaning of your words, though you have no special ability to understand them in return."},{"name":"Guardians of the Depths","text":"Adapted to even the most extreme ocean depths, you have resistance to cold damage."}],"lineage":"","age":{"mature":15,"max":200},"heightWeight":{"baseHeight":54,"heightMod":"2d10","baseWeight":90,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Triton.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MOT/Triton%202.webp"]},{"id":"triton-mpmm","name":"Triton","source":"MPMM","page":35,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":"walk"},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"fog-cloud-phb","name":"Fog Cloud","how":"innate","uses":"1/day","at":"1"},{"spell":"gust-of-wind-phb","name":"Gust of Wind","how":"innate","uses":"1/day","at":"3"},{"spell":"water-walk-phb","name":"Water Walk","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["cold"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Control Air and Water","text":"You can cast fog cloud with this trait. Starting at 3rd level, you can cast the gust of wind spell with this trait. Starting at 5th level, you can also cast the water walk spell with it. Once you cast any of these spells with this trait, you can't cast that spell with it again until you finish a long rest. You can also cast these spells using any spell slots you have of the appropriate level.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Emissary of the Sea","text":"You can communicate simple ideas to any Beast, Elemental, or Monstrosity that has a swimming speed. It can understand your words, though you have no special ability to understand it in return."},{"name":"Guardian of the Depths","text":"Adapted to the frigid ocean depths, you have resistance to cold damage."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Triton.webp"]},{"id":"triton-vgm","name":"Triton","source":"VGM","page":115,"edition":"2014","size":["Medium"],"speed":{"walk":9,"swim":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":1,"con":1,"cha":1}}],"proficiencies":[{"kind":"language","fixed":["common","primordial"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"fog-cloud-phb","name":"Fog Cloud","how":"innate","uses":"1/day","at":"1"},{"spell":"gust-of-wind-phb","name":"Gust of Wind","how":"innate","uses":"1/day","at":"3"},{"spell":"wall-of-water-xge","name":"Wall of Water","how":"innate","uses":"1/day","at":"5"}]}]},"resist":{"fixed":["cold"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Swim Speed","text":"You have a swimming speed of 30 feet."},{"name":"Amphibious","text":"You can breathe air and water."},{"name":"Control Air and Water","text":"A child of the sea, you can call on the magic of elemental air and water. You can cast fog cloud with this trait. Starting at 3rd level, you can cast gust of wind with it, and starting at 5th level, you can also cast wall of water with it. Once you cast a spell with this trait, you can't cast that spell with it again until you finish a long rest. Charisma is your spellcasting ability for these spells."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Emissary of the Sea","text":"Aquatic beasts have an extraordinary affinity with your people. You can communicate simple ideas with beasts that can breathe water. They can understand the meaning of your words, though you have no special ability to understand them in return."},{"name":"Guardians of the Depths","text":"Adapted to even the most extreme ocean depths, you have resistance to cold damage."}],"lineage":"","age":{"mature":15,"max":200},"heightWeight":{"baseHeight":54,"heightMod":"2d10","baseWeight":90,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Triton.webp"]},{"id":"troglodyte-dmg","name":"Troglodyte","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"str":2,"con":2,"int":-4,"cha":-4}}],"proficiencies":[{"kind":"language","fixed":["other"]}],"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Chameleon Skin","text":"You have advantage on Dexterity (Stealth) checks made to hide."},{"name":"Stench","text":"Any creature other than a troglodyte that starts its turn within 5 ft. of you must succeed on a DC 12 Constitution saving throw or be poisoned until the start of the creature's next turn. On a successful saving throw, the creature is immune to the stench of all troglodytes for 1 hour."},{"name":"Sunlight Sensitivity","text":"While in sunlight, you have disadvantage on attack rolls, as well as on Wisdom (Perception) checks that rely on sight."},{"name":"Natural Armor","text":"Your thick hide grants you a +1 bonus to Armor Class."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""},{"id":"vampire-psz","name":"Vampire","source":"PSZ","page":14,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"cha":2}}],"proficiencies":[{"kind":"language","fixed":["common","other"]}],"resist":{"fixed":["necrotic"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Blood Thirst","text":"You can drain blood and life energy from a willing creature, or one that is grappled by you, incapacitated, or restrained. Make a melee attack against the target. If you hit, you deal 1 piercing damage and 1d6 necrotic damage. The target's hit point maximum is reduced by an amount equal to the necrotic damage taken, and you regain hit points equal to that amount. The reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0."},{"name":"Darkvision","text":"Thanks to your heritage, you have superior vision in dark and dim conditions. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Vampiric Resistance","text":"You have resistance to necrotic damage."}],"lineage":"","age":null,"heightWeight":null,"options":[{"id":"vampire-psz--ixalan-psx","name":"Ixalan","kind":"subrace","source":"PSX","page":14,"traits":[{"name":"Feast of Blood","text":"When you drain blood with your Bloodthirst ability, you experience a surge of vitality. Your speed increases by 10 feet, and you gain advantage on Strength and Dexterity checks and saving throws for 1 minute."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":2,"wis":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Vampire.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Vampire2.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSX/Vampire3.webp"]},{"id":"vampire-psz--zendikar","name":"Zendikar","kind":"subrace","source":"PSZ","page":14,"traits":[{"name":"Null Transformation","text":"A humanoid killed with your Bloodthirst ability becomes a null."}],"removes":[],"benefits":{"ability":[{"fixed":{"cha":2,"int":1}}]},"images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Vampire.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Vampire2.webp"]}],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Vampire.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSZ/Vampire2.webp"]},{"id":"vedalken-ggr","name":"Vedalken","source":"GGR","page":21,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":2,"wis":1}}],"proficiencies":[{"kind":"skill","choose":{"from":["arcana","history","investigation","medicine","performance","sleight of hand"],"count":1}},{"kind":"tool","any":{"any":1}},{"kind":"language","fixed":["common","other"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Vedalken Dispassion","text":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws."},{"name":"Tireless Precision","text":"You are proficient in one of the following skills of your choice: Arcana, History, Investigation, Medicine, Performance, or Sleight of Hand. You are also proficient with one 5 of your choice.\n\nWhenever you make an ability check with the chosen skill or tool, roll a d4 and add the number rolled to the check's total."},{"name":"Partially Amphibious","text":"By absorbing oxygen through your skin, you can breathe underwater for up to 1 hour. Once you've reached that limit, you can't use this trait again until you finish a long rest."}],"lineage":"","age":{"mature":40,"max":500},"heightWeight":{"baseHeight":64,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/GGR/Vedalken.webp"]},{"id":"vedalken-psk","name":"Vedalken","source":"PSK","page":23,"edition":"","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":2,"wis":1}}],"proficiencies":[{"kind":"language","fixed":["common","other"]}]},"feats":[],"traits":[{"name":"Vedalken Cunning","text":"You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic."},{"name":"Aether Lore","text":"Whenever you make an Intelligence (History) check related to magic items or aether-powered technological devices, you can add twice your proficiency bonus, instead of any proficiency bonus you normally apply."}],"lineage":"","age":{"mature":40,"max":500},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Vedalken.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/PSK/Vedalken2.webp"]},{"id":"verdan-ai","name":"Verdan","source":"AI","page":72,"edition":"2014","size":["Varies"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":1,"cha":2}}],"proficiencies":[{"kind":"skill","fixed":["persuasion"]},{"kind":"language","fixed":["common","goblin"],"any":{"anyStandard":1}}]},"feats":[],"traits":[{"name":"Black Blood Healing","text":"The black blood that is a sign of your people's connection to That-Which-Endures boosts your natural healing. When you roll a 1 or 2 on any Hit Die you spend at the end of a short rest, you can reroll the die and must use the new roll."},{"name":"Limited Telepathy","text":"You can telepathically speak to any creature you can see within 30 feet of you. You don't need to share a language with the creature for it to understand your telepathy, but it must be able to understand at least one language. This process of communication is slow and limited, allowing you to transmit and receive only simple ideas and straightforward concepts."},{"name":"Persuasive","text":"Your people's lack of history makes you trustworthy and humble. You have proficiency in the Persuasion skill."},{"name":"Telepathic Insight","text":"Your mind's connection to the world around you strengthens your will. You have advantage on all Wisdom and Charisma saving throws."}],"lineage":"","age":{"mature":24,"max":200},"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/AI/Verdan.webp"]},{"id":"warforged-efa","name":"Warforged","source":"EFA","page":38,"edition":"2024","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":["construct"],"benefits":{"proficiencies":[{"kind":"skill","any":{"any":1}},{"kind":"tool","any":{"any":1}}],"resist":{"fixed":["poison"]}},"feats":[],"traits":[{"name":"Construct Resilience","text":"You have Resistance to Poison damage. You also have Advantage on saving throws to avoid or end the Poisoned condition."},{"name":"Integrated Protection","text":"You gain a +1 bonus to your Armor Class. In addition, armor you have donned can't be removed against your will while you're alive."},{"name":"Sentry's Rest","text":"You don't need to sleep, and magic can't put you to sleep. You can finish a Long Rest in 6 hours if you spend those hours in an inactive, motionless state. During this time, you appear inert but remain conscious."},{"name":"Specialized Design","text":"You gain one skill proficiency and one tool proficiency of your choice."},{"name":"Tireless","text":"You don't gain Exhaustion levels from dehydration, malnutrition, or suffocation."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/EFA/Warforged.webp"]},{"id":"warforged-erlw","name":"Warforged","source":"ERLW","page":35,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"con":2},"choose":{"from":["str","dex","int","wis","cha"],"count":1,"amount":1}}],"proficiencies":[{"kind":"skill","any":{"any":1}},{"kind":"tool","any":{"any":1}},{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"resist":{"fixed":["poison"]},"conditionImmune":{"fixed":["disease"]}},"feats":[],"traits":[{"name":"Constructed Resilience","text":"You were created to have remarkable fortitude, represented by the following benefits:\n\n• You have advantage on saving throws against being poisoned, and you have resistance to poison damage.\n• You don't need to eat, drink, or breathe.\n• You are immune to disease.\n• You don't need to sleep, and magic can't put you to sleep."},{"name":"Sentry's Rest","text":"When you take a long rest, you must spend at least six hours in an inactive, motionless state, rather than sleeping. In this state, you appear inert, but it doesn't render you unconscious, and you can see and hear as normal."},{"name":"Integrated Protection","text":"Your body has built-in defensive layers, which can be enhanced with armor:\n\n• You gain a +1 bonus to Armor Class.\n• You can don only armor with which you have proficiency. To don armor other than a shield, you must incorporate it into your body over the course of 1 hour, during which you remain in contact with the armor. To doff armor, you must spend 1 hour removing it. You can rest while donning or doffing armor in this way.\n• While you live, the armor incorporated into your body can't be removed against your will."},{"name":"Specialized Design","text":"You gain one skill proficiency and one tool proficiency of your choice."}],"lineage":"","age":{"mature":2,"max":30},"heightWeight":{"baseHeight":70,"heightMod":"2d6","baseWeight":270,"weightMod":"4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Warforged.webp","https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/ERLW/Warforged%20001.webp"]},{"id":"yuan-ti-mpmm","name":"Yuan-Ti","source":"MPMM","page":36,"edition":"2014","size":["Small","Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[2,1]}},{"weighted":{"from":["str","dex","con","int","wis","cha"],"weights":[1,1,1]}}],"proficiencies":[{"kind":"language","fixed":["common"],"any":{"anyStandard":1}}],"spells":{"ability":{"choose":["int","wis","cha"]},"groups":[{"name":"","items":[{"spell":"poison-spray-phb","name":"Poison Spray","how":"known","uses":"","at":"1"},{"spell":"animal-friendship-phb","name":"Animal Friendship","how":"innate","uses":"","at":"1"},{"spell":"suggestion-phb","name":"Suggestion","how":"innate","uses":"1/day","at":"3"}]}]},"resist":{"fixed":["poison"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray."},{"name":"Magic Resistance","text":"You have advantage on saving throws against spells."},{"name":"Poison Resilience","text":"You have advantage on saving throws you make to avoid or end the poisoned condition on yourself. You also have resistance to poison damage."},{"name":"Serpentine Spellcasting","text":"You know the poison spray cantrip. You can cast animal friendship an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast suggestion with this trait. Once you cast it, you can't do so again until you finish a long rest. You can also cast it using any spell slots you have of 2nd level or higher.\n\nIntelligence, Wisdom, or Charisma is your spellcasting ability for these spells when you cast them with this trait (choose when you select this race)."}],"lineage":"VRGR","age":null,"heightWeight":null,"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/MPMM/Yuan-ti.webp"]},{"id":"yuan-ti-pureblood-vgm","name":"Yuan-ti Pureblood","source":"VGM","page":120,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":[],"benefits":{"ability":[{"fixed":{"int":1,"cha":2}}],"proficiencies":[{"kind":"language","fixed":["common","abyssal","draconic"]}],"spells":{"ability":{"fixed":"cha"},"groups":[{"name":"","items":[{"spell":"poison-spray-phb","name":"Poison Spray","how":"known","uses":"","at":"1"},{"spell":"animal-friendship-phb","name":"Animal Friendship","how":"innate","uses":"","at":"1"},{"spell":"suggestion-phb","name":"Suggestion","how":"innate","uses":"1/day","at":"3"}]}]},"immune":{"fixed":["poison"]},"conditionImmune":{"fixed":["poisoned"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."},{"name":"Innate Spellcasting","text":"You know the poison spray cantrip. You can cast animal friendship an unlimited number of times with this trait, but you can target only snakes with it. Starting at 3rd level, you can also cast suggestion with this trait. Once you cast it, you can't do so again until you finish a long rest. Charisma is your spellcasting ability for these spells."},{"name":"Magic Resistance","text":"You have advantage on saving throws against spells and other magical effects."},{"name":"Poison Immunity","text":"You are immune to poison damage and the poisoned condition."}],"lineage":"","age":{"mature":20,"max":100},"heightWeight":{"baseHeight":56,"heightMod":"2d10","baseWeight":110,"weightMod":"2d4"},"options":[],"description":"","images":["https://raw.githubusercontent.com/5etools-mirror-3/5etools-img/main/races/VGM/Yuan-ti%20Pureblood.webp"]},{"id":"zombie-dmg","name":"Zombie","source":"DMG","page":282,"edition":"2014","size":["Medium"],"speed":{"walk":9},"creatureTypes":["undead"],"benefits":{"ability":[{"fixed":{"str":1,"con":2,"int":-6,"wis":-4,"cha":-4}}],"immune":{"fixed":["poison"]},"conditionImmune":{"fixed":["poisoned"]},"senses":[{"type":"darkvision","range":18}]},"feats":[],"traits":[{"name":"Undead Fortitude","text":"If damage reduces you to 0 hit points, you must make a Constitution saving throw with a DC of 5+the damage taken, unless the damage is radiant or from a critical hit. On a success, you drop to 1 hit point instead."},{"name":"Undead Nature","text":"You are immune to poison damage, and you can't be poisoned. You don't require air, food, drink, or sleep."},{"name":"Darkvision","text":"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray."}],"lineage":"","age":null,"heightWeight":null,"options":[],"description":""}]};
